local config = {
  ui_story_5081_50810100_1_dialog_content = "(En el viento soplando y las arenas abrasadoras, mis compañeros restantes y yo hacemos un intento desesperado de escapar...)",
  ui_story_5081_50810100_2_dialog_content = "(Detrás de nosotros surge un mar de Eclipsites...)",
  ui_story_5081_50810100_3_dialog_content = "(Y ante nosotros se encuentra un enorme castillo, símbolo de esperanza y desesperación...)",
  ui_story_5081_50810100_4_dialog_content = "(Pero ahora parece un espejismo lejano, una burbuja etérea que nunca se suponía que debía ser tocada.)",
  ui_story_5081_50810100_5_dialog_content = "¿Es este realmente el final?",
  ui_story_5081_50810100_6_dialog_content = "¡Maldita sea... Parece que esta vez no llegaré a casa! ¡Urgh!",
  ui_story_5081_50810100_7_dialog_content = "¡Chirrido! ¡No, Sork!",
  ui_story_5081_50810100_8_dialog_content = "¡Voy contigo! Somos compañeros hasta el amargo final, chirrido...",
  ui_story_5081_50810100_9_dialog_content = "¡Sork! ¡Bekk!",
  ui_story_5081_50810100_10_dialog_content = "Ahora no es el momento de lamentar a tus camaradas caídos...",
  ui_story_5081_50810100_11_dialog_content = "Odio admitirlo, pero en este momento... ¡eres nuestra última esperanza de supervivencia!",
  ui_story_5081_50810100_12_dialog_content = "¡No te detengas! ¡Sigue adelante sin importar qué!",
  ui_story_5081_50810100_13_dialog_content = "Odi!",
  ui_story_5081_50810100_14_dialog_content = "¡Continuaré con tu voluntad! Juro llegar al castillo y encontrarla...",
  ui_story_5081_50810100_15_dialog_content = "No espera, estaba a punto de decir algo genial...",
  ui_story_5081_50810100_16_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5081_50810100_17_dialog_content = "Se acabó...",
  ui_story_5081_50810100_18_dialog_content = "Lo siento todos, pero yo... no pude...",
  ui_story_5081_50810100_19_dialog_content = "...",
  ui_story_5081_50810100_20_dialog_content = "<color=#e8d9bb>¡Bip, bip!</color>",
  ui_story_5081_50810100_21_dialog_content = "¡Perdimos de nuevo!",
  ui_story_5081_50810100_22_dialog_content = "Supongo que realmente no podemos superar este nivel sin \"B\", mucho menos alcanzar ese alto rango.",
  ui_story_5081_50810100_23_dialog_content = "Pero \"B\" ya dejó su postura perfectamente clara...",
  ui_story_5081_50810100_24_dialog_content = "Tú... no te gusta jugar juegos, ¿verdad?",
  ui_story_5081_50810100_25_dialog_content = "Lo siento... ¡Nunca debí haberte molestado!",
  ui_story_5081_50810100_26_dialog_content = "Ahora que \"B\" no me soporta, ¿realmente no hay nada que podamos hacer?",
  ui_story_5081_50810100_27_dialog_content = "<color=#e8d9bb>Todo comenzó hace unos días cuando apareció una solicitud urgente de la Federación Illumina.</color>",
  ui_story_5081_50810100_28_dialog_content = "Realmente no quería venir a Illumina en este momento.",
  ui_story_5081_50810100_29_dialog_content = "Todos están tan ocupados... Parece que se avecina una gran tormenta.",
  ui_story_5081_50810100_30_dialog_content = "!",
  ui_story_5081_50810100_31_dialog_content = "¿Eh? ¿No es ese el Oficial de Inteligencia Yingel?",
  ui_story_5081_50810100_32_dialog_content = "...",
  ui_story_5081_50810100_33_dialog_content = "¡E-Ella me ignoró por completo!",
  ui_story_5081_50810100_34_dialog_content = "Se veía realmente estresada, aunque... ¿No estará en medio de otra misión secreta, verdad?",
  ui_story_5081_50810100_35_dialog_content = "Apareciste justo a tiempo, PlayerName.",
  ui_story_5081_50810100_36_dialog_content = "Oh, en realidad, acabo de llegar.",
  ui_story_5081_50810100_37_dialog_content = "Dejemos de lado las charlas. Deberías saber que esa no es la razón por la que pedí reunirme contigo esta vez.",
  ui_story_5081_50810100_38_dialog_content = "El Comité está realizando numerosos ajustes nuevos en su estructura. Naturalmente, esto ha puesto una tensión considerable en todos nuestros laboratorios de investigación y desarrollo...",
  ui_story_5081_50810100_39_dialog_content = "Decir que cada proyecto es un desastre total en este momento sería quedarse corto.",
  ui_story_5081_50810100_40_dialog_content = "Entonces... ¿me estás pidiendo ayuda?",
  ui_story_5081_50810100_41_dialog_content = "Aunque es posible que no puedas ayudar con los proyectos en sí...",
  ui_story_5081_50810100_42_dialog_content = "Tengo una tarea que se adapta perfectamente a tus habilidades.",
  ui_story_5081_50810100_43_dialog_content = "¿Cuál es la tarea?",
  ui_story_5081_50810100_44_dialog_content = "Me gustaría que investigaras el paradero de la Oficial de Tecnología Gronru. Desapareció repentinamente de su puesto hace unos días y no se la ha visto desde entonces.",
  ui_story_5081_50810100_45_dialog_content = "¿Gronru? ¿Ella ha desaparecido?",
  ui_story_5081_50810100_46_dialog_content = "Así es. Nuestras fuentes indican que ya ha abandonado Illumina, pero su paradero actual es desconocido.",
  ui_story_5081_50810100_47_dialog_content = "Estamos en medio de los tiempos difíciles de la Federación Illumina. Si se corre la voz de esto...",
  ui_story_5081_50810100_48_dialog_content = "\"¿Desertó de Illumina? ¿Podría estar trabajando con el enemigo? ¿O tal vez ha sido una espía para los Espectros todo el tiempo?\"",
  ui_story_5081_50810100_49_dialog_content = "... Es posible que cualquiera de estos rumores se propague como la pólvora.",
  ui_story_5081_50810100_50_dialog_content = "¡Eso es un poco demasiado!",
  ui_story_5081_50810100_51_dialog_content = "(De cualquier manera, debería intentar contactar a Gronru en su terminal...)",
  ui_story_5081_50810100_52_dialog_content = "Me temo que es la verdad. Dadas las circunstancias actuales, evitar este tipo de especulación pública es nuestra máxima prioridad.",
  ui_story_5081_50810100_53_dialog_content = "Ya se ha asignado a varios de nuestros propios miembros para manejar este asunto a través de los canales oficiales.",
  ui_story_5081_50810100_54_dialog_content = "De hecho, he oído que la Federación Illumina está preparada para movilizar toda su red de inteligencia continental para cazarla.",
  ui_story_5081_50810100_55_dialog_content = "Uh-oh—",
  ui_story_5081_50810100_56_dialog_content = "Entonces... ¿Qué harán con Gronru una vez que la encuentren? No la van a castigar, ¿verdad?",
  ui_story_5081_50810100_57_dialog_content = "¿Quién sabe? Después de todo, este no es mi campo de especialización.",
  ui_story_5081_50810100_58_dialog_content = "Por precaución, o quizás por miedo a crear un conflicto aún mayor, el Comité me preguntó si tenía alguna otra solución.",
  ui_story_5081_50810100_59_dialog_content = "Fue entonces cuando decidí acercarme a ti con esta misión.",
  ui_story_5081_50810100_60_dialog_content = "Necesitamos que encuentres a nuestra colega ausente y la traigas de vuelta antes de que se tomen medidas oficiales.",
  ui_story_5081_50810100_61_dialog_content = "Entiendo, pero tengo que preguntar...",
  ui_story_5081_50810100_62_dialog_content = "¿Podría ser que Gronru se fue debido a lo ocupado que está Illumina en este momento?",
  ui_story_5081_50810100_63_dialog_content = "¿Quizás el estrés la superó, por lo que necesitaba alejarse de su trabajo por un tiempo?",
  ui_story_5081_50810100_64_dialog_content = "¿Quién dice que ella no aparecerá en Illumina justo después de que me vaya?",
  ui_story_5081_50810100_65_dialog_content = "Lamentablemente, eso no es posible.",
  ui_story_5081_50810100_66_dialog_content = "La gente común nunca podría entender a Gronru cuando se trata de estrés.",
  ui_story_5081_50810100_67_dialog_content = "Esa chica siempre ha tenido un débil sentido de la moral, por lo que algo como esto nunca la haría sentir estresada.",
  ui_story_5081_50810100_68_dialog_content = "De hecho, esa es precisamente la razón por la que la pusimos a cargo de los proyectos de desarrollo más importantes de Illumina.",
  ui_story_5081_50810100_69_dialog_content = "Tienes razón. Gronru es un genio... pero aún así necesita un descanso del trabajo de vez en cuando.",
  ui_story_5081_50810100_70_dialog_content = "En cualquier caso, contamos contigo. No quieres que Gronru caiga en las arrugadas y viejas manos del Comité, ¿verdad?",
  ui_story_5081_50810100_71_dialog_content = "No tienes que decirlo de esa manera. ¡Estoy dispuesto a ayudar de todos modos!",
  ui_story_5081_50810100_72_dialog_content = "Es solo que Gronru tiene un montón de pasatiempos, lo que significa que podría estar en casi cualquier parte del mundo.",
  ui_story_5081_50810100_73_dialog_content = "Ella podría estar alimentando a las palomas en Lumopolis durante el día y luego viendo una obra en la Bahía de los Pabellones Gemelos por la noche.",
  ui_story_5081_50810100_74_dialog_content = "Viajar a todos esos lugares no será barato, especialmente para mí...",
  ui_story_5081_50810100_75_dialog_content = "No te preocupes por los costos. Hablaré con el Comité y me aseguraré de que seas debidamente compensado.",
  ui_story_5081_50810100_76_dialog_content = "Después de todo, encontrar al Oficial Técnico antes que tarde minimizará el daño a Illumina. Estoy seguro de que lo entenderán.",
  ui_story_5081_50810100_77_dialog_content = "¡Lo aprecio! Ah, hay una cosa más...",
  ui_story_5081_50810100_78_dialog_content = "Me encontré con la Oficial de Inteligencia Yingel hace un momento, y parecía realmente preocupada. Ni siquiera me saludó ni nada.",
  ui_story_5081_50810100_79_dialog_content = "¿Está ella bien?",
  ui_story_5081_50810100_80_dialog_content = "Yingel, eh... Con todo lo que ha sucedido últimamente, su posición se ha visto afectada incluso más que las demás.",
  ui_story_5081_50810100_81_dialog_content = "Es posible que se esté sumergiendo en su trabajo para evitar pensar en otros asuntos.",
  ui_story_5081_50810100_82_dialog_content = "... ¿Estás seguro de que no la están obligando a trabajar horas extras?",
  ui_story_5081_50810100_83_dialog_content = "Por el contrario, todos aquí desean que ella deje de esforzarse tanto.",
  ui_story_5081_50810100_84_dialog_content = "No importa cómo lo mires, ella es una miembro importante y talentosa de la Federación Illumina. El exceso de horas extras es tan inaceptable como abandonar su puesto sin permiso.",
  ui_story_5081_50810100_85_dialog_content = "Si tú lo dices... Supongo que todos en Illumina lo están pasando bastante mal en este momento.",
  ui_story_5081_50810100_86_dialog_content = "Solo déjame a mí encontrar a Gronru.",
  ui_story_5081_50810100_87_dialog_content = "Hemos sido amigos durante mucho tiempo, así que tengo algunas ideas sobre dónde podría estar.",
  ui_story_5081_50810100_88_dialog_content = "¡Te mantendré informado!",
  ui_story_5081_50810100_89_dialog_content = "(Enumeremos los lugares donde Gronru podría estar—)",
  ui_story_5081_50810100_90_dialog_content = "!(El lugar más probable es Umbraton, ¡la capital del entretenimiento de Astra!)",
  ui_story_5081_50810100_91_dialog_content = "¡Técnicas de vanguardia para asombrar al mundo entero! ¡El magistral trabajo del nuevo director del Teatro Dulces Sueños se revelará esta noche!",
  ui_story_5081_50810100_92_dialog_content = "¡Actuaciones que rompen el escenario! ¡Un festín suntuoso para los sentidos! ¡La reunión anual de músicos legendarios comienza hoy!",
  ui_story_5081_50810100_93_dialog_content = "... ¡Solo mira a estas multitudes!",
  ui_story_5081_50810100_94_dialog_content = "Cada lugar está lleno hasta la capacidad con visitantes. Encontrar a Gronru en este lío será como buscar una aguja en un pajar...",
  ui_story_5081_50810100_95_dialog_content = "No hay respuesta en la terminal tampoco... Parece que este juego de escondite no va a terminar pronto.",
  ui_story_5081_50810100_96_dialog_content = "¿Qué debo hacer... Eh? ¿Es eso—",
  ui_story_5081_50810100_97_dialog_content = "...",
  ui_story_5081_50810100_98_dialog_content = "¿Qué hace Rediesel Wrench aquí?",
  ui_story_5081_50810100_99_dialog_content = "¿Y por qué se escabullen así? No están aquí para causar problemas, ¿verdad?",
  ui_story_5081_50810100_100_dialog_content = "Si ahora mismo buscan pelea con las pandillas locales, las cosas solo se pondrán más difíciles para mí.",
  ui_story_5081_50810100_101_dialog_content = "Debería ir a advertirles.",
  ui_story_5081_50810201_1_dialog_content = "¡Apúrate! ¡Vamos a ponernos al día!",
  ui_story_5081_50810201_2_dialog_content = "Jeje, ¡objetivo bloqueado!",
  ui_story_5081_50810201_3_dialog_content = "Ejem—",
  ui_story_5081_50810201_4_dialog_content = "?",
  ui_story_5081_50810201_5_dialog_content = "Disculpe, pero ¿qué exactamente creen que están haciendo ustedes dos?",
  ui_story_5081_50810201_6_dialog_content = "Tsk, así que tú también estás aquí, PlayerName...",
  ui_story_5081_50810201_7_dialog_content = "¡No me digas que estás compitiendo contra nosotros!",
  ui_story_5081_50810201_8_dialog_content = "¡Vaya, si no es el jefe! ¿Quizás podamos llegar a un acuerdo?",
  ui_story_5081_50810201_9_dialog_content = "Con su ilustre nombre, tal vez podamos asegurar la prioridad para nosotros mismos.",
  ui_story_5081_50810201_10_dialog_content = "Lo siento, pero no tengo idea de lo que estás hablando.",
  ui_story_5081_50810201_11_dialog_content = "¿Estaban siguiendo a alguien hace un momento?",
  ui_story_5081_50810201_12_dialog_content = "Oh no, solo estábamos haciendo una ligera verificación de antecedentes de nuestros oponentes.",
  ui_story_5081_50810201_13_dialog_content = "Para decirlo simplemente, vinimos para evaluar la fuerza de combate de nuestros enemigos e identificar cualquier ventaja posible que puedan tener...",
  ui_story_5081_50810201_14_dialog_content = "Después de todo, es limitado. Solo aquellos con habilidades pueden arrebatárselo a otros.",
  ui_story_5081_50810201_15_dialog_content = "¿D-Deslizar algo?",
  ui_story_5081_50810201_16_dialog_content = "¡Por supuesto! ¡Solo mira a toda esta gente!",
  ui_story_5081_50810201_17_dialog_content = "¡De ninguna manera! ¡Absolutamente no! No te dejaré—",
  ui_story_5081_50810201_18_dialog_content = "¿Por qué no podemos—",
  ui_story_5081_50810201_19_dialog_content = "¡Roba de Umbraton!",
  ui_story_5081_50810201_20_dialog_content = "¡Compra ese juego!",
  ui_story_5081_50810201_21_dialog_content = "¿Ah?",
  ui_story_5081_50810201_22_dialog_content = "Entonces, déjame entender esto bien...",
  ui_story_5081_50810201_23_dialog_content = "Un nuevo juego de fantasía recién excavado está a punto de ser restaurado pronto, y ahora está en preventa en Umbraton.",
  ui_story_5081_50810201_24_dialog_content = "Pero solo tienen copias limitadas, y solo permiten que los jugadores lo compren si pasan su prueba.",
  ui_story_5081_50810201_25_dialog_content = "Así que viniste desde el desierto de Rediesel solo para pasar esta prueba y obtener una copia del juego.",
  ui_story_5081_50810201_26_dialog_content = "Y ahora estás siguiendo a otros jugadores de ideas afines para obtener una mejor comprensión de la prueba...",
  ui_story_5081_50810201_27_dialog_content = "Realmente están haciendo todo lo posible solo para comprar un videojuego, jaja...",
  ui_story_5081_50810201_28_dialog_content = "Ah... ¿Cuándo desarrollaste una visión tan cruda de la Rediesel Wrench, jefe?",
  ui_story_5081_50810201_29_dialog_content = "Supuse que después de años de amistad y lucha contra enemigos, podríamos haber tenido una comprensión mucho mejor el uno del otro.",
  ui_story_5081_50810201_30_dialog_content = "Uh... ¿Perdón?",
  ui_story_5081_50810201_31_dialog_content = "Supongo que realmente no entiendes la llave Rediesel... ¡o el valor de un juego de fantasía como este!",
  ui_story_5081_50810201_32_dialog_content = "... ¿Ese es realmente el punto aquí?",
  ui_story_5081_50810201_33_dialog_content = "Para que los Aurorianos desentierren un videojuego de las ruinas y lo restauren a su funcionamiento...",
  ui_story_5081_50810201_34_dialog_content = "¿Tienes alguna idea de cuánto trabajo conlleva eso?",
  ui_story_5081_50810201_35_dialog_content = "¿C-Cuánto cuesta?",
  ui_story_5081_50810201_36_dialog_content = "¡Reparar máquinas de juegos es la parte más fácil del proceso!",
  ui_story_5081_50810201_37_dialog_content = "Entender la codificación original y los contenidos de un juego, luego complementar cualquier parte dañada o faltante, ¡eso es increíblemente difícil!",
  ui_story_5081_50810201_38_dialog_content = "¡Y no me hagas empezar con los desafíos de traducir el antiguo idioma de un juego al Auroriano!",
  ui_story_5081_50810201_39_dialog_content = "¡Este tipo de trabajo es una de las mayores empresas de nuestro tiempo!",
  ui_story_5081_50810201_40_dialog_content = "C-Creo que lo entiendo ahora... Supongo que sacar un juego no es tan simple como pensaba...",
  ui_story_5081_50810201_41_dialog_content = "Exactamente. Además, la tecnología y la experiencia de Illumina suelen ser necesarias para trabajos de excavación y restauración a gran escala como este.",
  ui_story_5081_50810201_42_dialog_content = "¡Eso es lo que lo hace aún más impactante que un juego como este se venda primero en Umbraton!",
  ui_story_5081_50810201_43_dialog_content = "También es por eso que tenemos que conseguir una copia de la edición especial. Incluso si duplican el precio del juego, o incluso lo triplican, ¡pagaremos lo que cueste!",
  ui_story_5081_50810201_44_dialog_content = "Parece que será realmente caro entonces... ¿Estás bien con esto, Jomu?",
  ui_story_5081_50810201_45_dialog_content = "¡Por supuesto! Cuanto más caro sea ahora, más valioso será en el futuro.",
  ui_story_5081_50810201_46_dialog_content = "Si tuviera que elegir un tipo de juego favorito, sería el que hace que la gente saque su dinero a manos llenas.",
  ui_story_5081_50810201_47_dialog_content = "Así que estás dispuesto a comprar este juego de fantasía incluso <color=#FFB400>a un precio premium</color>... Casi no puedo creerlo, Jomu.",
  ui_story_5081_50810201_48_dialog_content = "Ustedes juntaron chatarra y otras partes para reconstruir un Colossus, pero de alguna manera están dispuestos a pagar buen dinero por un videojuego.",
  ui_story_5081_50810201_49_dialog_content = "Simplemente no entiendes, PlayerName.",
  ui_story_5081_50810201_50_dialog_content = "Ya te dije cuánto tiempo y esfuerzo se necesita para descubrir, desenterrar, restaurar y lanzar juegos como este...",
  ui_story_5081_50810201_51_dialog_content = "¿Crees que este tipo de trabajo puede ser realizado por cualquier estudio mediocre con recursos mínimos?",
  ui_story_5081_50810201_52_dialog_content = "Supongo que no.",
  ui_story_5081_50810201_53_dialog_content = "Dime, ¿qué crees que es el aspecto más importante de un videojuego?",
  ui_story_5081_50810201_54_dialog_content = "¿Su... jugabilidad?",
  ui_story_5081_50810201_55_dialog_content = "¡Equivocado! ¡Son los jugadores!",
  ui_story_5081_50810201_56_dialog_content = "Si haces algo despreciable, como obligar a profesionales a desarrollar tus juegos o robar versiones de edición limitada...",
  ui_story_5081_50810201_57_dialog_content = "¡Serás excluido por toda la comunidad de jugadores!",
  ui_story_5081_50810201_58_dialog_content = "No importa cuán maravilloso sea el juego que tienes, nadie estará cerca para compartir su alegría.",
  ui_story_5081_50810201_59_dialog_content = "¡Es el resultado más trágico imaginable para cualquier jugador! ¿No lo entiendes?",
  ui_story_5081_50810201_60_dialog_content = "¡Así es! ¡Incluso un juego como Tetrablox es más divertido cuando se unen dos personas!",
  ui_story_5081_50810201_61_dialog_content = "Además, hay muchas personas notables dentro de la comunidad de juegos, personas a las que definitivamente no quieres ofender.",
  ui_story_5081_50810201_62_dialog_content = "Especialmente porque podrían estar en el mercado buscando muchos periféricos de juegos nuevos... Jejeje.",
  ui_story_5081_50810201_63_dialog_content = "¿Jugadores, eh...",
  ui_story_5081_50810201_64_dialog_content = "Estoy bastante seguro de que hay muchos de esos en Rediesel Wrench, ¿verdad?",
  ui_story_5081_50810201_65_dialog_content = "Deben estar sin juegos para jugar si están dispuestos a venir hasta Umbraton por ellos...",
  ui_story_5081_50810201_66_dialog_content = "¡Oye! Aclaremos algo aquí: somos perfectamente capaces de desenterrar máquinas de juegos y cartuchos por nosotros mismos!",
  ui_story_5081_50810201_67_dialog_content = "¡Pero esos torpes idiotas no tienen idea de cómo cuidar adecuadamente las cosas, por lo que nuestras cosas se dañan todo el tiempo!",
  ui_story_5081_50810201_68_dialog_content = "¿Crees que puedo arreglar este tipo de lío yo solo? No, absolutamente no...",
  ui_story_5081_50810201_69_dialog_content = "Si pudiera llevarme a unos cuantos científicos de Illumina conmigo, ¡apuesto a que podría crear un juego que conquistaría al mundo entero!",
  ui_story_5081_50810201_70_dialog_content = "Espera, creo que podría conocer al científico de Illumina perfecto para el trabajo...",
  ui_story_5081_50810201_71_dialog_content = "¡Ah! Me distraje hablando con ustedes y casi lo olvido!",
  ui_story_5081_50810201_72_dialog_content = "(Me pregunto si la desaparición de Gronru tiene algo que ver con la preventa de este juego de fantasía?)",
  ui_story_5081_50810201_73_dialog_content = "(El momento no podría ser más perfecto...)",
  ui_story_5081_50810201_74_dialog_content = "(Empezar mi búsqueda con este juego no es una mala elección en absoluto. Ahora bien...)",
  ui_story_5081_50810201_75_dialog_content = "Hmm... ¿Podrías decirme dónde están vendiendo este juego?",
  ui_story_5081_50810201_76_dialog_content = "¡Pero por supuesto, mi querido amigo! Incluso te daré un descuento del veinte por ciento por esa información—",
  ui_story_5081_50810201_77_dialog_content = "Colmillos ocultos.",
  ui_story_5081_50810201_78_dialog_content = "Bueno...",
  ui_story_5081_50810201_79_dialog_content = "¡Sí, eso es correcto—Colmillos Ocultos!",
  ui_story_5081_50810201_80_dialog_content = "¡Un paraíso para todos los jugadores en Astra! ¡La única y suprema sala de juegos de Umbraton!",
  ui_story_5081_50810201_81_dialog_content = "Todavía no te voy a pagar por esa información, ya sabes...",
  ui_story_5081_50810201_82_dialog_content = "También es un lugar de encuentro para jugadores de alto nivel. La mayoría, si no todos, los récords de videojuegos de Astra se han establecido allí.",
  ui_story_5081_50810201_83_dialog_content = "... Suena como un verdadero salón de la fama, supongo.",
  ui_story_5081_50810201_84_dialog_content = "(Me pregunto si alguna de las puntuaciones altas de Gronru están registradas allí?)",
  ui_story_5081_50810201_85_dialog_content = "(¡Definitivamente estás en el camino correcto ahora, Caelestite! ¡Sigue así!)",
  ui_story_5081_50810201_86_dialog_content = "Desafortunadamente, probablemente no podrás asegurar una copia incluso si agregas tu nombre a la lista en este momento.",
  ui_story_5081_50810201_87_dialog_content = "¿Eh? Pero pensé que esto era una preventa. ¿Se suponía que debía reservar un lugar en la lista de espera?",
  ui_story_5081_50810201_88_dialog_content = "No tiene nada que ver con la lista de espera...",
  ui_story_5081_50810201_89_dialog_content = "Los cartuchos de videojuegos son extremadamente valiosos, por lo que la sala de juegos está realizando una revisión estricta de cualquier comprador potencial.",
  ui_story_5081_50810201_90_dialog_content = "Todo es para evitar que los revendedores y otros actores malintencionados se involucren, de modo que los verdaderos jugadores tengan la oportunidad de disfrutar del juego.",
  ui_story_5081_50810201_91_dialog_content = "No es de extrañar que Jomu se vea tan nervioso al respecto.",
  ui_story_5081_50810201_92_dialog_content = "Ja, muy gracioso, jefe. Marca mis palabras: ¡Ganaré el derecho de comprar una copia de \"B\" de manera justa y cuadrada!",
  ui_story_5081_50810201_93_dialog_content = "\"¿B\"?",
  ui_story_5081_50810201_94_dialog_content = "Así es. El paso más crucial para asegurar una copia de este juego es jugar contra \"B\".",
  ui_story_5081_50810201_95_dialog_content = "Como propietaria de Hidden Fangs, también es una de las mejores jugadoras de Astra...",
  ui_story_5081_50810201_96_dialog_content = "Así es como \"B\" te prueba para ver si tu amor por los videojuegos es real o no.",
  ui_story_5081_50810201_97_dialog_content = "No creo que un novato como tú pueda manejarlo.",
  ui_story_5081_50810201_98_dialog_content = "¿Q-Q-Qué estás diciendo? ¡Yo también he jugado un montón de juegos!",
  ui_story_5081_50810201_99_dialog_content = "Jejeje. Solo tendré que contarte un poco más sobre \"B\", para que puedas revolcarte en la desesperación...",
  ui_story_5081_50810301_1_dialog_content = "<color=#e8d9bb>Un cuerpo hecho completamente de juegos.</color>",
  ui_story_5081_50810301_2_dialog_content = "<color=#e8d9bb>Con una computadora por corazón, y datos por sangre.</color>",
  ui_story_5081_50810301_3_dialog_content = "<color=#e8d9bb>Ella ha jugado miles de juegos sin perder ni una sola vez.</color>",
  ui_story_5081_50810301_4_dialog_content = "<color=#e8d9bb>Su existencia es un misterio tanto para Aurorianos como para Eclipsites.</color>",
  ui_story_5081_50810301_5_dialog_content = "<color=#e8d9bb>La mayoría de los días, ella se esconde en los rincones más oscuros de la sala de juegos, murmurando para sí misma sobre ser inútil.</color>",
  ui_story_5081_50810301_6_dialog_content = "<color=#e8d9bb>Solo tiene un deseo en la vida: ¡una cantidad infinita de juegos para jugar!</color>",
  ui_story_5081_50810301_7_dialog_content = "...",
  ui_story_5081_50810301_8_dialog_content = "¡Basta ya! ¡La historia se vuelve cada vez más y más loca!",
  ui_story_5081_50810301_9_dialog_content = "Entonces, para decirlo simplemente... ¿\"B\" es un jugador que ha jugado innumerables juegos y no ha perdido ni una sola vez?",
  ui_story_5081_50810301_10_dialog_content = "Para ser más preciso—",
  ui_story_5081_50810301_11_dialog_content = "Tiene algunos de los récords de eliminación más rápidos y las puntuaciones más altas en todo Astra, y también es la jugadora de Tetrablox más famosa de todos los tiempos.",
  ui_story_5081_50810301_12_dialog_content = "También sigue estableciendo récords en el modo infinito de Tetrablox. Algunos incluso dicen que ha llegado al último nivel del juego...",
  ui_story_5081_50810301_13_dialog_content = "¿Realmente un juego así puede tener un nivel final?",
  ui_story_5081_50810301_14_dialog_content = "Por lo que he oído, el juego se congela una vez que superas cierto número de niveles...",
  ui_story_5081_50810301_15_dialog_content = "De cualquier manera, no es algo que un Aurorian ordinario podría hacer jamás.",
  ui_story_5081_50810301_16_dialog_content = "¿Es ella algún tipo de monstruo de juego surgido de las profundidades más profundas de las ruinas antiguas? ¡Muy bien podría serlo!",
  ui_story_5081_50810301_17_dialog_content = "Cálmate, ya lo entiendo. Ella es realmente buena en los videojuegos...",
  ui_story_5081_50810301_18_dialog_content = "En cualquier caso, muchos desafiantes han ido a Colmillos Ocultos en busca de \"B\", ¡solo para alejarse cojeando en derrota!",
  ui_story_5081_50810301_19_dialog_content = "En realidad, solo quiero preguntar por alguna información. ¡No estoy interesado en desafiar a \"B\" en absoluto!",
  ui_story_5081_50810301_20_dialog_content = "Esta persona tampoco parece muy accesible...",
  ui_story_5081_50810301_21_dialog_content = "¡No te preocupes, jefe! Estaré más que feliz de preguntar en tu nombre, ¡y con un descuento del cinco por ciento—",
  ui_story_5081_50810301_22_dialog_content = "Estarás bien, ¡así que solo ve allí y compruébalo por ti mismo! Hay todo tipo de jugadores allí, verás.",
  ui_story_5081_50810301_23_dialog_content = "Gracias chicos. ¡Guía el camino!",
  ui_story_5081_50810301_24_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5081_50810301_25_dialog_content = "... ¿Es realmente este el lugar?",
  ui_story_5081_50810301_26_dialog_content = "¡Es mucho más cómodo de lo que pensé que sería!",
  ui_story_5081_50810301_27_dialog_content = "Incluso estoy sintiendo una sensación de nostalgia, como si estuviera a punto de sentarme a jugar uno de mis juegos favoritos.",
  ui_story_5081_50810301_28_dialog_content = "Es solo una sala de juegos, ya sabes. ¿Cómo pensaste que sería?",
  ui_story_5081_50810301_29_dialog_content = "¿En serio me preguntas eso después de esa loca descripción que me diste?",
  ui_story_5081_50810301_30_dialog_content = "Como mínimo, pensé que estaría lleno de gángsters de Umbraton o algo así...",
  ui_story_5081_50810301_31_dialog_content = "¡Apuesto a que el dueño de esta acogedora tiendita debe ser alguien que realmente ama la vida!",
  ui_story_5081_50810301_32_dialog_content = "...",
  ui_story_5081_50810301_33_dialog_content = "¿Ah?",
  ui_story_5081_50810301_34_dialog_content = "!",
  ui_story_5081_50810301_35_dialog_content = "No sé sobre la vida, pero definitivamente le encantan los juegos...",
  ui_story_5081_50810301_36_dialog_content = "¿Mmm? ¿Qué te pasa, PlayerName? Parece que algo te molesta.",
  ui_story_5081_50810301_37_dialog_content = "Por alguna razón... siento que alguien me está observando.",
  ui_story_5081_50810301_38_dialog_content = "Solo estás imaginando cosas. Después de todo, la iluminación aquí no es muy brillante.",
  ui_story_5081_50810301_39_dialog_content = "Además, todos están demasiado ocupados jugando para notarte...",
  ui_story_5081_50810301_40_dialog_content = "Tienes razón, supongo que solo me estoy preocupando por nada.",
  ui_story_5081_50810301_41_dialog_content = "Entonces, ¿dónde está el dueño de la sala de juegos? Para algo tan importante como la preventa de un juego, apenas hay publicidad al respecto.",
  ui_story_5081_50810301_42_dialog_content = "¿Podría estar probando a alguien para ver si es digno de comprar el juego?",
  ui_story_5081_50810301_43_dialog_content = "No te preocupes, jefe. La dueña es una persona muy apasionada, y estoy seguro de que te responderá si la llamas, por supuesto, en voz alta.",
  ui_story_5081_50810301_44_dialog_content = "Vale, eh... ¡Disculpe! ¿Puedo hablar con \"B\", por favor?",
  ui_story_5081_50810301_45_dialog_content = "?",
  ui_story_5081_50810301_46_dialog_content = "¿Es ese un nuevo retador?",
  ui_story_5081_50810301_47_dialog_content = "Espera, creo que he visto ese atuendo antes... ¿No es una persona famosa?",
  ui_story_5081_50810301_48_dialog_content = "¡Sí! ¡Esto será increíble!",
  ui_story_5081_50810301_49_dialog_content = "¡Me tendiste una trampa, Jomu!",
  ui_story_5081_50810301_50_dialog_content = "Lo siento, jefe, pero como no pagaste por mi información, tuve que pensar en otra forma de cobrar mi compensación. ¡Buena suerte!",
  ui_story_5081_50810301_51_dialog_content = "...",
  ui_story_5081_50810301_52_dialog_content = "Tienes mucho valor, pidiendo a \"B\" de esa manera...",
  ui_story_5081_50810301_53_dialog_content = "¡Bienvenido a Hidden Fangs! ¡Espero que estés listo para un desafío!",
  ui_story_5081_50810301_54_dialog_content = "... ¿Ah?",
  ui_story_5081_50810301_55_dialog_content = "¿Oh? ¡Bueno, si no es PlayerName!",
  ui_story_5081_50810301_56_dialog_content = "Es PlayerName, chirp!",
  ui_story_5081_50810301_57_dialog_content = "¿Sork? ¿Bekk?",
  ui_story_5081_50810301_58_dialog_content = "¿Qué están haciendo ustedes dos aquí?",
  ui_story_5081_50810301_59_dialog_content = "¡Esa es mi línea, amigo! ¿Qué eres tú... ¡Oye! Jomu también está aquí!",
  ui_story_5081_50810301_60_dialog_content = "Deja de esconderte detrás de PlayerName, ¡vagabundo! Devuélveme el dinero que me debes, o si no...",
  ui_story_5081_50810301_61_dialog_content = "¡Sálvame, jefe!",
  ui_story_5081_50810301_62_dialog_content = "De ninguna manera, especialmente después de que me tendiste una trampa así...",
  ui_story_5081_50810301_63_dialog_content = "Bueno... Desafortunadamente, solo traje suficiente dinero para comprar este juego hoy, ya ves.",
  ui_story_5081_50810301_64_dialog_content = "Como empleado de esta tienda, seguramente no querrías que me vaya con las manos vacías, ¿verdad?",
  ui_story_5081_50810301_65_dialog_content = "¿Sork trabaja aquí?",
  ui_story_5081_50810301_66_dialog_content = "Él acaba de darte la bienvenida como a un empleado, ¿verdad?",
  ui_story_5081_50810301_67_dialog_content = "Bueno... Es una larga historia.",
  ui_story_5081_50810301_68_dialog_content = "Originalmente, Bekk y yo fuimos contratados para comprar algunos juegos nuevos para un cliente aquí en Umbraton.",
  ui_story_5081_50810301_69_dialog_content = "Pero al final, nos estafó un vendedor sospechoso y terminamos con un montón de cartuchos basura.",
  ui_story_5081_50810301_70_dialog_content = "Sin dinero y sin negocios que completar, decidimos pasar la noche en esta sala de juegos...",
  ui_story_5081_50810301_71_dialog_content = "¿Así que el dueño tuvo la amabilidad de ofrecerles trabajos mientras están aquí?",
  ui_story_5081_50810301_72_dialog_content = "¿Amable? Jeje, más bien curioso.",
  ui_story_5081_50810301_73_dialog_content = "La dueña quería ver qué tan bien Bekk y yo trabajamos juntos, así que nos invitó a jugar un juego.",
  ui_story_5081_50810301_74_dialog_content = "Si ganamos, ella cubriría todas nuestras pérdidas. Si perdemos, tendríamos que trabajar para ella.",
  ui_story_5081_50810301_75_dialog_content = "¡Rayos! Estábamos tan cerca de ganar también...",
  ui_story_5081_50810301_76_dialog_content = "¡Perdimos por un pelo, chirrido!",
  ui_story_5081_50810301_77_dialog_content = "¿Ustedes dos \"perdieron por un pelo\"? ¡Ja, no me hagas reír!",
  ui_story_5081_50810301_78_dialog_content = "Si estamos hablando de \"B\" aquí, ¡probablemente los aplastó a todos ustedes en el suelo!",
  ui_story_5081_50810301_79_dialog_content = "¿Qué? ¿Cómo supiste que ella usaba sus pies? Así es como pudo usar dos controles al mismo tiempo...",
  ui_story_5081_50810301_80_dialog_content = "¡Nos golpeó usando sus manos y pies al mismo tiempo!",
  ui_story_5081_50810301_81_dialog_content = "¿E-Ella lo hizo?",
  ui_story_5081_50810301_82_dialog_content = "De todos modos, una cosa llevó a la otra, y ahora ambos trabajamos aquí...",
  ui_story_5081_50810301_83_dialog_content = "Cuando no está ocupado, incluso llegamos a jugar juegos de mesa con nuestros clientes.",
  ui_story_5081_50810301_84_dialog_content = "Las personas pueden sumergirse completamente en los juegos de estrategia aquí, eso no es algo que puedas encontrar en la mayoría de los lugares...",
  ui_story_5081_50810301_85_dialog_content = "¡Aunque los juegos de negociación son mucho mejores, chirp!",
  ui_story_5081_50810301_86_dialog_content = "Entonces, ustedes dos también se ven atrapados en los juegos aquí, ¿eh?",
  ui_story_5081_50810301_87_dialog_content = "Realmente hay algo especial en este lugar... pero ¿por qué no he visto al dueño de la tienda en ninguna parte?",
  ui_story_5081_50810301_88_dialog_content = "\"B\" tiene una rara ascendencia demi-humana, al igual que nosotros. No es fácil para ella salir durante el día.",
  ui_story_5081_50810301_89_dialog_content = "Ella también tuvo que lidiar con muchos problemas en el pasado debido a su ascendencia. Así que, por favor...",
  ui_story_5081_50810301_90_dialog_content = "Solo trata de entender.",
  ui_story_5081_50810301_91_dialog_content = "¡Lo entiendo totalmente!",
  ui_story_5081_50810301_92_dialog_content = "Solo tengo algo que preguntarle, eso es todo. ¿Te gustaría pasarle un mensaje?",
  ui_story_5081_50810301_93_dialog_content = "Por supuesto, PlayerName.",
  ui_story_5081_50810301_94_dialog_content = "Solo déjame terminar este juego... quiero decir, lidiar con estos clientes, y me pondré en ello de inmediato.",
  ui_story_5081_50810301_95_dialog_content = "Seguro.",
  ui_story_5081_50810301_96_dialog_content = "¿Eh? Me pregunto adónde fueron Odi y Jomu...",
  ui_story_5081_50810301_97_dialog_content = "¿Estás bromeando? ¡Se me ocurrieron montones de nuevas estrategias solo para poder ganar mi copia del juego!",
  ui_story_5081_50810301_98_dialog_content = "Mira, incluso modifiqué mi propio controlador... ¡Échale un vistazo si quieres!",
  ui_story_5081_50810301_99_dialog_content = "¡Eso es tan cool!",
  ui_story_5081_50810301_100_dialog_content = "Perdona amigo, ¿te gustaría jugar unas cuantas rondas de Rediesel Hold 'em conmigo? ¡Creo que podríamos estar bastante igualados!",
  ui_story_5081_50810301_101_dialog_content = "Pero de donde vengo, el perdedor generalmente cubre los gastos del ganador por el resto del día. ¿Interesado?",
  ui_story_5081_50810301_102_dialog_content = "¡Claro, estoy en el juego!",
  ui_story_5081_50810301_103_dialog_content = "Todos parecen estar divirtiéndose mucho.",
  ui_story_5081_50810301_104_dialog_content = "Debería tocar algo también, para no sobresalir tanto...",
  ui_story_5081_50810301_105_dialog_content = "Hmm, qué elegir...",
  ui_story_5081_50810301_106_dialog_content = "Este parece bastante divertido. Aurora All-Star Racing, debería ser bastante bueno en juegos de conducción, ¿verdad?",
  ui_story_5081_50810301_107_dialog_content = "¡Supongo que será mejor que introduzca una muestra y averigüe!",
  ui_story_5081_50810301_108_dialog_content = "¡Guau, mira todas estas opciones de vehículos! ¡Incluso puedo elegir armas también!",
  ui_story_5081_50810301_109_dialog_content = "Bien, creo que ya le he agarrado la onda. ¡Vamos!",
  ui_story_5081_50810301_110_dialog_content = "<color=#e8d9bb>Aunque los gráficos del juego son bastante simples, los jugadores aún sienten como si hubieran sido transportados a un nuevo mundo.</color>",
  ui_story_5081_50810301_111_dialog_content = "<color=#e8d9bb>Las imágenes detalladas, junto con su presentación exagerada y efectos de sonido especiales, crean una experiencia inmersiva.</color>",
  ui_story_5081_50810301_112_dialog_content = "¿Es así como se supone que debo tomar las curvas? ¡Lo entiendo totalmente ahora!",
  ui_story_5081_50810301_113_dialog_content = "Recojo Lumina cada vez que derrapo en una esquina, ¿se supone que debo dispararlo a los Eclipsites? ¡Supongo que será mejor que lo intente!",
  ui_story_5081_50810301_114_dialog_content = "Espera... Este Eclipsite es un poco demasiado fuerte, ¿no es así?",
  ui_story_5081_50810301_115_dialog_content = "Uh-oh... ¿Por qué no puedo ver las estelas de Lumina?",
  ui_story_5081_50810301_116_dialog_content = "Oh, hombre... ¡Este juego no incluye la habilidad más fuerte de los Celestitas! ¡Es totalmente injusto!",
  ui_story_5081_50810301_117_dialog_content = "En realidad, este es el aspecto más <color=#FFB400>justo</color> del juego.",
  ui_story_5081_50810301_118_dialog_content = "¿Ah?",
  ui_story_5081_50810301_119_dialog_content = "<color=#e8d9bb>¡El jugador 2 ha entrado al juego!</color>",
  ui_story_5081_50810301_120_dialog_content = "¿Otro jugador... se ha unido a mi juego?",
  ui_story_5081_50810301_121_dialog_content = "... ¡N-No me mires!",
  ui_story_5081_50810301_122_dialog_content = "Solo mantén tus ojos en tu pantalla, o te estrellarás.",
  ui_story_5081_50810301_123_dialog_content = "¡Lo siento!",
  ui_story_5081_50810301_124_dialog_content = "Es mi primera vez jugando, así que pido disculpas si te estorbo...",
  ui_story_5081_50810301_125_dialog_content = "No te preocupes, te mostraré cómo jugar.",
  ui_story_5081_50810301_126_dialog_content = "Tienes mucho potencial. Concéntrate y no debería haber problema.",
  ui_story_5081_50810301_127_dialog_content = "E-Está bien entonces...",
  ui_story_5081_50810301_128_dialog_content = "<color=#e8d9bb>¡Advertencia! ¡Advertencia! ¡Una gran ola de Eclipsites se acerca!</color>",
  ui_story_5081_50810301_129_dialog_content = "Prepárate, vamos a hacer esto juntos.",
  ui_story_5081_50810301_130_dialog_content = "¡Entendido!",
  ui_story_5081_50810302_1_dialog_content = "?",
  ui_story_5081_50810302_2_dialog_content = "¿T-Todavía estoy vivo?",
  ui_story_5081_50810302_3_dialog_content = "¡No puedo creer que hayamos salido de esa horda de Eclipsites!",
  ui_story_5081_50810302_4_dialog_content = "¿Esto significa que estoy cerca de despejar la etapa?",
  ui_story_5081_50810302_5_dialog_content = "... ¿Te divertiste?",
  ui_story_5081_50810302_6_dialog_content = "¿Diversión? ¡Por supuesto que fue divertido! Simplemente no creo que podría haber jugado tanto tiempo sin tu ayuda.",
  ui_story_5081_50810302_7_dialog_content = "Eso no es necesariamente cierto. Tendrás que confiar en ti mismo para la próxima parte... pero estoy seguro de que estarás bien.",
  ui_story_5081_50810302_8_dialog_content = "¿Ah?",
  ui_story_5081_50810302_9_dialog_content = "<color=#e8d9bb>¡El jugador 2 ha abandonado el juego!</color>",
  ui_story_5081_50810302_10_dialog_content = "¿Te vas así como así?",
  ui_story_5081_50810302_11_dialog_content = "... ¡Te dije que no me miraras! ¡Ojos en la pantalla!",
  ui_story_5081_50810302_12_dialog_content = "¡Correcto! No puedo permitirme perder la concentración ahora...",
  ui_story_5081_50810302_13_dialog_content = "¡Ya me ayudaste a superar la parte más difícil, así que ahora depende de mí terminar el resto!",
  ui_story_5081_50810302_14_dialog_content = "¡Puedo manejar lo que sea que este juego me lance! Giros bruscos, Eclipsites, ¡lo que sea!",
  ui_story_5081_50810302_15_dialog_content = "¿Oh? No me di cuenta de que también estabas jugando, PlayerName... ¡y pareces bastante animado!",
  ui_story_5081_50810302_16_dialog_content = "Espera, esta es la etapa de Tempest Gorge, ¿no es así? Sé que no tienes idea de lo difícil que es esta carrera, pero intenta no perder de inmediato...",
  ui_story_5081_50810302_17_dialog_content = "¡Guau! Ven a ver, Odi. ¡Ya superó las cinco curvas consecutivas en Tempest Gorge!",
  ui_story_5081_50810302_18_dialog_content = "¡Imposible! Ni siquiera yo pude superar esa ola de Eclipsites... ¡Me niego a aceptar esto!",
  ui_story_5081_50810302_19_dialog_content = "¡Guau! ¡Echale un vistazo a esto, todos!",
  ui_story_5081_50810302_20_dialog_content = "¿Eh? ¿Por qué todos de repente se están reuniendo a mi alrededor?",
  ui_story_5081_50810302_21_dialog_content = "<color=#e8d9bb>Bajo la mirada ansiosa de todos, despejar el escenario de repente se vuelve aún más difícil.</color>",
  ui_story_5081_50810302_22_dialog_content = "<color=#e8d9bb>Pero al final, la sala de juegos estalla en vítores cuando la carrera llega a una emocionante y exitosa conclusión.</color>",
  ui_story_5081_50810302_23_dialog_content = "¡Wow!",
  ui_story_5081_50810302_24_dialog_content = "¿Un novato pasó el Desfiladero de la Tempestad en su primer intento? ¿Cómo es eso posible?",
  ui_story_5081_50810302_25_dialog_content = "¡Apuesto a que este tipo es en realidad un jugador profesional!",
  ui_story_5081_50810302_26_dialog_content = "¿De dónde diablos vienes, chico nuevo? ¿Estás aquí para presumir de tus habilidades?",
  ui_story_5081_50810302_27_dialog_content = "¿E-Esta etapa es realmente tan difícil?",
  ui_story_5081_50810302_28_dialog_content = "No se equivoquen, ¡todos! No soy nada especial, y esta es mi primera vez aquí. Además, tuve mucha ayuda de otro jugador...",
  ui_story_5081_50810302_29_dialog_content = "Cuando estaba luchando para pasar por esas curvas cerradas, ella estaba sentada justo al lado... ¿Eh?",
  ui_story_5081_50810302_30_dialog_content = "¿En serio? Porque no veo a nadie.",
  ui_story_5081_50810302_31_dialog_content = "¡Ella estaba aquí hace un segundo!",
  ui_story_5081_50810302_32_dialog_content = "Un pequeño Aurorian... que parecía no estar totalmente despierto...",
  ui_story_5081_50810302_33_dialog_content = "Creo que podría ser una semi-humana murciélago, y su cabello parecía un poco como las luces en la sala de juegos...",
  ui_story_5081_50810302_34_dialog_content = "Je... ¿Tienes alguna idea de a quién acabas de describir?",
  ui_story_5081_50810302_35_dialog_content = "¡Chirrido! ¡Un pequeño murciélago semi-humano!",
  ui_story_5081_50810302_36_dialog_content = "¡Eso suena mucho como Batia, la dueña de la sala de juegos!",
  ui_story_5081_50810401_1_dialog_content = "...",
  ui_story_5081_50810401_2_dialog_content = "Se siente como si estuviera esperando ser entrevistado...",
  ui_story_5081_50810401_3_dialog_content = "No te veas tan desconcertado. Si \"B\" estaba dispuesta a jugar contigo, definitivamente significa que llamaste su atención.",
  ui_story_5081_50810401_4_dialog_content = "Podría llamarla si te gustaría.",
  ui_story_5081_50810401_5_dialog_content = "No vamos a obtener más pre-pedidos hoy si no conseguimos nuevos desafiantes.",
  ui_story_5081_50810401_6_dialog_content = "¡Eso significa que tendremos que seguir trabajando aquí, chirrido!",
  ui_story_5081_50810401_7_dialog_content = "Entiendo. ¡Hagámoslo!",
  ui_story_5081_50810401_8_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5081_50810401_9_dialog_content = "... Vaya.",
  ui_story_5081_50810401_10_dialog_content = "... Mmm.",
  ui_story_5081_50810401_11_dialog_content = "... Uf.",
  ui_story_5081_50810401_12_dialog_content = "Discúlpame...",
  ui_story_5081_50810401_13_dialog_content = "Uh... ¡Sip!",
  ui_story_5081_50810401_14_dialog_content = "... ¿Hubo algo malo en mi saludo hace un momento?",
  ui_story_5081_50810401_15_dialog_content = "<size=30>(... ¿O tal vez se supone que debo comunicarme con ella en términos de arcade?)</size>",
  ui_story_5081_50810401_16_dialog_content = "No... Mmm...",
  ui_story_5081_50810401_17_dialog_content = "!",
  ui_story_5081_50810401_18_dialog_content = "¿N-Necesitabas... algo de mí?",
  ui_story_5081_50810401_19_dialog_content = "Realmente, no es nada especial.",
  ui_story_5081_50810401_20_dialog_content = "Soy un Caelestita, y mi nombre es el mismo que el que usé en el juego.",
  ui_story_5081_50810401_21_dialog_content = "Vine aquí buscando a alguien. ¿Podrías decirme si has visto...",
  ui_story_5081_50810401_22_dialog_content = "¡No lo he hecho! Definitivamente no acogo a niños cuando huyen de casa y les dejo jugar videojuegos aquí!",
  ui_story_5081_50810401_23_dialog_content = "T-T-Tú tienes el lugar equivocado... ¡Lo juro!",
  ui_story_5081_50810401_24_dialog_content = "¿Eh? ¿Realmente parezco un padre disgustado para ti?",
  ui_story_5081_50810401_25_dialog_content = "Oh, supongo que no...",
  ui_story_5081_50810401_26_dialog_content = "¡Eso es porque no lo soy! ¡Vine buscando a alguien que parece realmente joven pero en realidad es mucho mayor de lo que parece! ¡Es una de las mejores científicas de Illumina!",
  ui_story_5081_50810401_27_dialog_content = "Recientemente, abandonó todas sus importantes responsabilidades de laboratorio y desapareció sin ninguna explicación.",
  ui_story_5081_50810401_28_dialog_content = "Realmente disfruta de los videojuegos, así que pensé que este sería un buen lugar para comenzar a buscar...",
  ui_story_5081_50810401_29_dialog_content = "Su nombre es Gronru. ¿Sabes algo sobre ella?",
  ui_story_5081_50810401_30_dialog_content = "Yo no.",
  ui_story_5081_50810401_31_dialog_content = "E-Es eso así...",
  ui_story_5081_50810401_32_dialog_content = "(Esa fue una respuesta tan rápida... un poco demasiado rápida, si me preguntas.)",
  ui_story_5081_50810401_33_dialog_content = "(¿Está tratando de evitar causar un escándalo? Tiene sentido, considerando que se supone que este es un paraíso para todos los jugadores... Espera, jugadores...)",
  ui_story_5081_50810401_34_dialog_content = "¡Lo siento! Creo que hice la pregunta equivocada.",
  ui_story_5081_50810401_35_dialog_content = "Probablemente las personas aquí se identifican por sus nombres de jugador, ¿no es así?",
  ui_story_5081_50810401_36_dialog_content = "¿Cómo se llamaba el jugador de Gronru de nuevo? ¡Así es! ¡Se hace llamar Gronkenstein Ruu! ¿Has oído hablar de ella?",
  ui_story_5081_50810401_37_dialog_content = "¿Gronken qué?",
  ui_story_5081_50810401_38_dialog_content = "¡Gronkenstein Ruu!",
  ui_story_5081_50810401_39_dialog_content = "¿Grompen... Stein?",
  ui_story_5081_50810401_40_dialog_content = "No, Gronkenst—¡ay! ¡Me mordí la lengua!",
  ui_story_5081_50810401_41_dialog_content = "De todos modos... No conozco a ningún científico famoso.",
  ui_story_5081_50810401_42_dialog_content = "He tenido muchos jugadores que vienen a mi tienda últimamente... Es algo imposible... recordar todos sus nombres.",
  ui_story_5081_50810401_43_dialog_content = "Lo siento, pero... no creo que pueda ser de mucha ayuda.",
  ui_story_5081_50810401_44_dialog_content = "Espera, déjame pensar. Podría haber otra pista que pueda usar aquí...",
  ui_story_5081_50810401_45_dialog_content = "Tú... no te gusta jugar juegos, ¿verdad?",
  ui_story_5081_50810401_46_dialog_content = "¿Ah?",
  ui_story_5081_50810401_47_dialog_content = "No viniste aquí para jugar... Viniste a buscar a alguien.",
  ui_story_5081_50810401_48_dialog_content = "Cuando nos unimos en Aurora All-Star Racing y superamos la Garganta Tempest...",
  ui_story_5081_50810401_49_dialog_content = "No era diferente a ahora. No querías destacar, así que sentías que tenías que jugar, ¿verdad?",
  ui_story_5081_50810401_50_dialog_content = "Lo siento... ¡Nunca debí haberte molestado!",
  ui_story_5081_50810401_51_dialog_content = "¡O-Oye! No digas eso.",
  ui_story_5081_50810401_52_dialog_content = "¡Me estaba divirtiendo muchísimo cuando estábamos jugando juntos hace un momento! ¡Fue súper emocionante!",
  ui_story_5081_50810401_53_dialog_content = "Pero una vez que me calmo, recuerdo lo importante que es mi misión y tengo que volver a la tarea que tengo entre manos. Por eso...",
  ui_story_5081_50810401_54_dialog_content = "...",
  ui_story_5081_50810401_55_dialog_content = "¿La asusté porque estaba demasiado enfocado en mi misión?",
  ui_story_5081_50810401_56_dialog_content = "Deberías intentar hablar con ella de nuevo. Andar decaído no te hará ningún bien.",
  ui_story_5081_50810401_57_dialog_content = "Deberías saber cómo acercarte a ella ahora. Después de todo, su pasatiempo es bastante obvio.",
  ui_story_5081_50810401_58_dialog_content = "¿Te refieres a los videojuegos...",
  ui_story_5081_50810401_59_dialog_content = "Y aunque no sea para acercarte a ella de nuevo, acabas de mencionar el nombre del jugador de Gronru, ¿no es así?",
  ui_story_5081_50810401_60_dialog_content = "¿Por qué no juegas un par de juegos y ves si su nombre aparece en la tabla de clasificación?",
  ui_story_5081_50810401_61_dialog_content = "Eso debería decirte si ella ha estado aquí recientemente o no.",
  ui_story_5081_50810401_62_dialog_content = "¡Ya veo! ¡Es una gran idea, Odi!",
  ui_story_5081_50810401_63_dialog_content = "Además, como acabas de superar el Desfiladero de la Tempestad, quiero ver si tus habilidades son auténticas.",
  ui_story_5081_50810401_64_dialog_content = "¡Cubriré las fichas, así que ven a jugar unos partidos conmigo!",
  ui_story_5081_50810401_65_dialog_content = "Claro, ya voy.",
  ui_story_5081_50810401_66_dialog_content = "¿Qué es eso? ¿Odi está pagando hoy? Bueno, ¡apúntame!",
  ui_story_5081_50810401_67_dialog_content = "Tampoco puedo perderme esto...",
  ui_story_5081_50810401_68_dialog_content = "¡Cuenta con nosotros también! ¡Chirrido!",
  ui_story_5081_50810401_69_dialog_content = "Chicos...",
  ui_story_5081_50810401_70_dialog_content = "¡Vamos todos, busquemos señales de Gronru en las puntuaciones más altas!",
  ui_story_5081_50810402_1_dialog_content = "<color=#e8d9bb>¡JUEGO TERMINADO!</color>",
  ui_story_5081_50810402_2_dialog_content = "¿Perdimos de nuevo? ¡Urgh, al diablo con eso! ¡Pon más fichas!",
  ui_story_5081_50810402_3_dialog_content = "De hecho, nos hemos quedado sin tokens...",
  ui_story_5081_50810402_4_dialog_content = "¿Qué? Jomu, ve a buscar más para nosotros!",
  ui_story_5081_50810402_5_dialog_content = "¿Eh? ¿Yo? Debes estar bromeando... Sork, ¿por qué no compras algunos más?",
  ui_story_5081_50810402_6_dialog_content = "¿Yo? ¡Pero soy un empleado aquí!",
  ui_story_5081_50810402_7_dialog_content = "Sería un poco incómodo, ¿no? Además, estabas jugando como basura justo ahora, Jomu! ¡Al menos hazte útil de alguna manera!",
  ui_story_5081_50810402_8_dialog_content = "Jomu juega como basura, ¡chirrido!",
  ui_story_5081_50810402_9_dialog_content = "¡N-no soy tan bueno en este tipo de juego! No me culpas, ¿verdad? ¿Jefe?",
  ui_story_5081_50810402_10_dialog_content = "Nah, especialmente porque tampoco soy tan bueno en eso. Odi tuvo que llevarme todo el tiempo.",
  ui_story_5081_50810402_11_dialog_content = "El verdadero problema es que incluso con nuestras habilidades combinadas, no creo que alguna vez veamos la puntuación más alta de Gronru...",
  ui_story_5081_50810402_12_dialog_content = "¡Porque ni siquiera podemos llegar a las tablas de clasificación!",
  ui_story_5081_50810402_13_dialog_content = "Lo sabía... Necesitamos la ayuda de Batia para lograr esto, pero...",
  ui_story_5081_50810402_14_dialog_content = "...",
  ui_story_5081_50810402_15_dialog_content = "¡Parece que ella ya no quiere tener nada que ver conmigo!",
  ui_story_5081_50810402_16_dialog_content = "Jeje, no estaría tan seguro, PlayerName.",
  ui_story_5081_50810402_17_dialog_content = "Después de trabajar en la tienda durante unos días, puedo decirte que rara vez se acerca a los clientes para jugar con ellos.",
  ui_story_5081_50810402_18_dialog_content = "Estaba dispuesta a asociarse contigo en el momento en que entraste a este lugar, lo que significa que realmente debe gustarte.",
  ui_story_5081_50810402_19_dialog_content = "¡Chirrido! ¡PlayerName tiene un potencial oculto!",
  ui_story_5081_50810402_20_dialog_content = "Pero parecía tan decepcionada de mí antes...",
  ui_story_5081_50810402_21_dialog_content = "Estoy bastante seguro de que solo es este evento de preventa que está afectando sus nervios.",
  ui_story_5081_50810402_22_dialog_content = "Ha estado evaluando a los jugadores sin parar y aceptando desafíos todo el tiempo, además de sus deberes habituales como dueña de la sala de juegos...",
  ui_story_5081_50810402_23_dialog_content = "Probablemente esté demasiado cansada para prestar mucha atención a tus palabras en este momento.",
  ui_story_5081_50810402_24_dialog_content = "No es tu culpa, PlayerName!",
  ui_story_5081_50810402_25_dialog_content = "... ¿De verdad lo crees?",
  ui_story_5081_50810402_26_dialog_content = "A veces puedes ser realmente lento, ¿sabes eso? ¿Aún no lo has descubierto?",
  ui_story_5081_50810402_27_dialog_content = "¿Descubrir qué?",
  ui_story_5081_50810402_28_dialog_content = "\"¡\"B\" es una reclusa! ¡Es socialmente ansiosa!",
  ui_story_5081_50810402_29_dialog_content = "Hacerse cargo de una tienda como esta ya es lo suficientemente difícil para alguien como ella.",
  ui_story_5081_50810402_30_dialog_content = "Pero para dar a los jugadores como nosotros un lugar para reunirse y jugar...",
  ui_story_5081_50810402_31_dialog_content = "¡Ha estado haciendo su mejor esfuerzo para superar su ansiedad social y mantener este lugar en funcionamiento!",
  ui_story_5081_50810402_32_dialog_content = "Sabiendo eso, tiene sentido que ella no pueda darte una respuesta cuando le preguntas sobre cosas fuera de los videojuegos, ¿verdad?",
  ui_story_5081_50810402_33_dialog_content = "Entiendo...",
  ui_story_5081_50810402_34_dialog_content = "(Pero aún así, realmente no quiero renunciar a una pista tan buena...)",
  ui_story_5081_50810402_35_dialog_content = "(¡No puedo quitarme la sensación de que Gronru está de alguna manera conectado a este lugar!)",
  ui_story_5081_50810402_36_dialog_content = "¿Jefe? ¡Jefe!",
  ui_story_5081_50810402_37_dialog_content = "¿Eh? ¿Qué pasa ahora, Jomu? No me digas que vas a intentar estafarme de nuevo...",
  ui_story_5081_50810402_38_dialog_content = "¿Estafarte? ¡Tus palabras me hieren, jefe! Resulta que me preocupo por tus intereses más que nadie!",
  ui_story_5081_50810402_39_dialog_content = "Y se me ocurrió una idea solo para ti.",
  ui_story_5081_50810402_40_dialog_content = "¿Y eso sería?",
  ui_story_5081_50810402_41_dialog_content = "¿Por qué no intentas completar una Etapa-B?",
  ui_story_5081_50810402_42_dialog_content = "¿Un qué ahora?",
  ui_story_5081_50810402_43_dialog_content = "Dado que la dueña de la tienda no puede atender a cada uno de los desafiantes, ha configurado una serie de etapas únicas en algunas de las máquinas de juegos de la sala de arcade.",
  ui_story_5081_50810402_44_dialog_content = "Si puedes eliminarlos...",
  ui_story_5081_50810402_45_dialog_content = "¡Incluso podría permitirte copiar la versión original de este juego!",
  ui_story_5081_50810402_46_dialog_content = "¡Después de eso, podemos hacer un montón de copias y venderlas como versiones oficiales!",
  ui_story_5081_50810402_47_dialog_content = "También podemos ocultar parte del contenido detrás de un muro de pago y ganar aún más por copia, jeje...",
  ui_story_5081_50810402_48_dialog_content = "¡Haremos una fortuna en poco tiempo!",
  ui_story_5081_50810402_49_dialog_content = "... ¡Y nos convertiremos en las personas más odiadas en la comunidad de jugadores! ¿No dijiste que ofenderlos era una mala idea?",
  ui_story_5081_50810402_50_dialog_content = "Por eso haremos todo bajo tu nombre, ¡jefe! Después de todo, nadie sospecharía de la legendaria Caelestite...",
  ui_story_5081_50810402_51_dialog_content = "Está bien, ya basta de tus planes descabellados. Ya he conocido a tantos jugadores aquí hoy...",
  ui_story_5081_50810402_52_dialog_content = "Todos son muy agradables y realmente aman los videojuegos. ¡Me niego a estafarlos!",
  ui_story_5081_50810402_53_dialog_content = "¡Vamos jefe! ¡No seas así!",
  ui_story_5081_50810402_54_dialog_content = "Oye, ¿eso es...?",
  ui_story_5081_50810402_55_dialog_content = "¿Eh? ¿Qué está pasando allí?",
  ui_story_5081_50810402_56_dialog_content = "Parece que tenemos un nuevo retador. ¡Iré a darles la bienvenida!",
  ui_story_5081_50810402_57_dialog_content = "Claro, solo intenta no acercarte sigilosamente a ellos con tu escalofriante \"bienvenida\" otra vez...",
  ui_story_5081_50810402_58_dialog_content = "¡Esa podría ser la razón por la que no estás haciendo tantas ventas!",
  ui_story_5081_50810402_59_dialog_content = "¿Otro advenedizo que no sabe cuál es su lugar, eh? Vamos PlayerName, vámonos.",
  ui_story_5081_50810402_60_dialog_content = "... ¿Ir a dónde?",
  ui_story_5081_50810402_61_dialog_content = "¡Ve a ver de qué se trata todo este alboroto! Ahora que lo pienso, aún no has visto las habilidades de Batia en acción, ¿verdad?",
  ui_story_5081_50810402_62_dialog_content = "Supongo que no...",
  ui_story_5081_50810402_63_dialog_content = "(Esta es probablemente una buena oportunidad para conocer mejor a Batia también.)",
  ui_story_5081_50810402_64_dialog_content = "¡Haré lo mejor que pueda para mirar y aprender!",
  ui_story_5081_50810501_1_dialog_content = "Disculpe, pero ¿está el dueño de Hidden Fangs?",
  ui_story_5081_50810501_2_dialog_content = "¿Oh? ¿Es este el último retador?",
  ui_story_5081_50810501_3_dialog_content = "¡La he visto antes! ¡Es una tiradora a sueldo de Umbraton y se autoproclama conocedora de antigüedades!",
  ui_story_5081_50810501_4_dialog_content = "¿Contrató alguien importante a ella para venir aquí?",
  ui_story_5081_50810501_5_dialog_content = "Para nada. Vine aquí por mi propia voluntad.",
  ui_story_5081_50810501_6_dialog_content = "Me dijeron que podría comprar una copia de edición limitada de un juego desafiando al dueño de la sala de juegos, una persona con el nombre de \"B\".",
  ui_story_5081_50810501_7_dialog_content = "¡Hola, Allura! ¡Qué sorpresa verte aquí!",
  ui_story_5081_50810501_8_dialog_content = "¿PlayerName? ... Qué sorpresa tan inesperada.",
  ui_story_5081_50810501_9_dialog_content = "¿Ya has asegurado una copia del juego?",
  ui_story_5081_50810501_10_dialog_content = "Bueno...",
  ui_story_5081_50810501_11_dialog_content = "Parece que no. Es una pena, ya que comprarlo de ti probablemente me ahorraría tiempo. Aún así...",
  ui_story_5081_50810501_12_dialog_content = "Estoy interesado en ver cuán hábil es realmente esta persona \"B\".",
  ui_story_5081_50810501_13_dialog_content = "Otro retador... Bienvenido.",
  ui_story_5081_50810501_14_dialog_content = "¿Oh? ¿Así que esta niña es \"B\"?",
  ui_story_5081_50810501_15_dialog_content = "No está mal, solo te tomó cuarenta y seis segundos aparecer ante mí... ¿Aceptas mi desafío?",
  ui_story_5081_50810501_16_dialog_content = "Me gustaría preguntarte algo primero... ¿Por qué quieres comprar este juego?",
  ui_story_5081_50810501_17_dialog_content = "Por supuesto, para añadirlo a mi preciada colección.",
  ui_story_5081_50810501_18_dialog_content = "Un juego de fantasía completamente restaurado es la fusión perfecta de tecnología y entretenimiento, así como una antigüedad rara e invaluable.",
  ui_story_5081_50810501_19_dialog_content = "Los datos almacenados en su cartucho son tan valiosos como las palabras escritas en los antiguos tomos que he recopilado.",
  ui_story_5081_50810501_20_dialog_content = "Si no logro adquirir este juego de fantasía, el valor de toda mi colección disminuirá en un uno punto cinco por ciento.",
  ui_story_5081_50810501_21_dialog_content = "Un recolector de datos, huh...",
  ui_story_5081_50810501_22_dialog_content = "Bien. Acepto tu desafío.",
  ui_story_5081_50810501_23_dialog_content = "¿Qué? ¿En serio?",
  ui_story_5081_50810501_24_dialog_content = "Pero parece que Allura tampoco vino a jugar videojuegos...",
  ui_story_5081_50810501_25_dialog_content = "La recopilación de datos también es una parte muy importante de ser un jugador, PlayerName.",
  ui_story_5081_50810501_26_dialog_content = "Además del diseño y el arte de un cartucho, los datos de videojuegos antiguos almacenados en su interior también son extremadamente valiosos.",
  ui_story_5081_50810501_27_dialog_content = "El acto de coleccionar en sí mismo también es un aspecto importante del juego...",
  ui_story_5081_50810501_28_dialog_content = "¡Esta sala de juegos no es solo un hogar para los jugadores, también es un hogar para los ávidos coleccionistas!",
  ui_story_5081_50810501_29_dialog_content = "Puedes elegir el juego que quieras, siempre y cuando se pueda jugar aquí.",
  ui_story_5081_50810501_30_dialog_content = "Esa es exactamente la clase de confianza que esperaría de un jugador legendario.",
  ui_story_5081_50810501_31_dialog_content = "Esta es mi elección, Emperador de la Luz, Versión 98.",
  ui_story_5081_50810501_32_dialog_content = "... Qué inesperado.",
  ui_story_5081_50810501_33_dialog_content = "Tal vez estuve mal al asumir, pero dada tu apariencia... Estaba seguro de que elegirías un juego de disparos antes que cualquier otra cosa.",
  ui_story_5081_50810501_34_dialog_content = "No estabas equivocado al suponer, pero vine preparado para jugar este juego y no tengo intención de cambiar mi decisión.",
  ui_story_5081_50810501_35_dialog_content = "Lo que admiro de este juego es que es tanto clásico como accesible.",
  ui_story_5081_50810501_36_dialog_content = "... ¿De qué diablos están hablando?",
  ui_story_5081_50810501_37_dialog_content = "El retador quiere jugar un juego de lucha clásico, pero \"B\" piensa que debería elegir un juego de disparos en su lugar.",
  ui_story_5081_50810501_38_dialog_content = "¿Entonces qué significa \"Versión 98\"? No me digas... ¿Podría significar el Año 1998 del Calendario Matutino?",
  ui_story_5081_50810501_39_dialog_content = "Exactamente. 1998 fue un buen año para el entretenimiento en Umbraton, y durante ese tiempo salieron muchos juegos fantásticos...",
  ui_story_5081_50810501_40_dialog_content = "¡Ah! ¡Están a punto de comenzar!",
  ui_story_5081_50810501_41_dialog_content = "No parece que necesites calentar o incluso revisar tu lista de movimientos...",
  ui_story_5081_50810501_42_dialog_content = "En ese caso... comencemos.",
  ui_story_5081_50810501_43_dialog_content = "¡Guau! La primera retadora del día ha tomado su asiento—",
  ui_story_5081_50810501_44_dialog_content = "¡Y \"B\", la campeona indiscutible, ha iniciado sesión en su propia cuenta!",
  ui_story_5081_50810501_45_dialog_content = "¡Ahí está! ¡Su legendario nombre de jugador!",
  ui_story_5081_50810501_46_dialog_content = "¡Es ella, sin duda alguna! ¡Finalmente podremos verla en acción!",
  ui_story_5081_50810501_47_dialog_content = "¿C-Comentar en vivo? ¿Estás intentando volver a tu antiguo trabajo o algo así, Odi?",
  ui_story_5081_50810501_48_dialog_content = "¡Ninguna batalla épica está completa sin algunas refrescos selectos! ¡Aperitivos y bebidas de Umbraton a la venta aquí mismo!",
  ui_story_5081_50810501_49_dialog_content = "Este chico, por otro lado, nunca ha dejado de trabajar... Espera, ¿no son estos bocadillos del Desierto de Rediesel?",
  ui_story_5081_50810501_50_dialog_content = "¡Silencio, jefe! Quiero decir... Naturalmente, hice algunos ajustes para adaptarme a los gustos locales.",
  ui_story_5081_50810501_51_dialog_content = "De todos modos, si sigues perdiendo el tiempo aquí, ¡te perderás el final de la primera ronda!",
  ui_story_5081_50810501_52_dialog_content = "¿Q-Qué?",
  ui_story_5081_50810501_53_dialog_content = "<color=#e8d9bb>¡K.O.! ¡Perfecto!</color>",
  ui_story_5081_50810501_54_dialog_content = "¡Increíble!",
  ui_story_5081_50810501_55_dialog_content = "\"¡B\" tomó la iniciativa desde el mismo comienzo de la ronda! Con un salto y un sprint, lanzó a su oponente y no le dio tregua hasta el final!",
  ui_story_5081_50810501_56_dialog_content = "Sin espacio para contraatacar, ¡el retador no tuvo más remedio que admitir la derrota!",
  ui_story_5081_50810501_57_dialog_content = "¿Dándolo todo en la primera ronda? Estaba planeando contraatacar después de un segundo y medio...",
  ui_story_5081_50810501_58_dialog_content = "Pero logró llevarse la victoria en menos de un segundo.",
  ui_story_5081_50810501_59_dialog_content = "Aun así, creo que entiendo un poco mejor tu estilo de juego. Sigamos.",
  ui_story_5081_50810501_60_dialog_content = "Humph, ¿realmente crees que lo has descubierto?",
  ui_story_5081_50810501_61_dialog_content = "Te daré diez oportunidades para vencerme. Si lo haces, te dejaré comprar una copia del juego.",
  ui_story_5081_50810501_62_dialog_content = "Entonces me estás subestimando severamente. ¡Vamos!",
  ui_story_5081_50810501_63_dialog_content = "(Cuando Batia se sumerge en un juego, es como si se convirtiera en una persona completamente diferente.)",
  ui_story_5081_50810501_64_dialog_content = "(Confiada, seria, desinhibida, pero lo más importante... parece que se está divirtiendo.)",
  ui_story_5081_50810501_65_dialog_content = "(¿Podría ser esta la verdadera ella?)",
  ui_story_5081_50810501_66_dialog_content = "(Debería seguir observando, tanto el juego como a este jugador legendario...)",
  ui_story_5081_50810502_1_dialog_content = "<color=#e8d9bb>¡K.O.!</color>",
  ui_story_5081_50810502_2_dialog_content = "¡Se acabó! Después de diez intentos completos, el desafiante no pudo lograr ni una sola victoria!",
  ui_story_5081_50810502_3_dialog_content = "A pesar de esto, ella mantuvo la presión y logró acorralar a \"B\" unas cuantas veces...",
  ui_story_5081_50810502_4_dialog_content = "¡No se puede negar! ¡La retadora de hoy merece reconocimiento, si no simplemente por su increíble espíritu de lucha!",
  ui_story_5081_50810502_5_dialog_content = "<size=30>Te estás emocionando un poco demasiado, Odi...</size>",
  ui_story_5081_50810502_6_dialog_content = "...",
  ui_story_5081_50810502_7_dialog_content = "Increíble... Tenía la sensación de que perdería, pero no esperaba perder tan espectacularmente.",
  ui_story_5081_50810502_8_dialog_content = "Como era de esperar del legendario \"B\". Admito mi derrota.",
  ui_story_5081_50810502_9_dialog_content = "Eres bienvenido a desafiarme en otro juego, si te gustaría...",
  ui_story_5081_50810502_10_dialog_content = "No hace falta. Estoy completamente consciente de la brecha de habilidad entre nosotros ahora. Sería inútil continuar.",
  ui_story_5081_50810502_11_dialog_content = "Entiendo... pero tus habilidades aún son dignas de respeto.",
  ui_story_5081_50810502_12_dialog_content = "Puedo decir que hiciste mucha práctica de último minuto, pero hiciste un gran trabajo aprovechando tus ventajas y cubriendo tus debilidades.",
  ui_story_5081_50810502_13_dialog_content = "Tu conocimiento de los movimientos de tus personajes, las proporciones de daño, los efectos de habilidades e incluso sus cuadros es extremadamente alto.",
  ui_story_5081_50810502_14_dialog_content = "Con más tiempo y entrenamiento, quizás...",
  ui_story_5081_50810502_15_dialog_content = "Podrías vencerme en un solo partido... siempre y cuando no esté usando a mis mejores personajes, por supuesto.",
  ui_story_5081_50810502_16_dialog_content = "\"¿B\" realmente reconoció a su retadora?",
  ui_story_5081_50810502_17_dialog_content = "Aunque se estuviera limitando, ¡no puedo creer que \"B\" admitiera que alguien realmente podría vencerla!",
  ui_story_5081_50810502_18_dialog_content = "¿Oh? No sé si tengo ese tipo de potencial... pero tu análisis es completamente correcto.",
  ui_story_5081_50810502_19_dialog_content = "Para agregar ese juego de fantasía a mi colección, hice algunas prácticas de último minuto en este juego clásico.",
  ui_story_5081_50810502_20_dialog_content = "La razón por la que no elegí otro juego es porque no tengo tanta experiencia en ellos. Sin embargo...",
  ui_story_5081_50810502_21_dialog_content = "Eh... ¿T-Todavía quieres desafiarme en algo?",
  ui_story_5081_50810502_22_dialog_content = "No. Esta es mi tarjeta de presentación.",
  ui_story_5081_50810502_23_dialog_content = "Yo, eh, no sé qué se supone que debo hacer con esto.",
  ui_story_5081_50810502_24_dialog_content = "Solo aférrate a él, si quieres.",
  ui_story_5081_50810502_25_dialog_content = "Después de todo, definitivamente quiero experimentar la <color=#FFB400>alegría de jugar</color> ahora.",
  ui_story_5081_50810502_26_dialog_content = "Especialmente cuando se trata de juegos extremadamente detallados como este... ¡Ah, no puedo permitirme perder tan mal como hoy nunca más!",
  ui_story_5081_50810502_27_dialog_content = "¿Te... divertiste jugando hace un momento?",
  ui_story_5081_50810502_28_dialog_content = "Sí, lo hice. Al principio, solo quería agregar algunos juegos a mi colección de antigüedades.",
  ui_story_5081_50810502_29_dialog_content = "Pero ahora, finalmente me doy cuenta de lo mucho más divertido que es realmente jugarlos... ¡y este juego es mucho más complejo de lo que imaginaba!",
  ui_story_5081_50810502_30_dialog_content = "Si hay más juegos como este, te agradecería mucho que me los presentaras.",
  ui_story_5081_50810502_31_dialog_content = "Entendido... De hecho, creo que podríamos tener algunos cartuchos extra por aquí... Eres bienvenido a probarlos también...",
  ui_story_5081_50810502_32_dialog_content = "Y... si descubro algún juego similar, te lo haré saber de inmediato.",
  ui_story_5081_50810502_33_dialog_content = "T-También, has pasado. ¡Ahora eres digno de comprar una copia de este juego de fantasía!",
  ui_story_5081_50810502_34_dialog_content = "¿Eh? ¿Pero pensé que había perdido?",
  ui_story_5081_50810502_35_dialog_content = "Ganar o perder no determina el valor de un jugador... ¡Lo más importante es que disfruten jugando juegos!",
  ui_story_5081_50810502_36_dialog_content = "Entiendo...",
  ui_story_5081_50810502_37_dialog_content = "Parece que es hora de volver al trabajo. Puedo ayudarte a pagar por ello aquí, señorita.",
  ui_story_5081_50810502_38_dialog_content = "¡Felicidades! Finalmente, alguien se ha ganado el derecho de comprar el juego!",
  ui_story_5081_50810502_39_dialog_content = "¡Estoy tan celoso! Pero después de verlos enfrentarse, sé que no tengo oportunidad...",
  ui_story_5081_50810502_40_dialog_content = "Todos son demasiado amables.",
  ui_story_5081_50810502_41_dialog_content = "Esta sala de juegos realmente es un lugar maravilloso.",
  ui_story_5081_50810502_42_dialog_content = "¡Bien! Entre olas de aplausos, el recién llegado emerge de Hidden Fangs, sonriente y victorioso!",
  ui_story_5081_50810502_43_dialog_content = "¡Y mientras todavía hay muchos desafiantes en la sala de juegos, no parecen tan seguros de sí mismos ahora!",
  ui_story_5081_50810502_44_dialog_content = "No necesitabas agregar esa última parte, Odi! Además... E-Estoy empezando a pensar que no tengo las habilidades suficientes para—",
  ui_story_5081_50810502_45_dialog_content = "¿Aún no te has dado cuenta, PlayerName? ¿Cómo puedes seguir pensando que este desafío se basa únicamente en habilidad?",
  ui_story_5081_50810502_46_dialog_content = "¡Piensa, tonto! ¿Cuál fue la razón por la que \"B\" decidió unirse a ti antes?",
  ui_story_5081_50810502_47_dialog_content = "La razón, eh...",
  ui_story_5081_50810502_48_dialog_content = "¿Es así como se supone que debo tomar las curvas? ¡Lo entiendo totalmente ahora!",
  ui_story_5081_50810502_49_dialog_content = "Recojo Lumina cada vez que derrapo en una esquina, ¿se supone que debo dispararlo a los Eclipsites? ¡Supongo que será mejor que lo intente!",
  ui_story_5081_50810502_50_dialog_content = "En aquel entonces... Estaba totalmente perdido en el juego.",
  ui_story_5081_50810502_51_dialog_content = "Quizás pensó que realmente me gustaban los juegos cuando me vio así, por lo que decidió unirse a mí.",
  ui_story_5081_50810502_52_dialog_content = "¡No hace falta el \"quizás\"! ¿Realmente crees que captaste su atención solo con tus habilidades?",
  ui_story_5081_50810502_53_dialog_content = "¡Oye, no hay necesidad de ser tan directo!",
  ui_story_5081_50810502_54_dialog_content = "Siempre y cuando estés dispuesto a respetar, entender y disfrutar de los juegos aquí, no tendrás problemas para entenderla.",
  ui_story_5081_50810502_55_dialog_content = "¡No encontrarás a una persona más amigable y entusiasta que \"B\" si lo haces!",
  ui_story_5081_50810502_56_dialog_content = "Sin embargo, hay un inconveniente... Ella consume una tonelada de maná cada vez que se emociona, ¡y también tiene un tiempo de enfriamiento bastante largo!",
  ui_story_5081_50810502_57_dialog_content = "Entiendo. Encontrar a Gronru también podría ser una situación similar.",
  ui_story_5081_50810502_58_dialog_content = "Solo necesito intentar entenderlos... y experimentar los videojuegos que tanto aman por mí mismo.",
  ui_story_5081_50810502_59_dialog_content = "Una vez que lo haga, finalmente podré ver las cosas desde su perspectiva y acercarme más a ambos.",
  ui_story_5081_50810502_60_dialog_content = "Quizás Gronru solo está esperando a alguien que también la entienda.",
  ui_story_5081_50810502_61_dialog_content = "¡Hemos estado esperando que digas eso, jefe! ¡Y ya me tomé la libertad de inscribirnos a ambos!",
  ui_story_5081_50810502_62_dialog_content = "¡Ahora vamos a desafiar a \"B\" y hacer nuestras fortunas!",
  ui_story_5081_50810502_63_dialog_content = "Perdóneme, pero ¿es aquí donde puedo desafiar a la persona conocida como \"B\"?",
  ui_story_5081_50810502_64_dialog_content = "¡Ah! ¡Otro retador! ¡Vamos a echar un vistazo!",
  ui_story_5081_50810502_65_dialog_content = "¡Espérame, jefe!",
  ui_story_5081_50810601_1_dialog_content = "¡Qué retador inesperado!",
  ui_story_5081_50810601_2_dialog_content = "¡Juzgando por su ropa, creo que ella es de Lumopolis!",
  ui_story_5081_50810601_3_dialog_content = "¿Va a responderme alguien? ¡Estoy aquí para desafiar a \"B\"!",
  ui_story_5081_50810601_4_dialog_content = "¿Quién está a cargo aquí?",
  ui_story_5081_50810601_5_dialog_content = "¿Beretta?",
  ui_story_5081_50810601_6_dialog_content = "PlayerName? ¿Estás trabajando aquí por casualidad?",
  ui_story_5081_50810601_7_dialog_content = "Si es así, ¿podrías ayudarme a inscribirme en el desafío?",
  ui_story_5081_50810601_8_dialog_content = "No, creo que estás buscando al dueño de la tienda... ¡Oh, aquí viene ella!",
  ui_story_5081_50810601_9_dialog_content = "...",
  ui_story_5081_50810601_10_dialog_content = "¡Excelente!",
  ui_story_5081_50810601_11_dialog_content = "Perdóname por no haberte notado antes. Mi nombre es Beretta y soy un médico de campo de Lumopolis.",
  ui_story_5081_50810601_12_dialog_content = "¿Cómo puedo dirigirme a usted? ¿Y cómo puedo inscribirme para desafiar al legendario \"B\"?",
  ui_story_5081_50810601_13_dialog_content = "Puedes llamarme Batia. ¿Qué juego te gustaría jugar para el desafío?",
  ui_story_5081_50810601_14_dialog_content = "Cualquier juego está bien, ¡pero preferiría jugar tu juego más difícil y agotador!",
  ui_story_5081_50810601_15_dialog_content = "Para ser honesto, esta es mi primera vez visitando un establecimiento como este. Con tantos desafíos y dificultades a la vista...",
  ui_story_5081_50810601_16_dialog_content = "Aunque nunca antes he jugado a los juegos en serio, ¡este es el lugar perfecto para poner a prueba mi determinación!",
  ui_story_5081_50810601_17_dialog_content = "... Esto es solo una sala de juegos, no un campo de entrenamiento... Aquí solo encontrarás jugadores reunidos.",
  ui_story_5081_50810601_18_dialog_content = "Si quieres poner a prueba tu determinación... Yo...Yo sugiero que vayas a otro lugar.",
  ui_story_5081_50810601_19_dialog_content = "¡Los juegos son una excelente manera de probar la fuerza de voluntad de uno! ¡Escucho que muchos de los mejores soldados de Illumina entrenan de esta manera!",
  ui_story_5081_50810601_20_dialog_content = "Desafortunadamente, Lumopolis carece de estos métodos de entrenamiento. Cuando escuché que Umbraton tenía un lugar así, ¡tenía que venir y verlo por mí mismo!",
  ui_story_5081_50810601_21_dialog_content = "Ahora, ¿puedo desafiar a este llamado \"B\" a un partido de entrenamiento, por favor?",
  ui_story_5081_50810601_22_dialog_content = "Y-Yo soy \"B.\"",
  ui_story_5081_50810601_23_dialog_content = "Pero me niego a aceptar un desafío de alguien que no conoce las reglas de un juego...",
  ui_story_5081_50810601_24_dialog_content = "Si realmente quieres desafiarme... p-por favor elige un juego y aprende a jugarlo primero.",
  ui_story_5081_50810601_25_dialog_content = "¡Muy bien, haré exactamente eso! ¡Gracias!",
  ui_story_5081_50810601_26_dialog_content = "¡Ella en realidad está estudiando cómo tocar!",
  ui_story_5081_50810601_27_dialog_content = "... ¿Está realmente bien? ¡Creo que ella está incluso más enfocada en su objetivo que yo!",
  ui_story_5081_50810601_28_dialog_content = "Creo que \"B\" simplemente no sabe cómo lidiar con alguien como ella.",
  ui_story_5081_50810601_29_dialog_content = "Vencer a sus oponentes lo más pronto posible es cómo ella suele hacer las cosas.",
  ui_story_5081_50810601_30_dialog_content = "Algo me dice que eso no funcionará muy bien en alguien como Beretta...",
  ui_story_5081_50810601_31_dialog_content = "¡Ahh! ¿Cómo podría ser esto?",
  ui_story_5081_50810601_32_dialog_content = "Estuve aquí primero, ¿no?",
  ui_story_5081_50810601_33_dialog_content = "Esa maniática del entrenamiento no sabe lo primero sobre videojuegos, ¿verdad? ¡Esto va a tomar una eternidad!",
  ui_story_5081_50810601_34_dialog_content = "Tal vez deberíamos investigar métodos más dudosos, jefe...",
  ui_story_5081_50810601_35_dialog_content = "No te preocupes, aprendo muy rápido. También tienen juegos de pelea, ¡deberían ser perfectos para mí!",
  ui_story_5081_50810601_36_dialog_content = "Parece que Beretta va a elegir el mismo juego que Allura. Supongo que eso es a lo que se refería con \"clásico y accesible\", ¿verdad?",
  ui_story_5081_50810601_37_dialog_content = "El controlador está todo golpeado. Este juego debe ser realmente popular.",
  ui_story_5081_50810601_38_dialog_content = "Disculpe... pero ¿alguien está escuchando?",
  ui_story_5081_50810601_39_dialog_content = "Ustedes chicos... ambos pueden desafiarme.",
  ui_story_5081_50810601_40_dialog_content = "¿Mmm? ¿A qué te refieres con eso?",
  ui_story_5081_50810601_41_dialog_content = "Los dos pueden unirse contra mí. Aún así ganaré... así que no importa.",
  ui_story_5081_50810601_42_dialog_content = "Admiro tu confianza, pero debo rechazar.",
  ui_story_5081_50810601_43_dialog_content = "Perder en un partido de dos contra uno sería vergonzoso, pero ganar contra ti no sería mejor.",
  ui_story_5081_50810601_44_dialog_content = "Aunque este hombre joven parezca ser completamente débil, los números aún estarían a nuestro favor.",
  ui_story_5081_50810601_45_dialog_content = "Me niego a aceptar esto, a menos que tú mismo te unas a alguien!",
  ui_story_5081_50810601_46_dialog_content = "Adicto al entrenamiento... Pronto veremos quién es el verdadero debilucho!",
  ui_story_5081_50810601_47_dialog_content = "¿Un aliado? ... No necesito uno. No hay razón para que moleste a nadie, ya que...",
  ui_story_5081_50810601_48_dialog_content = "Si no te importa—",
  ui_story_5081_50810601_49_dialog_content = "¿Estaría bien si hago equipo contigo?",
  ui_story_5081_50810601_50_dialog_content = "¿Ah?",
  ui_story_5081_50810601_51_dialog_content = "Jaja, no estoy seguro si estoy devolviendo el favor o si es algo más...",
  ui_story_5081_50810601_52_dialog_content = "Pero hicimos un buen equipo antes, ¿no crees?",
  ui_story_5081_50810601_53_dialog_content = "Si no hubiera sido por ti, nunca habría superado una etapa tan difícil. ¡Así que ahora es mi turno de ser tu Jugador 2!",
  ui_story_5081_50810601_54_dialog_content = "Tú...",
  ui_story_5081_50810601_55_dialog_content = "Ver a todos estos retadores serios también me está entusiasmado.",
  ui_story_5081_50810601_56_dialog_content = "¡Apuesto a que podría disfrutar este juego al máximo si me dejas jugar en tu equipo!",
  ui_story_5081_50810601_57_dialog_content = "S-Si así es como realmente te sientes...",
  ui_story_5081_50810601_58_dialog_content = "¡Entonces juguemos juntos!",
  ui_story_5081_50810601_59_dialog_content = "...",
  ui_story_5081_50810601_60_dialog_content = "¡Gracias por eso, jefe! Sabes qué hacer ahora, ¿verdad?",
  ui_story_5081_50810601_61_dialog_content = "¿D-De qué estás hablando?",
  ui_story_5081_50810601_62_dialog_content = "¡Con tu sabotaje, este partido de dos contra dos se convertirá en una pelea de tres contra uno!",
  ui_story_5081_50810601_63_dialog_content = "¡Incluso con este loco del entrenamiento en nuestro equipo, todavía tendremos una oportunidad de vencerla! ¡Jajajaja!",
  ui_story_5081_50810601_64_dialog_content = "¡Me aseguraré de darte tu parte después!",
  ui_story_5081_50810601_65_dialog_content = "... ¿Crees que voy a <color=#FFB400>sabotar</color> el partido?",
  ui_story_5081_50810601_66_dialog_content = "¡Eso es todo! ¡Es hora de que sientas el poder del Último Caelestita!",
  ui_story_5081_50810602_1_dialog_content = "<color=#e8d9bb>¡K.O.!</color>",
  ui_story_5081_50810602_2_dialog_content = "¡Jefe, no! ¡Esto no es lo que acordamos!",
  ui_story_5081_50810602_3_dialog_content = "¡Deja de perder el tiempo, debilucho! ¡Vas a hacernos perder el partido!",
  ui_story_5081_50810602_4_dialog_content = "¡Así es! Y para que conste, ¡no estuve de acuerdo con nada! ¡Ahora tráelo, estoy listo para seguir apoyándote, Batia!",
  ui_story_5081_50810602_5_dialog_content = "Entonces te dejaré manejar esta pelea.",
  ui_story_5081_50810602_6_dialog_content = "¿Ah?",
  ui_story_5081_50810602_7_dialog_content = "¡Concéntrate, el juego ha comenzado!",
  ui_story_5081_50810602_8_dialog_content = "¡Vale! Espera, Jomu, ¡aún no estoy listo! ¿No tienes modales?",
  ui_story_5081_50810602_9_dialog_content = "Lo siento, jefe, pero solo estoy jugando el juego! Una vez que comienza el partido, ¡todo vale!",
  ui_story_5081_50810602_10_dialog_content = "La concentración es una parte importante del entrenamiento, PlayerName! ¡Yo también voy a darlo todo!",
  ui_story_5081_50810602_11_dialog_content = "E-Eso es un poco—",
  ui_story_5081_50810602_12_dialog_content = "No te preocupes, estoy aquí.",
  ui_story_5081_50810602_13_dialog_content = "Solo juega lo mejor que puedas. No perderemos.",
  ui_story_5081_50810602_14_dialog_content = "Tienes razón. Después de todo, ¡no puedo perder con la legendaria \"B\" de mi lado!",
  ui_story_5081_50810602_15_dialog_content = "Jomu no es muy bueno, y Beretta es completamente nuevo en el juego. Solo necesito manejarlos con una mano tranquila y concentrada...",
  ui_story_5081_50810602_16_dialog_content = "¡Oh? ¡Parece que este desafío de dobles ha entrado en una fase completamente nueva!",
  ui_story_5081_50810602_17_dialog_content = "\"¡B\" ha cambiado roles con el último Celestita y ahora está jugando de apoyo! ¡Debe tener mucha confianza en él!",
  ui_story_5081_50810602_18_dialog_content = "¡Y en este lado, Training Freak y Debilucho están luchando para poner en orden su trabajo en equipo!",
  ui_story_5081_50810602_19_dialog_content = "¡Oye, Odi! Estamos en el mismo equipo, ¿recuerdas? ¿Qué tipo de nombre es ese?",
  ui_story_5081_50810602_20_dialog_content = "Mientras que Training Freak se lanza de frente contra sus oponentes, ¡Weakling continúa con su provocación molesta! ¿Podría ser esto algún tipo de finta?",
  ui_story_5081_50810602_21_dialog_content = "¡Es nuestra oportunidad!",
  ui_story_5081_50810602_22_dialog_content = "<color=#e8d9bb>Pam, pam—¡zas!</color>",
  ui_story_5081_50810602_23_dialog_content = "¡Ay! El último celestita está siendo golpeado sin piedad! ¡Esa barra de HP no se ve muy bien, amigos! ¿Cuánto más puede aguantar?",
  ui_story_5081_50810602_24_dialog_content = "Urgh... T-Tal vez deberíamos volver a cambiar?",
  ui_story_5081_50810602_25_dialog_content = "No entres en pánico. Ya tengo a su compañero de equipo completamente bajo control.",
  ui_story_5081_50810602_26_dialog_content = "En cuanto a ella, solo vigila sus movimientos... tanto dentro como fuera del juego.",
  ui_story_5081_50810602_27_dialog_content = "El camino para ganar debería ser perfectamente claro.",
  ui_story_5081_50810602_28_dialog_content = "R-¿En serio? Veamos...",
  ui_story_5081_50810602_29_dialog_content = "¡Toma eso! ¡Y eso! ¡No cederé pase lo que pase!",
  ui_story_5081_50810602_30_dialog_content = "<color=#e8d9bb>Toc, toc, toc, toc, bang—</color>",
  ui_story_5081_50810602_31_dialog_content = "¡Ahí está mi oportunidad!",
  ui_story_5081_50810602_32_dialog_content = "Bajo el brutal ataque de Training Freak, ¡el Último Caelestita finalmente muestra sus colmillos y contraataca! Pero, ¿puede mantener la presión?",
  ui_story_5081_50810602_33_dialog_content = "¡Lo está haciendo! Parece que el Fanático del Entrenamiento ha cometido un error...",
  ui_story_5081_50810602_34_dialog_content = "¡El ataque sigue llegando! ¿Podría ser este el fin?",
  ui_story_5081_50810602_35_dialog_content = "<color=#e8d9bb>¡K.O.!</color>",
  ui_story_5081_50810602_36_dialog_content = "¡Lo ha hecho! ¡El último Caelestite gana!",
  ui_story_5081_50810602_37_dialog_content = "Observando desde las líneas laterales y corriendo interferencias, \"B\" llevó a su compañero de equipo a la victoria con solo su orientación!",
  ui_story_5081_50810602_38_dialog_content = "...",
  ui_story_5081_50810602_39_dialog_content = "¿B-Mejor dos de tres?",
  ui_story_5081_50810602_40_dialog_content = "Perdí esta vez... No hay nada más que decir.",
  ui_story_5081_50810602_41_dialog_content = "A pesar de mis habilidades en combate, fui completamente y totalmente derrotado. Parece que este tipo de entrenamiento debe tomarse mucho más en serio.",
  ui_story_5081_50810602_42_dialog_content = "Perdóname. Fui arrogante al desafiarte.",
  ui_story_5081_50810602_43_dialog_content = "Existe una gran diferencia entre los videojuegos de lucha y el combate real. Las técnicas involucradas también son completamente diferentes.",
  ui_story_5081_50810602_44_dialog_content = "Confundir los dos... nunca termina bien.",
  ui_story_5081_50810602_45_dialog_content = "¿Es eso así? Interesante. May ¿Podrías explicar este concepto como lo haría una maestra a sus estudiantes?",
  ui_story_5081_50810602_46_dialog_content = "P-Profesor? N-No, nunca podría... No estoy capacitado para ser el profesor de nadie.",
  ui_story_5081_50810602_47_dialog_content = "Ah, qué pena...",
  ui_story_5081_50810602_48_dialog_content = "Está bien, puedo explicártelo en el lugar de Batia.",
  ui_story_5081_50810602_49_dialog_content = "... ¿Ah?",
  ui_story_5081_50810602_50_dialog_content = "PlayerName? ¡Por supuesto! Tus habilidades también fueron bastante sorprendentes.",
  ui_story_5081_50810602_51_dialog_content = "Solo pude ver tus movimientos gracias al consejo de Batia, y creo...",
  ui_story_5081_50810602_52_dialog_content = "Estabas tratando el juego como si fuera una pelea real, ¿verdad?",
  ui_story_5081_50810602_53_dialog_content = "¡Por supuesto que lo estaba! Ya sea velocidad de reacción, seguimiento de movimiento o posicionamiento adecuado...",
  ui_story_5081_50810602_54_dialog_content = "¡Todos estos aspectos son tan importantes en los videojuegos como lo son en el combate en vivo!",
  ui_story_5081_50810602_55_dialog_content = "Tienes un punto, pero no son completamente iguales.",
  ui_story_5081_50810602_56_dialog_content = "¿Cómo es eso?",
  ui_story_5081_50810602_57_dialog_content = "En los juegos de lucha, entradas muy pequeñas y precisas pueden producir resultados extremadamente poderosos.",
  ui_story_5081_50810602_58_dialog_content = "Pero estabas presionando los botones y tirando del joystick con tanta fuerza hace un momento, como si estuvieras tratando de canalizar tu verdadera fuerza en el juego.",
  ui_story_5081_50810602_59_dialog_content = "Hay todo tipo de personajes en los videojuegos, y no siempre pueden realizar las acciones que quieres que hagan. Es por eso que...",
  ui_story_5081_50810602_60_dialog_content = "No solo estabas desperdiciando tu fuerza, sino que también estabas afectando negativamente tus entradas, lo que me dio la oportunidad que necesitaba para contraatacar.",
  ui_story_5081_50810602_61_dialog_content = "... ¿Así que todo lo que necesitabas para derrotarme era entender este simple concepto?",
  ui_story_5081_50810602_62_dialog_content = "Sí... Pero de nuevo, solo fue gracias al consejo de Batia.",
  ui_story_5081_50810602_63_dialog_content = "Yo... no hice nada. Es solo sentido común, eso es todo.",
  ui_story_5081_50810602_64_dialog_content = "Entiendo.",
  ui_story_5081_50810602_65_dialog_content = "Por eso los soldados de Illumina <color=#FFB400>se adaptan</color> para adecuarse al <color=#FFB400>poder de fuego</color> de sus armas... ¡Todo tiene sentido ahora!",
  ui_story_5081_50810602_66_dialog_content = "¡Los juegos definitivamente pueden usarse para entrenar... O mejor dicho, el entrenamiento puede verse como una especie de juego!",
  ui_story_5081_50810602_67_dialog_content = "¡Esta experiencia ha sido tanto sorprendente como iluminadora!",
  ui_story_5081_50810602_68_dialog_content = "¡Gracias, Batia! ¿Estaría bien si vuelvo para desafiarte en el futuro?",
  ui_story_5081_50810602_69_dialog_content = "?",
  ui_story_5081_50810602_70_dialog_content = "E-Eso depende... ¿A-Acaso tú tienes...?",
  ui_story_5081_50810602_71_dialog_content = "¿Mmm?",
  ui_story_5081_50810602_72_dialog_content = "Creo que ella quiere preguntar si te divertiste hace un momento, y si disfrutaste jugando ese juego.",
  ui_story_5081_50810602_73_dialog_content = "¡Por supuesto! ¡Fue una experiencia tan emocionante! ¡No tenía idea de que los videojuegos pudieran ser tan divertidos!",
  ui_story_5081_50810602_74_dialog_content = "¡Y algo me dice que ganaré mucha más experiencia si sigo jugándolos!",
  ui_story_5081_50810602_75_dialog_content = "¡En este empeño, nunca flaquearé!",
  ui_story_5081_50810602_76_dialog_content = "Entonces... Por favor acepta esto.",
  ui_story_5081_50810602_77_dialog_content = "¡Ella pasó! E-Esto no puede ser! No tiene idea de cuánto vale ese juego...",
  ui_story_5081_50810602_78_dialog_content = "¿Me estás recomendando este juego? ¡Muy bien entonces! ¡Asegúrate de que practicaré noche y día una vez que obtenga mi copia!",
  ui_story_5081_50810602_79_dialog_content = "¡Espero con ansias nuestro próximo duelo!",
  ui_story_5081_50810602_80_dialog_content = "Uh... O-O-Está bien!",
  ui_story_5081_50810602_81_dialog_content = "Y una vez que domine los secretos del entrenamiento de videojuegos de Illumina...",
  ui_story_5081_50810602_82_dialog_content = "¡Puede que tenga la oportunidad de finalmente redimir mi derrota contra Yingel!",
  ui_story_5081_50810602_83_dialog_content = "Yingel?",
  ui_story_5081_50810602_84_dialog_content = "Un oficial de inteligencia en la Federación Illumina, sí.",
  ui_story_5081_50810602_85_dialog_content = "Tras mi derrota a manos de ella durante el Ejercicio Militar Conjunto, a menudo pienso en cómo lograr la victoria sobre ella.",
  ui_story_5081_50810602_86_dialog_content = "¡Incluso me crucé con ella de camino aquí!",
  ui_story_5081_50810602_87_dialog_content = "Pero ella estaba tan ocupada que no se dio cuenta de mí...",
  ui_story_5081_50810602_88_dialog_content = "ella es...",
  ui_story_5081_50810602_89_dialog_content = "!",
  ui_story_5081_50810602_90_dialog_content = "¿Eh? ¿No es ese el Oficial de Inteligencia Yingel?",
  ui_story_5081_50810602_91_dialog_content = "...",
  ui_story_5081_50810602_92_dialog_content = "Supongo que no soy el único al que ignoraron.",
  ui_story_5081_50810602_93_dialog_content = "¿Qué pasa?",
  ui_story_5081_50810602_94_dialog_content = "Oh, nada.",
  ui_story_5081_50810602_95_dialog_content = "(¿Qué hace una oficial de inteligencia de alto nivel de Illumina en Umbraton de todos modos? ¿Podría estar buscando Gronru también?)",
  ui_story_5081_50810602_96_dialog_content = "Bueno, si la ves, ¡hazle saber sobre mi desafío inminente!",
  ui_story_5081_50810602_97_dialog_content = "L-Lo haré.",
  ui_story_5081_50810602_98_dialog_content = "¡Juego de fantasía, mi mayor fuente de ingresos hasta ahora! Lo hice... ¡Finalmente soy digno de ello! ¡Wow!",
  ui_story_5081_50810602_99_dialog_content = "Sigues hablando de eso, Jomu? ... ¿Eh? ¿Qué haces en el suelo?",
  ui_story_5081_50810602_100_dialog_content = "Lo hice... Pasé... Ugh...",
  ui_story_5081_50810602_101_dialog_content = "Parece que se mareó un poco por jugar demasiado tiempo... ¡Sabía que no estaba hecho para este tipo de juego!",
  ui_story_5081_50810602_102_dialog_content = "Si hubiera sabido que estaba dispuesto a arriesgar su vida por dinero, nunca lo habría traído conmigo.",
  ui_story_5081_50810602_103_dialog_content = "Aunque nunca dejó de hablar sobre ganar dinero, cuando lo vi jugar antes...",
  ui_story_5081_50810602_104_dialog_content = "Jomu parecía que se estaba divirtiendo mucho, ¿no es así?",
  ui_story_5081_50810602_105_dialog_content = "... Estuve tan cerca de engañar a \"B\" justo ahora... Qué lástima...",
  ui_story_5081_50810602_106_dialog_content = "(Incluso un comerciante avaro como Jomu puede quedar atrapado jugando videojuegos. Supongo que ese es el poder de su atractivo.)",
  ui_story_5081_50810602_107_dialog_content = "Mi cabeza da vueltas... Agua... necesito agua...",
  ui_story_5081_50810602_108_dialog_content = "Espera un momento, iré a buscar algunas bebidas para ti y Odi. Después de todo ese comentario, estoy seguro de que ella también tiene sed.",
  ui_story_5081_50810602_109_dialog_content = "Piénsalo como un regalo de agradecimiento por traerme aquí hoy.",
  ui_story_5081_50810602_110_dialog_content = "¡Vuelvo enseguida!",
  ui_story_5081_50810701_1_dialog_content = "<color=#e8d9bb>Thud—</color>",
  ui_story_5081_50810701_2_dialog_content = "¿Soy yo, o estas máquinas realmente parecen que provienen de Illumina?",
  ui_story_5081_50810701_3_dialog_content = "Me pregunto qué quieren beber Jomu y Odi?",
  ui_story_5081_50810701_4_dialog_content = "¿Quizás algo \"clásico y accesible\"?",
  ui_story_5081_50810701_5_dialog_content = "<color=#e8d9bb>Thud—</color>",
  ui_story_5081_50810701_6_dialog_content = "...",
  ui_story_5081_50810701_7_dialog_content = "Sabía que alguien me estaba mirando.",
  ui_story_5081_50810701_8_dialog_content = "¿Quién está ahí?",
  ui_story_5081_50810701_9_dialog_content = "¡Ah! Yo... ¡Lo siento!",
  ui_story_5081_50810701_10_dialog_content = "¿Eh? Eres tú, Batia.",
  ui_story_5081_50810701_11_dialog_content = "Lo siento por gritar hace un momento, pensé que alguien estaba intentando robar mis fichas o algo así.",
  ui_story_5081_50810701_12_dialog_content = "E-Es así... E-Esto...",
  ui_story_5081_50810701_13_dialog_content = "¡Guau! ¿Es eso... helado? ¿Pero por qué no lo estás comiendo? ¡Parece que está a punto de derretirse!",
  ui_story_5081_50810701_14_dialog_content = "E-Esto es para ti...",
  ui_story_5081_50810701_15_dialog_content = "Espera... ¿Compraste esto solo para mí?",
  ui_story_5081_50810701_16_dialog_content = "Sí.",
  ui_story_5081_50810701_17_dialog_content = "¡Entonces será mejor que lo coma rápido! Afortunadamente, aún no se ha derretido completamente...",
  ui_story_5081_50810701_18_dialog_content = "No estoy seguro de que todavía se pueda llamar \"helado\".",
  ui_story_5081_50810701_19_dialog_content = "¡Pero está bien! ¡Siempre podemos comprar más! Además, todavía es perfectamente comestible. ¡Vaya, eso está frío!",
  ui_story_5081_50810701_20_dialog_content = "¿En serio? Estoy tan feliz de que te guste.",
  ui_story_5081_50810701_21_dialog_content = "Además... quiero agradecerte.",
  ui_story_5081_50810701_22_dialog_content = "Por hacer equipo conmigo... y-y por ayudarme a manejar a ese retador demasiado entusiasta.",
  ui_story_5081_50810701_23_dialog_content = "¡Debería ser yo quien te agradezca! Nunca hubiera tenido una oportunidad sin tu ayuda.",
  ui_story_5081_50810701_24_dialog_content = "Y como tuviste la amabilidad de traerme helado, ¿por qué no te invito a una bebida? ¿Jugo o café?",
  ui_story_5081_50810701_25_dialog_content = "Um... El jugo de tomate, por favor...",
  ui_story_5081_50810701_26_dialog_content = "¡Ahora mismo!",
  ui_story_5081_50810701_27_dialog_content = "<color=#e8d9bb>Thud—</color>",
  ui_story_5081_50810701_28_dialog_content = "¡Aquí tienes! ¿Así que te gusta este tipo de bebida, eh?",
  ui_story_5081_50810701_29_dialog_content = "Ajá... No salgo mucho durante el día, así que dependo de cosas como esta para la nutrición... También funciona bastante bien.",
  ui_story_5081_50810701_30_dialog_content = "Uh, perdón por preguntar... ¿pero tiene que ver con ser parte murciélago?",
  ui_story_5081_50810701_31_dialog_content = "Lo hace... por eso salir es un problema para mí.",
  ui_story_5081_50810701_32_dialog_content = "Interactuar con los demás... tampoco es muy fácil para mí.",
  ui_story_5081_50810701_33_dialog_content = "Soy un auroriano como cualquier otro... pero no del todo.",
  ui_story_5081_50810701_34_dialog_content = "Hay muchas cosas que otras personas pueden hacer... que yo nunca podría.",
  ui_story_5081_50810701_35_dialog_content = "¿Es por eso que te quedas en casa jugando hasta ser el mejor en ellos?",
  ui_story_5081_50810701_36_dialog_content = "Es-Es vergonzoso, ¿no es así?",
  ui_story_5081_50810701_37_dialog_content = "¡Por supuesto que no! De hecho, ¡es un logro increíble!",
  ui_story_5081_50810701_38_dialog_content = "Convertirse en el mejor en un solo juego es un logro impresionante para cualquier jugador.",
  ui_story_5081_50810701_39_dialog_content = "¡Pero tu nombre está en la cima de todas las tablas de clasificación aquí, o incluso en todo Astra!",
  ui_story_5081_50810701_40_dialog_content = "\"B\" ya es un héroe y un símbolo en su propio derecho, ¡quizás incluso una leyenda! Cuando llegué a esta tienda...",
  ui_story_5081_50810701_41_dialog_content = "¡Lo hice con la intención de ampliar también mis propios horizontes!",
  ui_story_5081_50810701_42_dialog_content = "...",
  ui_story_5081_50810701_43_dialog_content = "P-Pero no viniste aquí con la intención de jugar juegos.",
  ui_story_5081_50810701_44_dialog_content = "¡Jaja, eso es cierto! Cuando aparecí por primera vez, mi objetivo era claro: encontrar a mi amigo perdido Gronru.",
  ui_story_5081_50810701_45_dialog_content = "Ves, ella fue la que me presentó muchos juegos.",
  ui_story_5081_50810701_46_dialog_content = "La mayoría de las veces, simplemente los aceptaba porque ella me los daba.",
  ui_story_5081_50810701_47_dialog_content = "Y solo los jugaría porque venían de un amigo.",
  ui_story_5081_50810701_48_dialog_content = "Por eso nunca imaginé que me gustaría un salón de juegos tanto como ahora.",
  ui_story_5081_50810701_49_dialog_content = "Cuando pienso en todos los partidos que jugamos hoy...",
  ui_story_5081_50810701_50_dialog_content = "Me doy cuenta de cuánto me he divertido aquí.",
  ui_story_5081_50810701_51_dialog_content = "Hmm... Entiendo.",
  ui_story_5081_50810701_52_dialog_content = "Realmente eres capaz de disfrutar los videojuegos.",
  ui_story_5081_50810701_53_dialog_content = "No sé si es por mi historia, mis objetivos, o tal vez algunas de las responsabilidades que estoy asumiendo...",
  ui_story_5081_50810701_54_dialog_content = "Pero... me resulta un poco difícil aceptar que me gusta este tipo de cosas.",
  ui_story_5081_50810701_55_dialog_content = "Así que poder jugar videojuegos como este, sin ningún miedo a ser juzgado, me ayuda a enfrentar ese conflicto interno de frente...",
  ui_story_5081_50810701_56_dialog_content = "Si pudiera disfrutar de los juegos de manera pura como tú y Gronru, apuesto a que podríamos entendernos aún más.",
  ui_story_5081_50810701_57_dialog_content = "<size=30>Gronru... Estoy tan celoso de que ella tenga un amigo como tú...</size>",
  ui_story_5081_50810701_58_dialog_content = "¿Así que la conoces?",
  ui_story_5081_50810701_59_dialog_content = "M-Más o menos... Después de todo, es una jugadora veterana y ha hecho muchas contribuciones especiales a la comunidad.",
  ui_story_5081_50810701_60_dialog_content = "P-Pero eso es todo lo que sé sobre ella... ¡Por favor, no me hagas más preguntas!",
  ui_story_5081_50810701_61_dialog_content = "¡Guau... Esos dos son espectaculares!",
  ui_story_5081_50810701_62_dialog_content = "¡Oh! Eh, ¿escuchaste eso? ¡Parece que podríamos tener algunos nuevos desafiantes en la sala de juegos!",
  ui_story_5081_50810701_63_dialog_content = "N-Nos convendría ir a verlo!",
  ui_story_5081_50810701_64_dialog_content = "(¿Ella está pidiendo encontrarse con los desafiantes ella misma? Eso es algo raro de ver...)",
  ui_story_5081_50810701_65_dialog_content = "(Parece que está evadiendo el tema. ¿Podría estar hablando de Gronru?)",
  ui_story_5081_50810701_66_dialog_content = "(Tan sospechoso como parece, creo que jugar juegos es mi mejor oportunidad para descubrir más.)",
  ui_story_5081_50810701_67_dialog_content = "¡Claro, vámonos allá!",
  ui_story_5081_50810701_68_dialog_content = "<color=#e8d9bb>Para entonces, dos retadores con estilos muy únicos ya habían captado la atención de toda la sala de juegos.</color>",
  ui_story_5081_50810701_69_dialog_content = "<color=#e8d9bb>Uno de ellos está sentado en el sofá de una manera fresca.</color>",
  ui_story_5081_50810701_70_dialog_content = "¿Esta tienda está diseñada para verse tan retro a propósito?",
  ui_story_5081_50810701_71_dialog_content = "Las luces y decoraciones tienen estilo, y han sido colocadas tan perfectamente en toda la sala de juegos.",
  ui_story_5081_50810701_72_dialog_content = "¡No puedo esperar para darlo todo en este desafío!",
  ui_story_5081_50810701_73_dialog_content = "<color=#e8d9bb>El otro está saltando alrededor de la tienda con emoción como un conejo.</color>",
  ui_story_5081_50810701_74_dialog_content = "¡Guau, es esta una máquina de garra? ¡Los premios dentro son taaan lindos!",
  ui_story_5081_50810701_75_dialog_content = "¡Y este debe ser el lugar donde intercambias puntos por premios! Oh, quiero todo lo que tienen...",
  ui_story_5081_50810701_76_dialog_content = "Dime, ¿puedo llevarme todos los premios si sigo ganando?",
  ui_story_5081_50810701_77_dialog_content = "¡Humph!",
  ui_story_5081_50810701_78_dialog_content = "Por supuesto que puedes. El truco está en ganar esa cantidad de veces primero.",
  ui_story_5081_50810701_79_dialog_content = "Pero eso no será necesario. Como dueño del arcade, tengo la última palabra por aquí.",
  ui_story_5081_50810701_80_dialog_content = "Si eres capaz de vencerme en un juego, puedes tomar lo que quieras, y tanto como quieras.",
  ui_story_5081_50810701_81_dialog_content = "¿Oh? Ahora estamos hablando...",
  ui_story_5081_50810701_82_dialog_content = "He oído hablar sobre la legendaria jugadora \"B\" y su arcade, pero nunca esperé que fuera tan audaz. ¡Me gusta!",
  ui_story_5081_50810701_83_dialog_content = "¡Guau, eso es súper generoso de tu parte! En ese caso... ¡Voy a hacer todo lo posible para vencerte!",
  ui_story_5081_50810701_84_dialog_content = "¡Guau! Parece que tenemos algunos nuevos desafiantes. ¡Vamos a aplaudir a la Bruja Salvaje y a la Chica Pastel!",
  ui_story_5081_50810701_85_dialog_content = "¡Los dos jugadores harán sus desafíos al mismo tiempo! <size=30>¡Pero mi pregunta es, quiénes son exactamente? ¿Un arrogante emprendedor y un coleccionista de mercancías?</size>",
  ui_story_5081_50810701_86_dialog_content = "Vamos a emocionarnos por otro emocionante partido a continuación—",
  ui_story_5081_50810702_1_dialog_content = "Parece que el fuego de los videojuegos no quema tanto como las llamas reales...",
  ui_story_5081_50810702_2_dialog_content = "¡He hecho lo mejor que pude también! Parece que tendré que comprar todas estas cosas lindas para mí...",
  ui_story_5081_50810702_3_dialog_content = "Oye, señor Cocodrilo, ¿podría probar esa insignia por un segundo?",
  ui_story_5081_50810702_4_dialog_content = "Lo siento señorita, pero tienes que cambiar fichas por eso.",
  ui_story_5081_50810702_5_dialog_content = "¡Oh, está bien! ¡Iré a buscar algo ahora mismo!",
  ui_story_5081_50810702_6_dialog_content = "... ¿Y ella simplemente se escapó?",
  ui_story_5081_50810702_7_dialog_content = "Oye, ¿estarías interesado en hacer equipo conmigo, verdad?",
  ui_story_5081_50810702_8_dialog_content = "¡Con el legendario jugador \"B\" a mi lado, podríamos iniciar una nueva era de juegos en el mundo!",
  ui_story_5081_50810702_9_dialog_content = "¡Cuando llegue ese día, tu sala de juegos podría verse abrumada con todos los nuevos clientes que tendrás!",
  ui_story_5081_50810702_10_dialog_content = "Yo... Eh... Aunque hacer crecer la comunidad de juegos no es necesariamente algo malo...",
  ui_story_5081_50810702_11_dialog_content = "Nunca he hecho algo tan extremo, y... y realmente no quiero hacerlo tampoco! Lo siento...",
  ui_story_5081_50810702_12_dialog_content = "Fuerte pero humilde, y apegado a lo que sabes, ¿eh?",
  ui_story_5081_50810702_13_dialog_content = "Está bien. Lo más importante es que lograste captar mi atención.",
  ui_story_5081_50810702_14_dialog_content = "Búscame cuando quieras hacer equipo.",
  ui_story_5081_50810702_15_dialog_content = "¿T-Tú también tienes uno de esos?",
  ui_story_5081_50810702_16_dialog_content = "¿Uno de qué?",
  ui_story_5081_50810702_17_dialog_content = "Una tarjeta con tu nombre en ella. Conseguí una antes.",
  ui_story_5081_50810702_18_dialog_content = "Ella se refiere a una tarjeta de presentación.",
  ui_story_5081_50810702_19_dialog_content = "Jaja, ¡por supuesto que tengo uno! Aquí tienes, espero saber de ti pronto.",
  ui_story_5081_50810702_20_dialog_content = "Uf...",
  ui_story_5081_50810702_21_dialog_content = "Diría que eso salió bastante bien, teniendo en cuenta todo...",
  ui_story_5081_50810702_22_dialog_content = "¿Por qué no preguntaste si se estaban divirtiendo esta vez?",
  ui_story_5081_50810702_23_dialog_content = "Oh...",
  ui_story_5081_50810702_24_dialog_content = "¿D-Hice la pregunta equivocada otra vez?",
  ui_story_5081_50810702_25_dialog_content = "I-Incluso para alguien como yo, es fácil ver que se divirtieron jugando ese juego...",
  ui_story_5081_50810702_26_dialog_content = "Pero cuando los vi en el juego justo ahora...",
  ui_story_5081_50810702_27_dialog_content = "No parecían tan emocionados o tan inmersos como tú, ¿verdad?",
  ui_story_5081_50810702_28_dialog_content = "Te enfadaste tanto conmigo porque no tenía la cabeza en el juego... ¡Espero que ellos no te hayan molestado también!",
  ui_story_5081_50810702_29_dialog_content = "No realmente, no. Esos dos son más del tipo social cuando se trata de jugar.",
  ui_story_5081_50810702_30_dialog_content = "¿Recuerdas lo que dijo antes ese conocedor de antigüedades?",
  ui_story_5081_50810702_31_dialog_content = "Algo sobre los videojuegos siendo la fusión de tecnología y entretenimiento, ¿verdad?",
  ui_story_5081_50810702_32_dialog_content = "Sí. Los videojuegos son mucho más que algo para jugar.",
  ui_story_5081_50810702_33_dialog_content = "Un buen juego es como una obra de arte, cada aspecto de él tiene el potencial de atraer a los jugadores.",
  ui_story_5081_50810702_34_dialog_content = "Algunas personas juegan por la historia y se centran en los detalles más finos del mundo dentro del juego.",
  ui_story_5081_50810702_35_dialog_content = "A otros les interesa más el arte y el diseño de un juego e incluso invitan a otras personas a jugar roles con ellos.",
  ui_story_5081_50810702_36_dialog_content = "A veces, juegos temáticos como ese generan enormes olas de interés. Así es como muchas personas se convierten en jugadores en primer lugar.",
  ui_story_5081_50810702_37_dialog_content = "Hay más en los videojuegos que solo superar niveles...",
  ui_story_5081_50810702_38_dialog_content = "Por eso, las personas que no están enfocadas en ganar también son dignas de disfrutar los juegos.",
  ui_story_5081_50810702_39_dialog_content = "Odi mencionó algo similar más temprano hoy. Dijo que la parte más importante de un videojuego es el jugador.",
  ui_story_5081_50810702_40_dialog_content = "Estoy de acuerdo. Es difícil para los jugadores encontrar alegría en los videojuegos cuando se mantienen alejados de la comunidad de jugadores.",
  ui_story_5081_50810702_41_dialog_content = "Por eso dejé que Gronru me convenciera de hacerme cargo de esta sala de juegos...",
  ui_story_5081_50810702_42_dialog_content = "Gronru de nuevo, ¿eh?",
  ui_story_5081_50810702_43_dialog_content = "¿D-Dije eso? ¡Lo siento, no quise mencionarla de nuevo! ¡Solo olvídalo!",
  ui_story_5081_50810702_44_dialog_content = "Sí, conozco la rutina. No me entrometeré más, lo prometo.",
  ui_story_5081_50810702_45_dialog_content = "A pesar de cuánto tiendes a minimizar las cosas, creo que esto es algo que solo tú puedes lograr...",
  ui_story_5081_50810702_46_dialog_content = "¿Qué es eso?",
  ui_story_5081_50810702_47_dialog_content = "Dirigiendo esta sala de juegos y dando a los jugadores un lugar para relajarse y divertirse.",
  ui_story_5081_50810702_48_dialog_content = "¿Quién más que el legendario \"B\" podría haberlo hecho tan bien?",
  ui_story_5081_50810702_49_dialog_content = "P-Pero no soy bueno para socializar con la gente en absoluto! No creo que esté capacitado para brindar a los jugadores ningún tipo de experiencia positiva...",
  ui_story_5081_50810702_50_dialog_content = "Solo estoy proporcionando un lugar, eso es todo.",
  ui_story_5081_50810702_51_dialog_content = "¿Es eso lo que piensas?",
  ui_story_5081_50810702_52_dialog_content = "Porque para mí, parecía que interactuaste con los desafiantes de hoy bastante bien.",
  ui_story_5081_50810702_53_dialog_content = "¿Sabes? Hay una razón por la que la gente te respeta y se reúne en este lugar.",
  ui_story_5081_50810702_54_dialog_content = "No soy tan especial... y aunque me elogies, aún no te lo diré—",
  ui_story_5081_50810702_55_dialog_content = "¿Dime qué?",
  ui_story_5081_50810702_56_dialog_content = "¡Jefe! ¡Tenemos otro nuevo visitante!",
  ui_story_5081_50810702_57_dialog_content = "¿Es un retador? Estaré allí enseguida...",
  ui_story_5081_50810702_58_dialog_content = "No exactamente...",
  ui_story_5081_50810702_59_dialog_content = "Lleva un uniforme de Illumina y habla como si estuviera siguiendo un guion. No creo que sea ningún tipo de jugador. Además...",
  ui_story_5081_50810702_60_dialog_content = "No te has metido en el lado malo de alguien recientemente, ¿verdad PlayerName?",
  ui_story_5081_50810702_61_dialog_content = "¡Porque ese tipo preguntó por ti por tu nombre!",
  ui_story_5081_50810801_1_dialog_content = "¿Alguien con un uniforme de Illumina me está buscando? No me digas...",
  ui_story_5081_50810801_2_dialog_content = "Oh...",
  ui_story_5081_50810801_3_dialog_content = "Finalmente estás aquí, PlayerName. ¿Podría hablar contigo, por favor?",
  ui_story_5081_50810801_4_dialog_content = "Claro... No te preocupes, todos están demasiado ocupados jugando para notarnos.",
  ui_story_5081_50810801_5_dialog_content = "Es bueno verte de nuevo, Oficial de Inteligencia Anatoli.",
  ui_story_5081_50810801_6_dialog_content = "Igualmente, PlayerName. Iré directo al grano.",
  ui_story_5081_50810801_7_dialog_content = "Primero, permíteme agradecerte por tus esfuerzos en ayudar a Illumina durante este momento crítico.",
  ui_story_5081_50810801_8_dialog_content = "Si me permites preguntar, ¿cómo está procediendo tu investigación?",
  ui_story_5081_50810801_9_dialog_content = "Para decirlo de una manera, he vencido a unos cinco de los ocho gimnasios...",
  ui_story_5081_50810801_10_dialog_content = "Entiendo. ¿Quieres decir que tu misión está completada en un sesenta y dos punto cinco por ciento?",
  ui_story_5081_50810801_11_dialog_content = "Bueno, también tengo que vencer a los Cuatro Élites...",
  ui_story_5081_50810801_12_dialog_content = "¿Podría pedirte que expliques las cosas en términos sencillos?",
  ui_story_5081_50810801_13_dialog_content = "Jaja... Es un poco difícil cuantificar el progreso cuando estás buscando a alguien.",
  ui_story_5081_50810801_14_dialog_content = "¡Pero he estado haciendo todo lo posible para llevar a cabo esta misión para Migard y el Comité! Confía en mí, ¡lo lograré!",
  ui_story_5081_50810801_15_dialog_content = "¿Es eso cierto? De nuevo, te agradezco por tus contribuciones a Illumina.",
  ui_story_5081_50810801_16_dialog_content = "Según mi información, este lugar tiene algunos juegos muy atractivos en reserva.",
  ui_story_5081_50810801_17_dialog_content = "Junto con esta atmósfera cómoda, es el lugar perfecto para olvidar las preocupaciones y perderse en mundos virtuales.",
  ui_story_5081_50810801_18_dialog_content = "Cuando te estaba esperando, me preocupaba que también te hubieras perdido en estos mundos... pero parece que estaba pensando demasiado en las cosas.",
  ui_story_5081_50810801_19_dialog_content = "¡Nunca perdería de vista una misión tan importante! Realmente no deberías bromear así, Anatoli! Jajaja...",
  ui_story_5081_50810801_20_dialog_content = "¿Así que solo viniste aquí para obtener un informe de estado para Migard?",
  ui_story_5081_50810801_21_dialog_content = "Para ser franco, no. De hecho, uno podría decir que tenemos un poco de conflicto entre nosotros.",
  ui_story_5081_50810801_22_dialog_content = "¿Conflicto?",
  ui_story_5081_50810801_23_dialog_content = "No hay nada de qué preocuparse. Cuando se trata de la misión, nuestros objetivos siguen siendo los mismos.",
  ui_story_5081_50810801_24_dialog_content = "Los jugadores aquí están mucho más interesados en la tecnología antigua que la mayoría de las personas. Creo que podría recopilar información muy interesante de ellos.",
  ui_story_5081_50810801_25_dialog_content = "... Si tan solo pudiera quedarme un poco más.",
  ui_story_5081_50810801_26_dialog_content = "Si así es como te sientes, ¿por qué no encontramos algo para que juegues?",
  ui_story_5081_50810801_27_dialog_content = "Bueno, hay un juego que ha despertado mi interés.",
  ui_story_5081_50810801_28_dialog_content = "El llamado Crisis Eclipsite.",
  ui_story_5081_50810801_29_dialog_content = "Se supone que los Eclipsites en este juego son bastante realistas, así como las armas que están disponibles para los jugadores.",
  ui_story_5081_50810801_30_dialog_content = "A veces me pregunto si se desarrolló a partir de un programa de entrenamiento de Illumina que fracasó.",
  ui_story_5081_50810801_31_dialog_content = "¿Por qué no lo pruebas entonces? Después de todo, todavía tengo muchos tokens.",
  ui_story_5081_50810801_32_dialog_content = "Creo que sí. Aprecio mucho tu generosidad.",
  ui_story_5081_50810801_33_dialog_content = "<color=#e8d9bb>Toca, toca, toca, toca—</color>",
  ui_story_5081_50810801_34_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5081_50810801_35_dialog_content = "Graah...",
  ui_story_5081_50810801_36_dialog_content = "¡Los controles son sorprendentemente fluidos y receptivos! ¡Muy desafiante para los jugadores!",
  ui_story_5081_50810801_37_dialog_content = "<color=#e8d9bb>Toca, toca, toca, toca—</color>",
  ui_story_5081_50810801_38_dialog_content = "¡El combate también es muy realista! Desafortunadamente, las fichas no se pueden usar para revivir a nuestros camaradas caídos en la vida real...",
  ui_story_5081_50810801_39_dialog_content = "...",
  ui_story_5081_50810801_40_dialog_content = "¿Eh? Aún no has terminado el nivel, Anatoli.",
  ui_story_5081_50810801_41_dialog_content = "No vine aquí para jugar juegos. Solo quería probarlos brevemente por mí mismo.",
  ui_story_5081_50810801_42_dialog_content = "Y ahora que lo hice, no puedo evitar sentirme un poco arrepentido.",
  ui_story_5081_50810801_43_dialog_content = "¿Arrepentido?",
  ui_story_5081_50810801_44_dialog_content = "Este juego tiene el potencial de servir como un programa de entrenamiento adecuado y ayudarnos enormemente en las batallas futuras...",
  ui_story_5081_50810801_45_dialog_content = "Pero parece que los jugadores aquí solo lo valoran como una fuente de entretenimiento.",
  ui_story_5081_50810801_46_dialog_content = "Me hace preguntarme, si tanta gente encuentra tanta alegría en destruir a los Eclipsites en los juegos...",
  ui_story_5081_50810801_47_dialog_content = "¿No sería mejor que su tiempo y energía se gastaran eliminando a los Eclipsites reales en el campo de batalla?",
  ui_story_5081_50810801_48_dialog_content = "¿Es este realmente el valor de los videojuegos de Astra? Quizás no lo entiendo completamente, pero parece una pérdida de—",
  ui_story_5081_50810801_49_dialog_content = "<color=#e8d9bb>Toca, toca, toca, toca—</color>",
  ui_story_5081_50810801_50_dialog_content = "¿Eh? Es—",
  ui_story_5081_50810801_51_dialog_content = "Abandonar un juego cuando aún no está terminado... Si alguien está siendo derrochador, eres tú.",
  ui_story_5081_50810801_52_dialog_content = "No permitiré este tipo de comportamiento en mi sala de juegos.",
  ui_story_5081_50810801_53_dialog_content = "¿Tu sala de juegos, dices? Debes ser el dueño.",
  ui_story_5081_50810801_54_dialog_content = "Perdóname si violé las reglas de tu establecimiento. Asegúrate de que terminaré de jugar a partir de ahora.",
  ui_story_5081_50810801_55_dialog_content = "Eres un soldado de Illumina, ¿verdad?",
  ui_story_5081_50810801_56_dialog_content = "De hecho, lo soy.",
  ui_story_5081_50810801_57_dialog_content = "¡Entonces reúne toda tu habilidad y experiencia de entrenamiento, intenta superar mi puntuación!",
  ui_story_5081_50810801_58_dialog_content = "No tengo ningún deseo de competir, pero si esto es lo que deseas...",
  ui_story_5081_50810801_59_dialog_content = "<color=#e8d9bb>Toc, toc, toc—toc, toc, toc, toc</color>",
  ui_story_5081_50810801_60_dialog_content = "<color=#e8d9bb>¡Boom! ¡Boom!</color>",
  ui_story_5081_50810801_61_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5081_50810801_62_dialog_content = "¡A-Asombroso! ¡Están jugando como si estuvieran poseídos por monstruos!",
  ui_story_5081_50810801_63_dialog_content = "Pero Anatoli... De alguna manera, su puntuación es mucho más baja que la de ella!",
  ui_story_5081_50810801_64_dialog_content = "No creo... haberla visto jugar tan seriamente antes...",
  ui_story_5081_50810801_65_dialog_content = "En tu opinión... ¿soy indigno de esto?",
  ui_story_5081_50810801_66_dialog_content = "... Perdón, pero ¿estás hablando conmigo?",
  ui_story_5081_50810801_67_dialog_content = "Sí. Como alguien que no puede luchar contra los Eclipsites en la vida real... ¿Crees que tengo el derecho de luchar contra ellos en un videojuego?",
  ui_story_5081_50810801_68_dialog_content = "¿No es posible que algunas personas simplemente no nacieron para luchar contra los Eclipsites... o incluso para salir de la seguridad de sus hogares?",
  ui_story_5081_50810801_69_dialog_content = "Pero incluso así, tal vez todavía quieran hacer frente a los monstruos que han invadido nuestro mundo...",
  ui_story_5081_50810801_70_dialog_content = "Incluso si solo es dando a todos un lugar para reunirse y divertirse.",
  ui_story_5081_50810801_71_dialog_content = "Una persona así... todavía tiene algo que ofrecer al mundo, ¿no crees?",
  ui_story_5081_50810801_72_dialog_content = "Yo...",
  ui_story_5081_50810801_73_dialog_content = "No pierdas la concentración o perderás.",
  ui_story_5081_50810801_74_dialog_content = "Perdóname.",
  ui_story_5081_50810801_75_dialog_content = "Concentraré todas mis fuerzas en terminar este juego...",
  ui_story_5081_50810802_1_dialog_content = "<color=#e8d9bb>¡Misión Cumplida!</color>",
  ui_story_5081_50810802_2_dialog_content = "¿Ya terminó? Apenas puedo creer que ya haya pasado tanto tiempo.",
  ui_story_5081_50810802_3_dialog_content = "O que perdí por un margen tan grande...",
  ui_story_5081_50810802_4_dialog_content = "Debo admitir, tu habilidad para disparar es tan aguda como tu destreza en los videojuegos.",
  ui_story_5081_50810802_5_dialog_content = "Creo que tus habilidades solo son superadas por los Aurorians que han pasado por el entrenamiento de combate especial del Oficial Yingel...",
  ui_story_5081_50810802_6_dialog_content = "¿Te divertiste?",
  ui_story_5081_50810802_7_dialog_content = "¿Mmm?",
  ui_story_5081_50810802_8_dialog_content = "¡Claro que sí! Si tuviera que evaluar la calidad de este juego, le daría la calificación más alta posible.",
  ui_story_5081_50810802_9_dialog_content = "Pero, ¿podrías decirme por qué todavía estás jugando?",
  ui_story_5081_50810802_10_dialog_content = "¡Oh! No te preocupes por mí, solo estoy terminando el resto de las misiones secundarias... Me molesta si no termino un juego completo.",
  ui_story_5081_50810802_11_dialog_content = "Y también... ¡S-siento que soy mucho más valiente al hablar con la gente si estoy mirando una pantalla!",
  ui_story_5081_50810802_12_dialog_content = "No todos tienen la oportunidad de luchar contra los Eclipsites en el frente de batalla.",
  ui_story_5081_50810802_13_dialog_content = "Algunas personas trabajan en los campos, mientras que otras construyen defensas...",
  ui_story_5081_50810802_14_dialog_content = "Algunos vuelan por todo Astra entregando mensajes importantes, y otros se quedan en sus laboratorios resolviendo problemas técnicos...",
  ui_story_5081_50810802_15_dialog_content = "Pero creo que todos merecen una oportunidad para relajarse y descomprimirse, ¡así como una oportunidad para desafiarse a sí mismos!",
  ui_story_5081_50810802_16_dialog_content = "Algo que les ayude a entender el peligro de los Eclipsites mientras también renueva su deseo de trabajar hacia un objetivo común...",
  ui_story_5081_50810802_17_dialog_content = "¿No crees que es una buena manera de conectar a los Aurorianos que no pueden luchar contra los Eclipsites con aquellos que sí pueden?",
  ui_story_5081_50810802_18_dialog_content = "¿Qué, exactamente?",
  ui_story_5081_50810802_19_dialog_content = "Ella está hablando del juego que acabas de jugar, Anatoli.",
  ui_story_5081_50810802_20_dialog_content = "También vi tus expresiones mientras jugabas...",
  ui_story_5081_50810802_21_dialog_content = "Serio, diligente, orgulloso de tus logros y molesto por tus fracasos.",
  ui_story_5081_50810802_22_dialog_content = "Esas emociones no son diferentes a las que experimentas fuera de los videojuegos, por eso deberías darle una respuesta honesta a Batia.",
  ui_story_5081_50810802_23_dialog_content = "¿Realmente crees que las cosas solo valen la pena si pueden usarse en la lucha contra los Eclipsites?",
  ui_story_5081_50810802_24_dialog_content = "...",
  ui_story_5081_50810802_25_dialog_content = "Por favor perdóname por no darme cuenta de mi error antes...",
  ui_story_5081_50810802_26_dialog_content = "Algunas de las cosas que acabo de decir... eran para personas que ni siquiera están aquí ahora mismo.",
  ui_story_5081_50810802_27_dialog_content = "Quizás estaba tratando de desahogar mi estrés y frustración hacia ellos.",
  ui_story_5081_50810802_28_dialog_content = "Por favor, permíteme usar el conocimiento que adquirí mientras jugaba este juego para rectificar mi respuesta.",
  ui_story_5081_50810802_29_dialog_content = "Claro, adelante.",
  ui_story_5081_50810802_30_dialog_content = "Los videojuegos no son inútiles, de hecho, están lejos de serlo.",
  ui_story_5081_50810802_31_dialog_content = "La atmósfera de esta sala de juegos es un reflejo directo de la misión original de Illumina.",
  ui_story_5081_50810802_32_dialog_content = "¿No son nuestras luchas y sacrificios interminables con el propósito de crear un mundo pacífico, libre de la amenaza de los Eclipsites?",
  ui_story_5081_50810802_33_dialog_content = "Un mundo donde aquellos que no pueden defenderse de los Eclipsites también pueden tener vidas largas y felices...",
  ui_story_5081_50810802_34_dialog_content = "Los innumerables sacrificios que hemos hecho hasta este punto son lo que realmente importa.",
  ui_story_5081_50810802_35_dialog_content = "Luchar y sacrificar simplemente por hacerlo es perder de vista nuestros objetivos y deseos.",
  ui_story_5081_50810802_36_dialog_content = "Ah... Mis disculpas por dar una respuesta tan larga.",
  ui_story_5081_50810802_37_dialog_content = "Pero mi corazón y mente están mucho más tranquilos ahora... Gracias, PlayerName y señorita Batia.",
  ui_story_5081_50810802_38_dialog_content = "...",
  ui_story_5081_50810802_39_dialog_content = "No dije nada, ya sabes. ¿Quizás esto era algo que el juego estaba destinado a mostrarte?",
  ui_story_5081_50810802_40_dialog_content = "De hecho, nunca consideré los pensamientos y sentimientos de aquellos que no pueden luchar contra los Eclipsites antes de jugar este juego.",
  ui_story_5081_50810802_41_dialog_content = "Pero ahora siento que he ganado una comprensión un poco mejor.",
  ui_story_5081_50810802_42_dialog_content = "Debo mantener un enfoque más abierto al reunir información de ahora en adelante...",
  ui_story_5081_50810802_43_dialog_content = "¡No olvides relajarte y disfrutar de vez en cuando! ¡Siempre eres bienvenido en la sala de juegos!",
  ui_story_5081_50810802_44_dialog_content = "Gracias. Solo desearía que el Oficial Yingel también pudiera ver las cosas de esta manera.",
  ui_story_5081_50810802_45_dialog_content = "<size=30>Últimamente se ha estado esforzando mucho, quizás más de lo necesario.</size>",
  ui_story_5081_50810802_46_dialog_content = "... Pero no te preocupes. Me aseguraré de que este asunto llegue a una conclusión satisfactoria.",
  ui_story_5081_50810802_47_dialog_content = "Uh, ¿qué pasa?",
  ui_story_5081_50810802_48_dialog_content = "Te contactaré una vez que se haya resuelto, tenlo por seguro.",
  ui_story_5081_50810802_49_dialog_content = "Hasta entonces, por favor espera pacientemente mis buenas noticias...",
  ui_story_5081_50810802_50_dialog_content = "... ¿Se fue él?",
  ui_story_5081_50810802_51_dialog_content = "Sí... Y parece que nos ocultó algo importante.",
  ui_story_5081_50810802_X51_dialog_content = "(Después de despedir a Jomu con Odi y ayudar a Batia con algunas tareas, el día casi había terminado.)",
  ui_story_5081_50810802_X52_dialog_content = "(Los clientes se iban por la noche. Cuando Batia y yo éramos los únicos que quedaban en la sala de juegos, decidimos cerrar la tienda y salir a dar un paseo.)",
  ui_story_5081_50810802_X53_dialog_content = "Gracias...",
  ui_story_5081_50810802_X54_dialog_content = "¿Por qué me estás agradeciendo esta vez?",
  ui_story_5081_50810802_52_dialog_content = "¡Por muchas cosas! Primero que nada, gracias por ayudarme a hablar con ese soldado de Illumina... Pero tengo que preguntar...",
  ui_story_5081_50810802_53_dialog_content = "Lo que le dije hace un momento... ¿Fui demasiado lejos?",
  ui_story_5081_50810802_54_dialog_content = "Al final... Solo soy un inútil recluso que solo sabe cómo jugar juegos...",
  ui_story_5081_50810802_55_dialog_content = "Esa es la razón por la que valoro juegos como este, así que yo...",
  ui_story_5081_50810802_56_dialog_content = "¡No te has excedido, así que deja de dudar tanto de ti mismo!",
  ui_story_5081_50810802_57_dialog_content = "No creo que haya un solo Aurorian en Astra que sea peor que yo luchando contra los Eclipsites.",
  ui_story_5081_50810802_58_dialog_content = "¿Pero eso significa que mi existencia no tiene valor?",
  ui_story_5081_50810802_59_dialog_content = "¡N-No... Eso no es lo que quise decir en absoluto! Es solo que...",
  ui_story_5081_50810802_60_dialog_content = "Ese oficial de inteligencia también hizo muchos buenos puntos... No debería haberlo cuestionado de esa manera.",
  ui_story_5081_50810802_61_dialog_content = "Pero sabes... en realidad estoy algo emocionado de ver el futuro del que él habló...",
  ui_story_5081_50810802_62_dialog_content = "Un mundo libre de la amenaza de los Eclipsites... Es difícil imaginar algo tan maravilloso.",
  ui_story_5081_50810802_63_dialog_content = "Si ese día llega, entonces quizás el Ejercicio Militar Conjunto se convertirá en la convención de juegos más grande de Astra!",
  ui_story_5081_50810802_64_dialog_content = "Apuesto a que te verías tan genial parado en el podio de los ganadores y sosteniendo los trofeos del primer lugar en cada uno de los juegos—",
  ui_story_5081_50810802_65_dialog_content = "¡Detente! Nunca podría subir allí para aceptar un trofeo... Eso es cosa de Gronru, ¡no mía!",
  ui_story_5081_50810802_66_dialog_content = "Pero hasta que el mundo finalmente se deshaga de los Eclipsites...",
  ui_story_5081_50810802_67_dialog_content = "Puede que quiera jugar un juego donde pueda enfrentarlos con un equipo de poderosos Aurorianos...",
  ui_story_5081_50810802_68_dialog_content = "¡Y finalmente derrotarlos a todos!",
  ui_story_5081_50810802_69_dialog_content = "Aunque un solo videojuego nunca podría capturar todas las luchas de Astra...",
  ui_story_5081_50810802_70_dialog_content = "¡Todavía quiero experimentar y entender esas historias por mí mismo!",
  ui_story_5081_50810802_71_dialog_content = "Lo harás.",
  ui_story_5081_50810802_72_dialog_content = "¿Ah?",
  ui_story_5081_50810802_73_dialog_content = "¡Sé que podrás! Y si no puedes hacerlo por tu cuenta, solo pide a Gronru que haga más juegos para ti!",
  ui_story_5081_50810802_74_dialog_content = "Si ella nos incluye a todos nosotros y nuestras historias, apuesto a que sería uno de los mejores juegos de todos los tiempos.",
  ui_story_5081_50810802_75_dialog_content = "¿Pedirle que haga más juegos? Pero Gronru lo está pasando tan mal en este momento...",
  ui_story_5081_50810802_76_dialog_content = "B-Jefe! ¡Ven rápido!",
  ui_story_5081_50810802_77_dialog_content = "¡Problema! ¡Problema! ¡Chirrido!",
  ui_story_5081_50810802_78_dialog_content = "Increíble... ¡Esto es increíble!",
  ui_story_5081_50810802_79_dialog_content = "¿Qué está pasando?",
  ui_story_5081_50810802_80_dialog_content = "¡El jefe final de todos los desafiantes acaba de aparecer!",
  ui_story_5081_50810802_81_dialog_content = "Y con esos tentáculos, definitivamente parece la parte... Si no tienes cuidado...",
  ui_story_5081_50810802_82_dialog_content = "¡La leyenda de \"B\" será completamente arruinada! ¡Chirrido!",
  ui_story_5081_50810901_1_dialog_content = "I-Increíble...",
  ui_story_5081_50810901_2_dialog_content = "Está jugando cinco juegos al mismo tiempo... ¡No, seis!",
  ui_story_5081_50810901_3_dialog_content = "¡Y ella los está aplastando absolutamente!",
  ui_story_5081_50810901_4_dialog_content = "¡Este estilo de juego no se parece a nada que haya visto antes! Es como si ella hubiera sido creada con un único propósito...",
  ui_story_5081_50810901_5_dialog_content = "<size=45>¡Un arma definitiva construida solo para destruir leyendas!</size>",
  ui_story_5081_50810901_6_dialog_content = "No, no...",
  ui_story_5081_50810901_7_dialog_content = "Ella no es alguna arma definitiva ni nada por el estilo. Solo es un tipo especial de Auroriana...",
  ui_story_5081_50810901_8_dialog_content = "...",
  ui_story_5081_50810901_9_dialog_content = "No. 33, ¿qué te trae por aquí? ¿Viniste a jugar algunos juegos?",
  ui_story_5081_50810901_10_dialog_content = "... ¿Celestita?",
  ui_story_5081_50810901_11_dialog_content = "Un momento, por favor. Explicaré mi presencia una vez que complete la tarea en cuestión.",
  ui_story_5081_50810901_12_dialog_content = "<color=#e8d9bb>Los tentáculos de No. 33 se detienen lentamente y los datos que se muestran en sus ojos finalmente desaparecen.</color>",
  ui_story_5081_50810901_13_dialog_content = "<color=#e8d9bb>Las máquinas de arcade a su alrededor parpadean con mensajes de victoria, y sus puntuaciones aparecen en todas sus tablas de clasificación.</color>",
  ui_story_5081_50810901_14_dialog_content = "<color=#e8d9bb>Sin embargo, todavía hay una clara brecha entre sus puntuaciones y las de los que están en la cima.</color>",
  ui_story_5081_50810901_15_dialog_content = "Ahora que los juegos han terminado, permíteme explicar mis razones para venir aquí.",
  ui_story_5081_50810901_16_dialog_content = "Mi nombre es No. 33, un guardián de las antiguas ruinas de Northland.",
  ui_story_5081_50810901_17_dialog_content = "He sabido que un cartucho de datos de la civilización antigua ha sido descubierto y restaurado en este lugar. Como tal, solicité permiso a la Corte de Northland para viajar aquí.",
  ui_story_5081_50810901_18_dialog_content = "Mi intención original era comprarlo y analizar su contenido.",
  ui_story_5081_50810901_19_dialog_content = "Al llegar a esta sala de juegos, sin embargo, rápidamente me di cuenta de que todos estos juegos fueron creados restaurando datos antiguos...",
  ui_story_5081_50810901_20_dialog_content = "Y que sus archivos todavía eran dignos de análisis.",
  ui_story_5081_50810901_21_dialog_content = "Por esta razón, inmediatamente comencé a investigar sobre ellos. Estoy dispuesto a ofrecer pago por los datos que he recopilado y cualquier costo que pueda haber incurrido.",
  ui_story_5081_50810901_22_dialog_content = "E-Eso no será necesario. Estos juegos están hechos para jugar, y ya gastaste fichas para jugarlos.",
  ui_story_5081_50810901_23_dialog_content = "Pero usar tentáculos para jugar varios juegos... Nunca había visto algo así antes...",
  ui_story_5081_50810901_24_dialog_content = "¿Son fáciles de usar?",
  ui_story_5081_50810901_25_dialog_content = "¿Te refieres a mis tentáculos? Son parte del sistema de guardián y me permiten administrar varias estructuras dentro de las ruinas.",
  ui_story_5081_50810901_26_dialog_content = "No son particularmente útiles para la vida cotidiana de los Aurorianos, pero son realmente útiles al ejecutar órdenes.",
  ui_story_5081_50810901_27_dialog_content = "Y ahora, me doy cuenta de que también son bastante adecuados para jugar videojuegos. Comparado con otros jugadores en la sala de juegos...",
  ui_story_5081_50810901_28_dialog_content = "La capacidad de respuesta, precisión y sensibilidad de mis tentáculos me ofrecen claras ventajas, pero el conocimiento íntimo de los datos del juego también es bastante esencial.",
  ui_story_5081_50810901_29_dialog_content = "¿Esa es la razón por la que no pudiste obtener la puntuación más alta justo ahora, No. 33?",
  ui_story_5081_50810901_30_dialog_content = "¿O es simplemente porque esta fue tu primera vez jugando? ¡Quizás podrás encabezar las tablas de clasificación una vez que domines estos juegos!",
  ui_story_5081_50810901_31_dialog_content = "Debo adquirir más experiencia antes de llegar a cualquier conclusión definitiva.",
  ui_story_5081_50810901_32_dialog_content = "Cuanto más complejo es el juego, más difícil se vuelve, pero también contiene aún más caminos óptimos para su finalización.",
  ui_story_5081_50810901_33_dialog_content = "En cuanto a las puntuaciones en estas clasificaciones, no tengo forma de analizarlas en este momento.",
  ui_story_5081_50810901_34_dialog_content = "Solo puedo mirarlos con respeto.",
  ui_story_5081_50810901_35_dialog_content = "¡Eso es perfecto! Entonces... ¿Eso significa que todavía necesitas recopilar más datos del juego, verdad?",
  ui_story_5081_50810901_36_dialog_content = "¿Por qué no juegas con nosotros y ganas aún más experiencia?",
  ui_story_5081_50810901_37_dialog_content = "Por supuesto. Mis nuevas órdenes son observar a los aurorianos modernos en su vida cotidiana...",
  ui_story_5081_50810901_38_dialog_content = "Además de garantizar la seguridad de su futuro utilizando cualquier dato útil de la civilización antigua.",
  ui_story_5081_50810901_39_dialog_content = "Aliarme con los jugadores presentes sería una forma eficiente de llevar a cabo mis órdenes.",
  ui_story_5081_50810901_40_dialog_content = "Puedo comenzar en cualquier momento.",
  ui_story_5081_50810901_41_dialog_content = "¡Vamos, todos! ¡Divirtámonos!",
  ui_story_5081_50810902_1_dialog_content = "<color=#e8d9bb>Con la planificación de Batia, todos comienzan a jugar juegos contra No. 33.</color>",
  ui_story_5081_50810902_2_dialog_content = "<color=#e8d9bb>Con la excepción de Odi, quien logra ganar uno o dos partidos, No. 33 derrota a todos de manera impresionante.</color>",
  ui_story_5081_50810902_3_dialog_content = "<color=#e8d9bb>Sin embargo, Batia mantiene su título como la legendaria e invicta \"B\".</color>",
  ui_story_5081_50810902_4_dialog_content = "Gracias a todos. Los datos y observaciones que he recopilado hoy serán muy valiosos para mi investigación.",
  ui_story_5081_50810902_5_dialog_content = "Perdóneme, pero ¿puedo tomar prestados algunos juegos que requieren un análisis prolongado para completar?",
  ui_story_5081_50810902_6_dialog_content = "Creo que los datos ocultos dentro de estos juegos serán de gran beneficio para el futuro de todos los Aurorianos.",
  ui_story_5081_50810902_7_dialog_content = "Analizaré al máximo y haré que mis hallazgos estén disponibles para todos.",
  ui_story_5081_50810902_8_dialog_content = "¡Por supuesto! ¡Ven conmigo y te llevaré a ver mi colección! ¡Toma lo que creas que te ayudará!",
  ui_story_5081_50810902_9_dialog_content = "Elegiré sabiamente. Gracias por tu generosidad.",
  ui_story_5081_50810902_10_dialog_content = "No creo que te haya visto nunca tan emocionada, Batia...",
  ui_story_5081_50810902_11_dialog_content = "Oh, ¿e-en serio? ¿Es tan obvio?",
  ui_story_5081_50810902_12_dialog_content = "Sí, pero me siento exactamente igual que tú ahora mismo.",
  ui_story_5081_50810902_13_dialog_content = "Al final del día, los videojuegos son una excelente manera de unir a las personas y animarlas, ¿verdad?",
  ui_story_5081_50810902_14_dialog_content = "¿Quién sabe? Una vez que No. 33 analice los datos de esos juegos, tal vez sus hallazgos ayuden a la industria del juego a desarrollarse aún más.",
  ui_story_5081_50810902_15_dialog_content = "Incluso dijo que el futuro de todos los Aurorianos podría beneficiarse de tus juegos... Eso es bastante emocionante, ¿no es así?",
  ui_story_5081_50810902_16_dialog_content = "¡Realmente te gustan los videojuegos, PlayerName!",
  ui_story_5081_50810902_17_dialog_content = "Avanzar en los juegos y hacerlos más accesibles para el mundo... Eso es lo mejor que podría pedir.",
  ui_story_5081_50810902_18_dialog_content = "No puedo esperar a ver qué encuentra...",
  ui_story_5081_50810902_19_dialog_content = "He hecho mi elección. Cuando los resultados de mi investigación estén claros, te notificaré lo antes posible, señorita.",
  ui_story_5081_50810902_20_dialog_content = "¡B-Mejor de las suertes!",
  ui_story_5081_50810902_21_dialog_content = "Debo irme ahora. Adiós.",
  ui_story_5081_50810902_22_dialog_content = "A-Actualmente... ¿Podría preguntarte algo antes de que te vayas?",
  ui_story_5081_50810902_23_dialog_content = "Por todos los medios.",
  ui_story_5081_50810902_24_dialog_content = "Tiene que ver... con las personas que hicieron estos juegos, la civilización perdida de épocas pasadas...",
  ui_story_5081_50810902_25_dialog_content = "¿Puedes decirme en qué tipo de mundo vivían?",
  ui_story_5081_50810902_26_dialog_content = "¿Había... muchos juegos en su mundo? ¿Juegos que fueron desarrollados con más significados que solo para entretenimiento?",
  ui_story_5081_50810902_27_dialog_content = "...",
  ui_story_5081_50810902_28_dialog_content = "Era un mundo muy avanzado, pero también muy aterrador.",
  ui_story_5081_50810902_29_dialog_content = "\"¿Significados?\", preguntas?",
  ui_story_5081_50810902_30_dialog_content = "Lo siento, pero analizar estos datos no me proporcionará la respuesta que buscas.",
  ui_story_5081_50810902_31_dialog_content = "En este mundo, el significado de algo no es una constante inmutable.",
  ui_story_5081_50810902_32_dialog_content = "Para aquellos que tienen frío y hambre, cualquier cosa fuera de la comida y la ropa no tiene sentido.",
  ui_story_5081_50810902_33_dialog_content = "Para aquellos con almas vacías, las abundantes posesiones materiales también carecen de sentido.",
  ui_story_5081_50810902_34_dialog_content = "Pero en este lugar, los videojuegos son una fuente de disfrute, concentración y unidad. Eso los hace significativos.",
  ui_story_5081_50810902_35_dialog_content = "En lo que respecta a mis órdenes, la tecnología que beneficia a los lugareños también es significativa.",
  ui_story_5081_50810902_36_dialog_content = "Los videojuegos no son la excepción.",
  ui_story_5081_50810902_37_dialog_content = "Entonces... ¿Crees que son significativos?",
  ui_story_5081_50810902_38_dialog_content = "Sí. <color=#FFB400>En mi opinión</color>, son significativos.",
  ui_story_5081_50810902_39_dialog_content = "Y creo... que también deberías ver su significado especial <color=#FFB400>en tu opinión</color>.",
  ui_story_5081_50810902_40_dialog_content = "Ah...",
  ui_story_5081_50810902_41_dialog_content = "Sí, yo también lo creo.",
  ui_story_5081_50810902_42_dialog_content = "Los jugadores son los que dan sentido a los juegos, no los juegos en sí mismos.",
  ui_story_5081_50810902_43_dialog_content = "¡Lo más importante son las personas que pueden encontrar significado en los videojuegos!",
  ui_story_5081_50810902_44_dialog_content = "Ya sea aquellos que coleccionan juegos, observan las últimas tendencias o compran mercancía de juegos...",
  ui_story_5081_50810902_45_dialog_content = "¡Incluso fuiste capaz de convencer a Anatoli sobre la importancia de los videojuegos!",
  ui_story_5081_50810902_46_dialog_content = "¡Los videojuegos no distinguen entre ricos y pobres o buenos y malos. ¡Cualquiera puede encontrar significado al jugarlos!",
  ui_story_5081_50810902_47_dialog_content = "PlayerName...",
  ui_story_5081_50810902_48_dialog_content = "Si alguna vez te encuentras con alguien que describe las vidas o pasiones de otras personas como <color=#FFB400>sin sentido</color>...",
  ui_story_5081_50810902_49_dialog_content = "¡No dejes que nada de lo que digan te afecte! ¡A gente así no le importa el significado o valor de nada!",
  ui_story_5081_50810902_50_dialog_content = "Realmente admiro tu amor por los videojuegos, Batia. Solo desearía que no dudaras tanto de ti mismo.",
  ui_story_5081_50810902_51_dialog_content = "Por favor, sigue compartiendo tu amor por los juegos con otras personas. ¡Haz de tu sala de juegos un refugio seguro para jugadores de todo el mundo!",
  ui_story_5081_50810902_52_dialog_content = "Ah... ¡Ahhhh! ¡Ya lo entiendo! No hace falta que te pases, PlayerName!",
  ui_story_5081_50810902_53_dialog_content = "Jaja, ¡lo siento! Estaba un poco preocupado por ti, así que no pude evitar decir lo que pensaba...",
  ui_story_5081_50810902_54_dialog_content = "Gracias. Supongo que todos los que les gustan los videojuegos son así.",
  ui_story_5081_50810902_55_dialog_content = "Gronru también me dijo algo así una vez...",
  ui_story_5081_50810902_56_dialog_content = "Ya veo... En realidad estás bastante cerca de ella, ¿verdad?",
  ui_story_5081_50810902_57_dialog_content = "Sí... Eh, ¿PlayerName? Después de cerrar la sala de juegos por el día, tengo algunas cosas que contarte...",
  ui_story_5081_50811001_1_dialog_content = "¡Hora de cerrar! ¡Todos fuera! ¡Chirrido!",
  ui_story_5081_50811001_2_dialog_content = "Lo sé, ¡ahora cállate!",
  ui_story_5081_50811001_3_dialog_content = "¡Tsk! Comienzo a sentirme un poco inquieto. ¿Acaba de pasar una bola de sombras por la puerta?",
  ui_story_5081_50811001_4_dialog_content = "¿O fue una bola de llamas?",
  ui_story_5081_50811001_5_dialog_content = "<color=#e8d9bb>A medida que el sol se pone en el horizonte, los jugadores regresan lentamente a sus hogares en una ignorancia dichosa.</color>",
  ui_story_5081_50811001_6_dialog_content = "<color=#e8d9bb>Mientras tanto, una siniestra silueta se infiltra silenciosamente en este lugar de alegría y diversión.</color>",
  ui_story_5081_50811001_7_dialog_content = "<color=#e8d9bb>¿Puedes sentir el perturbador e ilusorio calor de su presencia?</color>",
  ui_story_5081_50811001_8_dialog_content = "La atmósfera se oscureció de repente aquí... ¿Eh? ¿Quién dejó este juego de terror encendido por aquí?",
  ui_story_5081_50811001_9_dialog_content = "Ah, lo siento, probablemente fui yo...",
  ui_story_5081_50811001_10_dialog_content = "Estaba buscando un juego para jugar en mi nido esta noche, así que podría haber dejado algunos encendidos.",
  ui_story_5081_50811001_11_dialog_content = "No le tienes miedo a este juego, ¿verdad PlayerName?",
  ui_story_5081_50811001_12_dialog_content = "No realmente, solo me sobresalté un poco cuando las líneas comenzaron a reproducirse de repente.",
  ui_story_5081_50811001_13_dialog_content = "Uh, ¿a qué te refieres con tu \"nido\"?",
  ui_story_5081_50811001_14_dialog_content = "¿Interesado? Eres libre de echarle un vistazo si quieres.",
  ui_story_5081_50811001_15_dialog_content = "Estar rodeado de montones de juegos y luces parpadeantes por la noche me hace sentir tan seguro y cálido...",
  ui_story_5081_50811001_16_dialog_content = "¡También tengo suficientes bocadillos y bebidas para durarme un mes entero!",
  ui_story_5081_50811001_17_dialog_content = "Ji ji ji...",
  ui_story_5081_50811001_18_dialog_content = "<color=#e8d9bb>Bajo el manto de la noche, caes en la desesperación de la nada.</color>",
  ui_story_5081_50811001_19_dialog_content = "<color=#e8d9bb>El aullido de las almas torturadas más allá de la tumba resuena en cada rincón de la oscuridad.</color>",
  ui_story_5081_50811001_20_dialog_content = "Ah...",
  ui_story_5081_50811001_21_dialog_content = "¿Escuchaste eso? Los efectos de sonido de este juego son realmente realistas...",
  ui_story_5081_50811001_22_dialog_content = "¡E-Eso no vino de mi juego!",
  ui_story_5081_50811001_23_dialog_content = "Ent-Entonces, ¿qué fue?",
  ui_story_5081_50811001_24_dialog_content = "No me digas que fue...",
  ui_story_5081_50811001_25_dialog_content = "Ah...",
  ui_story_5081_50811001_26_dialog_content = "¡Creo que viene de allí!",
  ui_story_5081_50811001_27_dialog_content = "¡P-Pero ahí es donde está mi nido!",
  ui_story_5081_50811001_28_dialog_content = "¡Oye, espera!",
  ui_story_5081_50811001_29_dialog_content = "¿Ahhhhhhh?",
  ui_story_5081_50811001_30_dialog_content = "¡Ahhhhhhh!",
  ui_story_5081_50811001_31_dialog_content = "¡Un fantasma! ¡Hay un fantasma acechando mi nido!",
  ui_story_5081_50811001_32_dialog_content = "¡Ahhhh! ¡PlayerName! ¡Odi! ¡Sork! ¡Bekk! ¡Alguien ayúdame!",
  ui_story_5081_50811001_33_dialog_content = "¡Nunca quiero volver a jugar otro juego de miedo nunca más!",
  ui_story_5081_50811001_34_dialog_content = "¡No te preocupes, ya voy!",
  ui_story_5081_50811001_35_dialog_content = "¿Eh? Uriel... ¿Eres tú?",
  ui_story_5081_50811001_36_dialog_content = "¡Crunch! Munch, munch... Glug, glug, glug...",
  ui_story_5081_50811001_37_dialog_content = "Ah. Los bocadillos no son nada especial, pero estas bebidas son bastante buenas...",
  ui_story_5081_50811001_38_dialog_content = "¡Oye! ¡No derrames nada en mis máquinas de juegos! Ahhh...",
  ui_story_5081_50811001_39_dialog_content = "Por favor, no soy tan torpe. Solo estoy... ayudándote a limpiarlos, eso es todo.",
  ui_story_5081_50811001_40_dialog_content = "Tales criaturas viles y sucias... con vidas tan carentes de sentido.",
  ui_story_5081_50811001_41_dialog_content = "Desaparece, desaparece, desaparece, desaparece—",
  ui_story_5081_50811001_42_dialog_content = "Desaparece junto a mí, otra existencia sin sentido...",
  ui_story_5081_50811001_43_dialog_content = "¿E-está tratando de deshacerse de mí en la vida real? ¡El desafío es solo para videojuegos!",
  ui_story_5081_50811001_44_dialog_content = "... Estoy bastante seguro de que eso no es lo que ella quiere decir...",
  ui_story_5081_50811001_45_dialog_content = "Resulta que ella es Uriel... ¡una de las Cuatro Ángeles de Lumopolis!",
  ui_story_5081_50811001_46_dialog_content = "¿Una persona famosa de Lumopolis? ¿Qu-Qué hace aquí?",
  ui_story_5081_50811001_47_dialog_content = "¡Ahhhh! ¡Está dejando migajas por todo mi teclado!",
  ui_story_5081_50811001_48_dialog_content = "Debo destruir este mundo... Debo quemarlo todo...",
  ui_story_5081_50811001_49_dialog_content = "¿Tienes alguna idea de cuánto tiempo he estado atrapado junto a esas existencias malditas?",
  ui_story_5081_50811001_50_dialog_content = "Desde el anochecer hasta el amanecer y de vuelta al anochecer, el calor nunca deja de aumentar, y yo nunca dejo de arrastrar esas almas miserables al infierno...",
  ui_story_5081_50811001_51_dialog_content = "Fue tan doloroso al principio, pero ahora... No siento nada, así que dejemos que todo arda...",
  ui_story_5081_50811001_52_dialog_content = "Ven conmigo y desciende al limbo del olvido...",
  ui_story_5081_50811001_53_dialog_content = "¡Está empezando a hacer mucho calor aquí!",
  ui_story_5081_50811001_54_dialog_content = "Uriel, ¡tienes que calmarte!",
  ui_story_5081_50811001_55_dialog_content = "¡Mi máquina de juegos... Va a quemarla hasta convertirla en cenizas! Mi archivo guardado... ¡no mi archivo guardado!",
  ui_story_5081_50811001_56_dialog_content = "No hay tiempo... ¡Solo tendremos que enfriarla y mover todo fuera de aquí!",
  ui_story_5081_50811001_57_dialog_content = "Odi! Sork! Bekk! ¡Denos una mano!",
  ui_story_5081_50811002_1_dialog_content = "¿Es eso todo? Uf, creo que logramos salvar la mayor parte...",
  ui_story_5081_50811002_2_dialog_content = "¿Necesitamos sacar algo más de la habitación?",
  ui_story_5081_50811002_3_dialog_content = "No, creo que estamos bien... Gracias a todos...",
  ui_story_5081_50811002_4_dialog_content = "En cuanto a esa máquina de juegos... simplemente déjala tenerla. No importa si la quema...",
  ui_story_5081_50811002_5_dialog_content = "Aunque Uriel parece realmente deprimida la mayor parte del tiempo, ¿me pregunto qué le habrá pasado?",
  ui_story_5081_50811002_6_dialog_content = "Quizás debería pedirle a Carleen que resuelva esto. Después de todo, Uriel todavía tiene un poco de miedo de su capitán.",
  ui_story_5081_50811002_7_dialog_content = "Carleen incluso podría ser capaz de enfriarla completamente...",
  ui_story_5081_50811002_8_dialog_content = "... Que extraño.",
  ui_story_5081_50811002_9_dialog_content = "¿Qué es extraño?",
  ui_story_5081_50811002_10_dialog_content = "Ella es una de las Cuatro Ángeles, lo que significa... probablemente ha eliminado a más Eclipsites que cualquier otro Aurorian, ¿verdad?",
  ui_story_5081_50811002_11_dialog_content = "Sí, supongo...",
  ui_story_5081_50811002_12_dialog_content = "Y sin embargo, aquí está, pasando el rato en una sala de juegos e intentando con todas sus fuerzas vencer a los Eclipsites en un videojuego...",
  ui_story_5081_50811002_13_dialog_content = "¿No debería una famosa guerrera de Lumopolis tener cosas más nobles que hacer con su tiempo?",
  ui_story_5081_50811002_14_dialog_content = "Ella definitivamente lo hace... Espera, déjame reformular eso.",
  ui_story_5081_50811002_15_dialog_content = "Cuando vences a los Eclipsites en un videojuego, generalmente obtienes algún tipo de recompensa, o te indica que superaste el nivel. Eso no siempre sucede en la vida real.",
  ui_story_5081_50811002_16_dialog_content = "Para una Angel deprimida, ¿quizás eso es lo que quiere?",
  ui_story_5081_50811002_17_dialog_content = "Ya veo... Supongo que todos tienen sus propias razones para querer jugar, ¿eh?",
  ui_story_5081_50811002_18_dialog_content = "Estoy seguro de que hay una razón más profunda detrás del comportamiento de Uriel, pero eso no es excusa para molestarte de esta manera.",
  ui_story_5081_50811002_19_dialog_content = "Solo le informaré a Carleen—",
  ui_story_5081_50811002_20_dialog_content = "¡Lo siento, todos!",
  ui_story_5081_50811002_21_dialog_content = "¡No puedo disculparme lo suficiente por todos los problemas que te hemos causado!",
  ui_story_5081_50811002_22_dialog_content = "¿Eh? ¿También estás aquí, PlayerName? ¡Genial! ¡Eso facilita mucho las cosas!",
  ui_story_5081_50811002_23_dialog_content = "¿Qué demonios...",
  ui_story_5081_50811002_24_dialog_content = "Ha habido muchos más Eclipsites en el área de lo habitual.",
  ui_story_5081_50811002_25_dialog_content = "Uriel fue enviado para exterminarlos y luchó contra ellos sin parar durante días seguidos...",
  ui_story_5081_50811002_26_dialog_content = "¡Es una trabajadora tan dura! Cuando finalmente fichó, todo lo que tenía que decir era—",
  ui_story_5081_50811002_27_dialog_content = "\"Dulce destrucción... Necesito ir a un lugar donde pueda limpiar verdaderamente a los Eclipsites...\" ¡Y luego simplemente desapareció de repente!",
  ui_story_5081_50811002_28_dialog_content = "Tuve que preguntar por todo Lumopolis y Umbraton antes de descubrir este lugar...",
  ui_story_5081_50811002_29_dialog_content = "Un lugar donde ella realmente podría limpiar a los Eclipsites... ¡Estaba hablando de los juegos en este arcade! Ah, ¡estoy tan celoso!",
  ui_story_5081_50811002_30_dialog_content = "¿Celoso?",
  ui_story_5081_50811002_31_dialog_content = "¿Ha estado Lumopolis realmente ocupado últimamente también?",
  ui_story_5081_50811002_32_dialog_content = "¡Sí! No hay días libres cuando tu trabajo es garantizar la seguridad de todos, después de todo...",
  ui_story_5081_50811002_33_dialog_content = "Pero parece que Uriel les causó algunos problemas, ¿eh?",
  ui_story_5081_50811002_34_dialog_content = "¿Alguien está herido? Si es así, ¡Lumopolis asumirá la responsabilidad de todos y cada uno de los daños!",
  ui_story_5081_50811002_35_dialog_content = "Así que no hay necesidad de hacer ningún informe desagradable sobre lo que sucedió aquí... ¿Okey?",
  ui_story_5081_50811002_36_dialog_content = "¡Sólo déjame la restauración de la tienda a mí!",
  ui_story_5081_50811002_37_dialog_content = "Jaj—",
  ui_story_5081_50811002_38_dialog_content = "Allá vamos-",
  ui_story_5081_50811002_39_dialog_content = "Oh—",
  ui_story_5081_50811002_40_dialog_content = "¡Y ahora es el momento... de lidiar con la parte más molesta!",
  ui_story_5081_50811002_41_dialog_content = "¿Eh? Oh, solo eres tú, Raphael...",
  ui_story_5081_50811002_42_dialog_content = "Me niego a volver con alguien que disfruta trabajando horas extras, así que simplemente—",
  ui_story_5081_50811002_43_dialog_content = "¿De qué estás hablando, Uriel? ¡Estoy aquí para ayudar a todos, no porque esté en horario de trabajo!",
  ui_story_5081_50811002_44_dialog_content = "Para evitar que molestes al público, no tengo más opción que arrastrarte de vuelta a Lumopolis. ¿Divertido, verdad?",
  ui_story_5081_50811002_45_dialog_content = "Pero aún no he terminado aquí... Todavía necesito quemar todo Astra...",
  ui_story_5081_50811002_46_dialog_content = "¡Hasta luego, PlayerName! Ah, y gracias por ser tan comprensiva, señorita!",
  ui_story_5081_50811002_47_dialog_content = "Sé que te causamos muchos problemas, pero permíteme decir que tienes una sala de juegos realmente maravillosa.",
  ui_story_5081_50811002_48_dialog_content = "¡Incluso un Auroriano como Uriel, que piensa que todo es insignificante, ama absolutamente este lugar!",
  ui_story_5081_50811002_49_dialog_content = "¡Seguro que volveré a jugar algún día también! ¡Adiós!",
  ui_story_5081_50811101_1_dialog_content = "... ¿Finalmente se han ido? ¡Apresúrate y cierra la puerta, Sork!",
  ui_story_5081_50811101_2_dialog_content = "No puedo creer que dos personas famosas aparecieron una tras otra. ¿Quién sigue, el Señor de la Ciudad mismo?",
  ui_story_5081_50811101_3_dialog_content = "...Probablemente no.",
  ui_story_5081_50811101_4_dialog_content = "Entonces, ¿tal vez Queen Bethlehem? Eso suena un poco más realista, ¿verdad?",
  ui_story_5081_50811101_5_dialog_content = "... No creo que ese sea el punto.",
  ui_story_5081_50811101_6_dialog_content = "No me importa quién aparezca, siempre y cuando no sea Sinsa. Si se entera de que me engañaron para trabajar aquí gratis...",
  ui_story_5081_50811101_7_dialog_content = "¡Seré el hazmerreír de Rediesel Wrench durante años!",
  ui_story_5081_50811101_8_dialog_content = "¡Décadas, incluso! ¡Chirrido!",
  ui_story_5081_50811101_9_dialog_content = "¡Dénle un respiro, chicos! ¡Están asustando a Batia!",
  ui_story_5081_50811101_10_dialog_content = "Oh...",
  ui_story_5081_50811101_11_dialog_content = "Me agradecieron antes de irse.",
  ui_story_5081_50811101_12_dialog_content = "¿Ah?",
  ui_story_5081_50811101_13_dialog_content = "Uriel... ¿Vino a mi arcade por su propia voluntad?",
  ui_story_5081_50811101_14_dialog_content = "¡Parece que sí! No tenía idea de que ella iba a las salas de juegos para desahogarse...",
  ui_story_5081_50811101_15_dialog_content = "¡Eso significa que tu tienda está haciendo una contribución significativa en la lucha contra los Eclipsites, Batia!",
  ui_story_5081_50811101_16_dialog_content = "No llegaría tan lejos. En cuanto a Uriel...",
  ui_story_5081_50811101_17_dialog_content = "Si podemos encontrarnos en circunstancias normales, podría ser capaz de recomendarle algunos juegos solo para ella.",
  ui_story_5081_50811101_18_dialog_content = "Pero hoy... Yo...",
  ui_story_5081_50811101_19_dialog_content = "¿Qué tal hoy?",
  ui_story_5081_50811101_20_dialog_content = "¡No creo haber visto nunca tantos clientes locos en un solo día!",
  ui_story_5081_50811101_21_dialog_content = "Sabía que esta preventa iba a atraer mucha atención de todo Astra...",
  ui_story_5081_50811101_22_dialog_content = "¡Pero nunca esperé ver a tantos clientes extraños y poderosos! ¡Algo no está bien en esto!",
  ui_story_5081_50811101_23_dialog_content = "¡Así que finalmente te has dado cuenta, pero ya es demasiado tarde!",
  ui_story_5081_50811101_24_dialog_content = "?",
  ui_story_5081_50811101_25_dialog_content = "Permití que los rumores sobre la legendaria \"B\" y su arcade se propagaran rápidamente a través de mi red de inteligencia...",
  ui_story_5081_50811101_26_dialog_content = "Y ahora, es hora de que coseche los frutos de mi trabajo.",
  ui_story_5081_50811101_27_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_5081_50811101_28_dialog_content = "Todos han sido rodeados, así que nadie se mueva.",
  ui_story_5081_50811101_29_dialog_content = "?",
  ui_story_5081_50811101_30_dialog_content = "La verdad a menudo se esconde bajo capas de oscuridad, pero a través de mi investigación, todo saldrá a la luz.",
  ui_story_5081_50811101_31_dialog_content = "Después de una larga investigación, finalmente he descubierto la verdad detrás de esta tienda y su verdadero dueño.",
  ui_story_5081_50811101_32_dialog_content = "Ya he solicitado la cooperación tanto del Señor Sombrío como del alguacil de Lumopolis—",
  ui_story_5081_50811101_33_dialog_content = "Por la sospecha de posesión de información clasificada, ¡por la presente declaro que los Hidden Fangs deben cerrar sus puertas en espera de una investigación adicional!",
  ui_story_5081_50811101_34_dialog_content = "¿Q-Quién te crees que eres? ¿Qué te da el derecho de hacer eso?",
  ui_story_5081_50811101_35_dialog_content = "<color=#e8d9bb>Chasquido—</color>",
  ui_story_5081_50811101_36_dialog_content = "Aquí está la orden oficial, firmada por cada uno de los organismos de gobierno involucrados en la investigación. ¿Necesito decir más?",
  ui_story_5081_50811101_37_dialog_content = "¡O-Oposición! Nunca hice algo así en absoluto... Lo juro...",
  ui_story_5081_50811101_38_dialog_content = "Tu objeción no hace ninguna diferencia. Después de todo, las <color=#FFB400>palabras</color> no significan nada en este lugar, ¿verdad?",
  ui_story_5081_50811101_39_dialog_content = "¡Solo un desafío servirá!",
  ui_story_5081_50811101_40_dialog_content = "¡Ahora solo espera un segundo!",
  ui_story_5081_50811101_41_dialog_content = "Sé que tienes una orden oficialmente firmada, y sé que debes haber trabajado realmente duro en esas líneas justo ahora...",
  ui_story_5081_50811101_42_dialog_content = "Pero, ¿qué diablos estás haciendo, Oficial de Inteligencia Yin—",
  ui_story_5081_50811101_43_dialog_content = "¡Ese no es mi nombre! ¡Soy el desafiante conocido como \"Y\"!",
  ui_story_5081_50811101_44_dialog_content = "¡Y logré entrar en esta sala de juegos justo antes de que cerrara sus puertas!",
  ui_story_5081_50811101_45_dialog_content = "El invicto \"B\" es el amo de este lugar, ¿verdad? No rechazarías mi desafío, ¿verdad?",
  ui_story_5081_50811101_46_dialog_content = "...",
  ui_story_5081_50811101_47_dialog_content = "No te preocupes, Batia, iré a hablar con ella. Después de todo, esto es parte de mi misión...",
  ui_story_5081_50811101_48_dialog_content = "De hecho, he oído que la Federación Illumina está preparada para movilizar toda su red de inteligencia continental para cazarla.",
  ui_story_5081_50811101_49_dialog_content = "Para ser franco, no. De hecho, uno podría decir que tenemos un poco de conflicto entre nosotros.",
  ui_story_5081_50811101_50_dialog_content = "<size=30>Últimamente se ha estado esforzando mucho, quizás más de lo necesario.</size>",
  ui_story_5081_50811101_51_dialog_content = "... Pero no te preocupes. Me aseguraré de que este asunto llegue a una conclusión satisfactoria.",
  ui_story_5081_50811101_52_dialog_content = "Entonces estaban hablando de ti todo este tiempo, Yingel!",
  ui_story_5081_50811101_53_dialog_content = "No es de extrañar que Beretta dijera que te vio afuera más temprano hoy... ¿Y qué pasa con esas gafas de sol?",
  ui_story_5081_50811101_54_dialog_content = "Esa mirada que sentí cuando aparecí por primera vez no era de Batia... ¡Eras tú!",
  ui_story_5081_50811101_55_dialog_content = "Entonces... ¿Qué harán con Gronru una vez que la encuentren? No la van a castigar, ¿verdad?",
  ui_story_5081_50811101_56_dialog_content = "¿Quién sabe? Después de todo, este no es mi campo de especialización.",
  ui_story_5081_50811101_57_dialog_content = "(... ¡La Federación Illumina envió a Yingel, el mejor de sus soldados, para cazar a Gronru!)",
  ui_story_5081_50811101_X57_dialog_content = "(¿No te preocupa esto? ¡¿No van a arrastrarte de vuelta a la fuerza, verdad?!)",
  ui_story_5081_50811101_58_dialog_content = "¿Qué pasa, \"B\"? Si te molesta tanto, ¡entonces simplemente acepta mi desafío!",
  ui_story_5081_50811101_59_dialog_content = "¡Acepto!",
  ui_story_5081_50811101_60_dialog_content = "¡Como dueño de esta sala de juegos, tengo que defenderla!",
  ui_story_5081_50811101_61_dialog_content = "Espera... No me digas que ustedes dos van a—",
  ui_story_5081_50811101_62_dialog_content = "¡Es hora de duelo!",
  ui_story_5081_50811102_1_dialog_content = "¿Esto es realmente todo lo que tienes? Esperaba más de la legendaria \"B.\"",
  ui_story_5081_50811102_2_dialog_content = "Tu vida es como una vela en el viento...",
  ui_story_5081_50811102_3_dialog_content = "¿Es eso lo que piensas?",
  ui_story_5081_50811102_4_dialog_content = "¡He estado preparando este movimiento de un solo turno solo para ti! ¿Estás listo para ello?",
  ui_story_5081_50811102_5_dialog_content = "Qué...",
  ui_story_5081_50811102_6_dialog_content = "<color=#e8d9bb>Whoosh, whoosh, whoosh—¡boom!</color>",
  ui_story_5081_50811102_7_dialog_content = "<size=45>¡No... Noooo!</size>",
  ui_story_5081_50811102_8_dialog_content = "La HP de Yingel se redujo a cero...",
  ui_story_5081_50811102_9_dialog_content = "En serio... ¡Ni siquiera tuve la oportunidad de comentar el partido!",
  ui_story_5081_50811102_10_dialog_content = "¡Estos dos no paraban de explicar sus movimientos en cada turno, como si fuera un aburrido juego de cartas!",
  ui_story_5081_50811102_11_dialog_content = "Jeje, ¡ese mandamiento probablemente no vale nada ahora!",
  ui_story_5081_50811102_12_dialog_content = "¡Espera, no hagas que parezca que vivimos en un mundo donde ganar un juego lo resuelve todo!",
  ui_story_5081_50811102_13_dialog_content = "¿Cómo puede ser? ¡Mi estrategia era perfecta! Te he estado observando en este lugar durante tanto tiempo...",
  ui_story_5081_50811102_14_dialog_content = "Tu estilo de juego, tus hábitos e incluso tus batallas contra todos esos desafiantes...",
  ui_story_5081_50811102_15_dialog_content = "¡No... Aún no ha terminado! ¡Me niego a aceptar la derrota!",
  ui_story_5081_50811102_16_dialog_content = "¡Dos de tres! ¡Esta competencia apenas está comenzando!",
  ui_story_5081_50811102_17_dialog_content = "Vaya... Yingel realmente está empezando a sonar como un villano de dibujos animados ahora.",
  ui_story_5081_50811102_18_dialog_content = "¡Por mí está bien! Para proteger mi arcade, te venceré tantas veces como sea necesario...",
  ui_story_5081_50811102_19_dialog_content = "¡Esto es lo que PlayerName y los demás me enseñaron sobre ser el dueño de este lugar!",
  ui_story_5081_50811102_20_dialog_content = "¡Es hora de duelo!",
  ui_story_5081_50811102_21_dialog_content = "¡Para ya—",
  ui_story_5081_50811102_22_dialog_content = "Perdón por la interrupción.",
  ui_story_5081_50811102_23_dialog_content = "Perdóname... por llegar tan tarde.",
  ui_story_5081_50811102_24_dialog_content = "Veo que la oficial Yingel ya está aquí. Por favor, perdóname por no haberla detenido antes.",
  ui_story_5081_50811102_25_dialog_content = "Está bien, llegaste en el momento justo! No es demasiado tarde para hacer que ella se eche atrás!",
  ui_story_5081_50811102_26_dialog_content = "Entendido.",
  ui_story_5081_50811102_27_dialog_content = "Oficial Yingel, hay más en esta misión de lo que originalmente pensábamos.",
  ui_story_5081_50811102_28_dialog_content = "La Oficial Técnica Gronru es un miembro importante de nuestro departamento de investigación... pero también es una persona muy temperamental.",
  ui_story_5081_50811102_29_dialog_content = "Ya he hablado tanto con el Oficial Migard como con el Comité.",
  ui_story_5081_50811102_30_dialog_content = "En lugar de intentar obligarla a regresar, es mejor que continuemos con nuestros propios deberes.",
  ui_story_5081_50811102_31_dialog_content = "Por el momento, por favor deje la investigación sobre el paradero del oficial Gronru a PlayerName. En cuanto a nosotros—",
  ui_story_5081_50811102_32_dialog_content = "¿Ya estás pidiendo refuerzos, eh?",
  ui_story_5081_50811102_33_dialog_content = "Solo una pequeña interrupción, nada más. Continuemos.",
  ui_story_5081_50811102_34_dialog_content = "¡Mi apelación a la razón cayó completamente en oídos sordos!",
  ui_story_5081_50811102_35_dialog_content = "Parece que tendré que actualizar mi información sobre el Oficial Yingel una vez más...",
  ui_story_5081_50811102_36_dialog_content = "No, Anatoli, definitivamente hiciste lo mejor que pudiste. Solo que ella no es la Oficial de Inteligencia Yingel en este momento, es la retadora conocida como \"Y\".",
  ui_story_5081_50811102_37_dialog_content = "¡Sé lo que realmente buscas, \"Y\"! ¡Por eso propongo que trabajemos juntos y completemos nuestra misión!",
  ui_story_5081_50811102_38_dialog_content = "!",
  ui_story_5081_50811102_39_dialog_content = "Anatoli ya me lo dijo. Has estado esforzándote mucho en el trabajo, ¿no?",
  ui_story_5081_50811102_40_dialog_content = "Cuando los líderes de la Federación Illumina te asignaron la búsqueda de Gronru, fue porque querían darte una tarea menos estresante.",
  ui_story_5081_50811102_41_dialog_content = "Pero al final, decidieron poner el trabajo en mis manos. Si me preguntas, ¡solo están complicando las cosas aún más!",
  ui_story_5081_50811102_42_dialog_content = "¡Por eso preferiría evitar cualquier conflicto innecesario y trabajar contigo para terminar la misión!",
  ui_story_5081_50811102_43_dialog_content = "...",
  ui_story_5081_50811102_44_dialog_content = "Sé que no quieres asociarte con nadie, pero apuesto a que no quieres que Illumina siga sin uno de sus mejores científicos por más tiempo, ¿verdad?",
  ui_story_5081_50811102_45_dialog_content = "... ¿Y qué te hace estar tan seguro de que encontraremos al Oficial Técnico si trabajamos juntos?",
  ui_story_5081_50811102_46_dialog_content = "Toda mi inteligencia apuntaba a que ella estaría en esta ubicación exacta.",
  ui_story_5081_50811102_47_dialog_content = "Aún así, no vi ninguna señal de ella, incluso después de todo este tiempo... Así que pensé que al derrotar a \"B\", podría obligarla a revelar el paradero de Gronru.",
  ui_story_5081_50811102_48_dialog_content = "¿Eres capaz de vencerla, PlayerName? Si no, solo puedo confiar en mí mismo...",
  ui_story_5081_50811102_49_dialog_content = "¿Batia? ¿Qué opinas de Yingel como jugador?",
  ui_story_5081_50811102_50_dialog_content = "¿Te refieres a ella? La verdad es que la encuentro bastante interesante. Parece que también disfruta mucho de los juegos...",
  ui_story_5081_50811102_51_dialog_content = "Y ella sabe cómo producir algunas estrategias de muy alto nivel, incluso si se deja llevar por ellas... Creo que es una gran jugadora.",
  ui_story_5081_50811102_52_dialog_content = "¿C-Caído en el exceso? ¿Es esa tu opinión sobre mí?",
  ui_story_5081_50811102_53_dialog_content = "No, eso no es correcto... Estás hablando del desafiante conocido como \"Y\", pero...",
  ui_story_5081_50811102_54_dialog_content = "Tu oponente es ahora el Oficial de Inteligencia Yingel. Por favor, no me pongas al mismo nivel que el último desafiante.",
  ui_story_5081_50811102_55_dialog_content = "Ahora que Batia ha reconocido las habilidades de Yingel, creo que es seguro para mí preguntar ahora.",
  ui_story_5081_50811102_56_dialog_content = "Gronru en realidad está escondiéndose en algún lugar aquí, ¿no es así?",
  ui_story_5081_50811102_57_dialog_content = "Oh... Lo siento mucho, Gronru...",
  ui_story_5081_50811102_58_dialog_content = "Sí... Eso es la verdad.",
  ui_story_5081_50811102_59_dialog_content = "Mientras solo sean ustedes dos...",
  ui_story_5081_50811102_60_dialog_content = "Estoy seguro de que no le importará reunirse contigo. Por aquí, por favor.",
  ui_story_5081_50811201_1_dialog_content = "Está un poco oscuro... Por favor, no te quedes demasiado atrás.",
  ui_story_5081_50811201_2_dialog_content = "Nunca esperé que hubiera un túnel debajo de este lugar.",
  ui_story_5081_50811201_3_dialog_content = "Mis informes de inteligencia no mencionaban nada sobre un pasadizo oculto...",
  ui_story_5081_50811201_4_dialog_content = "Gronru se tomó muchas molestias para ocultar este lugar. Tiene sentido que no supieras de su existencia...",
  ui_story_5081_50811201_5_dialog_content = "Aquí estamos... Bienvenidos al estudio subterráneo de Gronru.",
  ui_story_5081_50811201_6_dialog_content = "Es su espacio privado donde puede analizar y restaurar juegos recientemente excavados de antiguas civilizaciones.",
  ui_story_5081_50811201_7_dialog_content = "¿Un estudio de videojuegos? ¿Eso significa—",
  ui_story_5081_50811201_8_dialog_content = "Tenías razón al suponer que Gronru estaba aquí todo el tiempo, PlayerName... pero por diferentes razones.",
  ui_story_5081_50811201_9_dialog_content = "Ella no vino aquí para comprar una copia del juego de fantasía en preventa, porque ella es la que lo restauró en primer lugar.",
  ui_story_5081_50811201_10_dialog_content = "En otras palabras...",
  ui_story_5081_50811201_11_dialog_content = "Ella es la verdadera dueña de Hidden Fangs, una veterana jugadora que me apoya en la administración de esta sala de juegos.",
  ui_story_5081_50811201_12_dialog_content = "Entonces mis informes de inteligencia eran correctos, esta realmente es su base secreta.",
  ui_story_5081_50811201_13_dialog_content = "Eludiendo sus cruciales deberes como oficial de Illumina para reparar viejos videojuegos...",
  ui_story_5081_50811201_14_dialog_content = "¡No puedo pensar en algo más egoísta que hacer! Illumina está en medio de—",
  ui_story_5081_50811201_15_dialog_content = "¿En medio de qué?",
  ui_story_5081_50811201_16_dialog_content = "Dale un respiro, Yingel. Si PlayerName no hubiera ganado el favor de Batia, ¡te habría llevado otro año encontrar este lugar!",
  ui_story_5081_50811201_17_dialog_content = "¿Ganó mi favor? Ni siquiera se acerca a la mitad de hacer eso...",
  ui_story_5081_50811201_18_dialog_content = "¡Espera un minuto! No soy un NPC o algo así... Por favor, no bromees así, Gronru!",
  ui_story_5081_50811201_19_dialog_content = "Es solo que... Parecían tener algo realmente importante que decirte, así que los traje aquí.",
  ui_story_5081_50811201_20_dialog_content = "Después de todo, ellos son tus amigos y compañeros de trabajo...",
  ui_story_5081_50811201_21_dialog_content = "¡Eso no significa nada! ¿No te dije que no dejaras entrar a nadie aquí hasta que terminaran mis vacaciones?",
  ui_story_5081_50811201_22_dialog_content = "... P-Pero dijiste \"con la excepción de jugadores especialmente interesantes\"...",
  ui_story_5081_50811201_23_dialog_content = "\"¿Jugadores especialmente interesantes\"? No estás hablando de PlayerName y Yingel, ¿verdad?",
  ui_story_5081_50811201_24_dialog_content = "¿Realmente crees que esos dos tienen alguna oportunidad contra el cerebro secreto detrás de los Hidden Fangs?",
  ui_story_5081_50811201_25_dialog_content = "<color=#e8d9bb>Estruendo...</color>",
  ui_story_5081_50811201_26_dialog_content = "Nos están subestimando, PlayerName.",
  ui_story_5081_50811201_27_dialog_content = "Sí... Pero no vinimos aquí para desafiar a ningún \"genio secreto\" en primer lugar!",
  ui_story_5081_50811201_28_dialog_content = "Eso ya no importa. Ahora no podemos evitar esta batalla.",
  ui_story_5081_50811201_29_dialog_content = "Oficial Técnico Gronru, ¿tienes idea de cuánto caos ha causado tu ausencia en Illumina?",
  ui_story_5081_50811201_30_dialog_content = "Urgh, qué dolor...",
  ui_story_5081_50811201_31_dialog_content = "¡No me digas que la última arma anti-Eclipsite empezó a fallar de nuevo! Si ese es el caso, ¡entonces usa algo más!",
  ui_story_5081_50811201_32_dialog_content = "¡Mis viejas armas pueden hacer el trabajo muy bien!",
  ui_story_5081_50811201_33_dialog_content = "¿O es que el Comité todavía no ha limpiado su propio desorden?",
  ui_story_5081_50811201_34_dialog_content = "Siempre alargando las reuniones con sus discursos melodramáticos y llenos de autoimportancia... ¿Acaso todos tiran su cerebro por la ventana cuando llegan a la cima o qué?",
  ui_story_5081_50811201_35_dialog_content = "¿O tal vez algunos científicos de laboratorio discuten sobre qué proyectos seguir y cuáles desechar de nuevo?",
  ui_story_5081_50811201_36_dialog_content = "¡Cualquier proyecto que no pase la inspección se descarta sin pensarlo dos veces, aunque todo lo que necesitan es un poco más de apoyo! ¡Me enfada mucho!",
  ui_story_5081_50811201_37_dialog_content = "Su estado mental...",
  ui_story_5081_50811201_38_dialog_content = "Es incluso peor que el de Uriel, ¿no es así?",
  ui_story_5081_50811201_39_dialog_content = "Aunque no puedas asumir la responsabilidad de todas esas cosas, eso no es excusa para abandonar tu puesto sin aprobación—",
  ui_story_5081_50811201_40_dialog_content = "¿Quién dice que no obtuve la aprobación? ¡Presenté mi solicitud de tiempo de vacaciones! ¡Y yo mismo lo aprobé!",
  ui_story_5081_50811201_41_dialog_content = "¡Incluso puse avisos de mi tiempo libre por toda mi oficina! ¡No me digas que no los viste!",
  ui_story_5081_50811201_42_dialog_content = "¡Urghhhh, eso es todo! No voy a dejar que ninguno de ustedes arruine mi juego de Longzhou Tilemaster—",
  ui_story_5081_50811201_43_dialog_content = "¡Si quieres que vuelva a la oficina, tendrás que arrastrar mi frío y muerto cuerpo hasta allí!",
  ui_story_5081_50811201_44_dialog_content = "¿Maestro de azulejos de Longzhou? Creo que he oído hablar de ese juego. Es algo así como el mahjong...",
  ui_story_5081_50811201_45_dialog_content = "¿Eh? Pero pensé que estabas terminando tu trabajo en el juego de fantasía, Gronru? ¿Por qué pusiste pausa a eso?",
  ui_story_5081_50811201_46_dialog_content = "Hmm... ¡N-No importa! Nadie tiene permitido molestarme ahora mismo, ¿me oyes? ¡Nadie!",
  ui_story_5081_50811201_47_dialog_content = "¡Que comience el juego de Gronru!",
  ui_story_5081_50811201_48_dialog_content = "... Sabía que terminaría así.",
  ui_story_5081_50811201_49_dialog_content = "¡Consíguelo, Peng-Peng!",
  ui_story_5081_50811201_50_dialog_content = "\"¿Peng-Peng\"? ... Oh, te refieres a este pequeño.",
  ui_story_5081_50811201_51_dialog_content = "¡Aún no he terminado! Fija tus ojos en esto: Todo Verde, Cuatro Bendiciones y Nueve Linternas de Loto!",
  ui_story_5081_50811201_52_dialog_content = "¡Oye... Espera solo un segundo! ¿Cómo se supone que voy a seguir eso?",
  ui_story_5081_50811201_53_dialog_content = "¡He entrado al juego! ¡Resiste, PlayerName!",
  ui_story_5081_50811201_54_dialog_content = "¡También estoy en posición!",
  ui_story_5081_50811201_55_dialog_content = "Honestamente... ¿Qué tipo de persona nombra a los Eclipsites después de un movimiento en el mahjong?",
  ui_story_5081_50811201_56_dialog_content = "¿Quién más sino el gran Gronru, maestro de todas las formas de mahjong!",
  ui_story_5081_50811201_57_dialog_content = "¡Todos los que se atrevan a desafiarme serán aplastados bajo el colosal peso de mis fichas!",
  ui_story_5081_50811201_58_dialog_content = "¿Viniste a desafiarme, verdad? ¡Entonces adelante, los tres! Les mostraré a todos ustedes—",
  ui_story_5081_50811201_59_dialog_content = "¡Que yo, Gronkenstein Ruu, soy el verdadero e invicto jugador conocido como \"B\"!",
  ui_story_5081_50811201_60_dialog_content = "La \"B\" significa \"jefe\", como en el jefe final!",
  ui_story_5081_50811300_1_dialog_content = "<color=#e8d9bb>Y así el invencible Gronru es finalmente derrotado.</color>",
  ui_story_5081_50811300_2_dialog_content = "Uf... Eso estuvo cerca. Gronru casi nos vence.",
  ui_story_5081_50811300_3_dialog_content = "Tener a un jugador tan poderoso como Batia en nuestro equipo es extremadamente tranquilizador.",
  ui_story_5081_50811300_4_dialog_content = "Créeme, todos jugaron lo mejor que pudieron ahora mismo. Sin ustedes... nunca podría haber vencido a Gronru...",
  ui_story_5081_50811300_5_dialog_content = "¿Vencido a mí? ¡En tus sueños! ¡Gronkenstein Ruu nunca puede ser derrotado!",
  ui_story_5081_50811300_6_dialog_content = "¡Esa fue solo mi primera forma! Todavía me quedan dos formas, ¡cada una el doble de fuerte que la anterior!",
  ui_story_5081_50811300_7_dialog_content = "Aaaaaahhhh—",
  ui_story_5081_50811300_8_dialog_content = "Espera, Gronru... Estás usando códigos de trucos ahora, ¿no es así?",
  ui_story_5081_50811300_9_dialog_content = "¡Eso no es justo en absoluto!",
  ui_story_5081_50811300_10_dialog_content = "\"¿Justo\"? ¡Esa palabra no existe en ningún lugar de Astra!",
  ui_story_5081_50811300_11_dialog_content = "¡Las trampas son solo otra parte del Juego de Gronru! Si no te gusta, ¡entonces sal!",
  ui_story_5081_50811300_12_dialog_content = "Haaaaaahhhh—",
  ui_story_5081_50811300_13_dialog_content = "Espera... ¿Realmente está usando trucos?",
  ui_story_5081_50811300_14_dialog_content = "¿Por qué toda la habitación tiembla como si fuera a autodestruirse?",
  ui_story_5081_50811300_15_dialog_content = "¿Está sobrecargando la máquina de juegos al usar demasiados trucos?",
  ui_story_5081_50811300_16_dialog_content = "Cada pieza de equipo en esta sala está interconectada...",
  ui_story_5081_50811300_17_dialog_content = "G-Gronru! Si esto continúa, ¡toda la sala de juegos explotará!",
  ui_story_5081_50811300_18_dialog_content = "Entonces déjalo explotar... Prefiero que eso suceda en lugar de perder contra ti y tener que volver a trabajar!",
  ui_story_5081_50811300_19_dialog_content = "¿Por qué debería lidiar con toda la secuela cuando nada de esto fue mi culpa?",
  ui_story_5081_50811300_20_dialog_content = "¡Al diablo con sus reglas injustas! ¡Solo están creando más trabajo para mí para cubrir sus propios errores!",
  ui_story_5081_50811300_21_dialog_content = "¡Esos tontos altaneros nunca podrían entender! ¡La única razón por la que trabajamos es para disfrutar adecuadamente de los juegos en nuestro tiempo libre!",
  ui_story_5081_50811300_22_dialog_content = "Un Astra donde no puedo jugar a los videojuegos a mi antojo... está destinado a desaparecer, junto con mi tercera forma—",
  ui_story_5081_50811300_23_dialog_content = "<color=#e8d9bb>Bip-</color>",
  ui_story_5081_50811300_24_dialog_content = "?",
  ui_story_5081_50811300_25_dialog_content = "¿El temblor se detuvo?",
  ui_story_5081_50811300_26_dialog_content = "Sí. Necesitábamos sacarla de eso, así que corté la energía de sus máquinas.",
  ui_story_5081_50811300_27_dialog_content = "No me culpas, ¿verdad Gronru? Además, siempre activas el guardado automático en tus juegos...",
  ui_story_5081_50811300_28_dialog_content = "¡Ya no me importan mis datos guardados! ¡No volveré, ni siquiera si estoy muerto!",
  ui_story_5081_50811300_29_dialog_content = "Eres tan patético sin tus trampas, Gronru.",
  ui_story_5081_50811300_30_dialog_content = "¡Eso es gracioso viniendo de ti, Yingel! ¿No te acaba de llevar Batia? ¡Incluso sin trampas, nunca tendrías oportunidad contra mí en un enfrentamiento uno a uno!",
  ui_story_5081_50811300_31_dialog_content = "Quizás, pero aún así gané... ¡Todos lo hicimos!",
  ui_story_5081_50811300_32_dialog_content = "Asqueroso... ¡Te maldigo!",
  ui_story_5081_50811300_33_dialog_content = "¡Deténganlo, ambos! No los traje para desafiarte, Gronru! Es solo que...",
  ui_story_5081_50811300_34_dialog_content = "Noté que no te ha ido tan bien últimamente... pero no sabía cómo ayudarte...",
  ui_story_5081_50811300_35_dialog_content = "Después de todo... No tengo idea de lo que piensan tus líderes.",
  ui_story_5081_50811300_36_dialog_content = "Pero creo que está bien si no te gustan, ¡Gronru!",
  ui_story_5081_50811300_37_dialog_content = "¡Por eso... quería traerte a algunas de las personas que podrían gustarte!",
  ui_story_5081_50811300_38_dialog_content = "¿Yo?",
  ui_story_5081_50811300_39_dialog_content = "¿Ella?",
  ui_story_5081_50811300_40_dialog_content = "¡N-No me mires!",
  ui_story_5081_50811300_41_dialog_content = "¡Así es! Después de jugar con ellos y contra ellos, puedo decir que tienen una verdadera pasión por los videojuegos!",
  ui_story_5081_50811300_42_dialog_content = "Y a diferencia de mí... ellos no se encierran en sus habitaciones todos los días. Son tus colegas, así como tus amigos.",
  ui_story_5081_50811300_43_dialog_content = "Por eso creo que son mejores entendiendo tus problemas que yo.",
  ui_story_5081_50811300_44_dialog_content = "Batia...",
  ui_story_5081_50811300_45_dialog_content = "Entonces, ¿podrías considerar esto como si yo estuviera organizando una convención de juegos improvisada en Hidden Fangs?",
  ui_story_5081_50811300_46_dialog_content = "Espero que esto te dé la oportunidad de compartir tus problemas con nosotros... ¡para que podamos encontrar juntos una forma de avanzar!",
  ui_story_5081_50811300_47_dialog_content = "*olfatea*",
  ui_story_5081_50811300_48_dialog_content = "Waaaaaaaaah—",
  ui_story_5081_50811300_49_dialog_content = "¡No soporto esas reuniones odiosas ni las montañas de informes que siempre tengo que escribir!",
  ui_story_5081_50811300_50_dialog_content = "Nunca hay suficiente tiempo para jugar juegos, mucho menos para restaurarlos... ¡Por eso decidí esconderme aquí!",
  ui_story_5081_50811300_51_dialog_content = "Tenía la intención de terminar mi trabajo en ese juego de fantasía lo más pronto posible, pero estaba de tan mal humor que no pude hacer ningún progreso...",
  ui_story_5081_50811300_52_dialog_content = "Así que pensé, \"Tal vez un juego de Longzhou Tilemaster me ayude a relajarme un poco...\"",
  ui_story_5081_50811300_53_dialog_content = "¡Pero una vez que empecé a jugar, no pude soltar el controlador!",
  ui_story_5081_50811300_54_dialog_content = "Me dije a mí mismo que pararía después de llegar al octavo rango, pero luego seguí hasta el noveno rango, y luego el décimo...",
  ui_story_5081_50811300_55_dialog_content = "Tuve una terrible suerte todo el tiempo, por lo que me llevó una eternidad hacer algún progreso... Y ahora el lanzamiento del juego de fantasía está a la vuelta de la esquina...",
  ui_story_5081_50811300_56_dialog_content = "¡De ninguna manera llegaré a tiempo ahora!",
  ui_story_5081_50811300_57_dialog_content = "¡Mi trabajo aún no está terminado! ¡El juego aún no está terminado! ¡No he terminado ni una sola cosa!",
  ui_story_5081_50811300_58_dialog_content = "*sollozando* ¿Por qué la vida tiene que ser tan dura? Ya no quiero jugar más—",
  ui_story_5081_50811300_59_dialog_content = "PlayerName! ¡Tienes que ayudarme a borrarme del mundo!",
  ui_story_5081_50811300_60_dialog_content = "¡O-Oye! ¡No digas cosas aterradoras como esa!",
  ui_story_5081_50811300_61_dialog_content = "Este mundo te necesita, Gronru! Además, la vida nunca ha sido un juego para un solo jugador...",
  ui_story_5081_50811300_62_dialog_content = "¿Por qué no nos dejas jugar contigo?",
  ui_story_5081_50811300_63_dialog_content = "Si enfrentamos juntos esta etapa llamada vida, ¡estoy seguro de que podemos superarla con creces! ¡Sería mucho más divertido que hacerlo solo, al menos!",
  ui_story_5081_50811300_64_dialog_content = "En cuanto a la tortura redundante, innecesaria y estresante en Illumina...",
  ui_story_5081_50811300_65_dialog_content = "... Quiero decir, en cuanto a tu trabajo, estoy seguro de que Anatoli y yo podemos ayudarte a optimizar algunos de esos procesos.",
  ui_story_5081_50811300_66_dialog_content = "Y cuando se trata de restaurar videojuegos, ¡Odi definitivamente sabe lo suyo!",
  ui_story_5081_50811300_67_dialog_content = "¡Quizás No. 33 también pueda ayudar!",
  ui_story_5081_50811300_68_dialog_content = "En cuanto a mí... No soy bueno en nada aparte de los videojuegos, ¡pero siempre puedes pedirme que sea tu probador!",
  ui_story_5081_50811300_69_dialog_content = "No solo eres bueno en los videojuegos, Batia.",
  ui_story_5081_50811300_70_dialog_content = "Todos somos jugadores aquí, pero tú tienes algo especial que nadie más tiene...",
  ui_story_5081_50811300_71_dialog_content = "¡Eso son los Colmillos Ocultos, el destino final para los jugadores de todo el mundo! ¡Sin mencionar tu reputación como el legendario jugador \"B\"!",
  ui_story_5081_50811300_72_dialog_content = "¡Solo piensa en todos los retadores a los que derrotaste para proteger tu arcade hoy!",
  ui_story_5081_50811300_73_dialog_content = "Yo...",
  ui_story_5081_50811300_74_dialog_content = "Batia... Oh, Batiaaaa—",
  ui_story_5081_50811300_75_dialog_content = "V-Va a estar bien, Gronru! No llores...",
  ui_story_5081_50811300_76_dialog_content = "¡Ya has crecido! Has pasado de ser una pequeña niña tranquila a una gerente de arcade confiable!",
  ui_story_5081_50811300_77_dialog_content = "Parece que los discursos de PlayerName son tan efectivos como siempre...",
  ui_story_5081_50811300_78_dialog_content = "C-Como dije, ¡no soy un NPC!",
  ui_story_5081_50811300_79_dialog_content = "¡Pero realmente eres increíble! ¡Manejaste tantos problemas tú solo!",
  ui_story_5081_50811300_80_dialog_content = "¡Incluso manejaste a alguien tan enfurecedor como Yingel!",
  ui_story_5081_50811300_81_dialog_content = "?",
  ui_story_5081_50811300_82_dialog_content = "Creo que tendré que desafiarte de nuevo solo para mostrarte lo <color=#FFB400>irritante</color> que realmente puedo ser, Oficial de Tecnología Gronru.",
  ui_story_5081_50811300_83_dialog_content = "Oh, ¿así que quieres seguir jugando?",
  ui_story_5081_50811300_84_dialog_content = "Para nada. Solo estoy lanzando un desafío.",
  ui_story_5081_50811300_85_dialog_content = "Jejeje, parece que los videojuegos realmente pueden hacer que cualquier cosa suceda... ¡Me siento mucho mejor después de todo lo que ha pasado hoy!",
  ui_story_5081_50811300_86_dialog_content = "¿Ustedes todavía quieren desafiarme? Estoy dispuesto, pero solo necesito algo de tiempo primero.",
  ui_story_5081_50811300_87_dialog_content = "¡Quiero ir a terminar mi trabajo en ese juego de fantasía ahora mismo! Después de eso, todos pueden ser mis valiosos probadores para mi último trabajo!",
  ui_story_5081_50811300_88_dialog_content = "¡Esta es tu única oportunidad para desafiar al verdadero jefe final!",
  ui_story_5081_50811300_89_dialog_content = "¡Porque después de que regrese a Illumina, este logro no estará disponible en la versión oficial!",
  ui_story_5081_50811300_90_dialog_content = "¡Veremos si tienes lo que se necesita para desbloquearlo en primer lugar!",
  ui_story_5081_50811300_91_dialog_content = "¿Entonces está decidido? ¿Finalmente vas a regresar a Illumina?",
  ui_story_5081_50811300_92_dialog_content = "... ¡Humph!",
  ui_story_5081_50811300_93_dialog_content = "¿Eh? ¿A dónde vas, Yingel?",
  ui_story_5081_50811300_94_dialog_content = "¿Realmente necesitas preguntar? Voy a hacer un último entrenamiento antes de que termine de restaurar el juego.",
  ui_story_5081_50811300_95_dialog_content = "No pararé hasta vencerla tan mal que decida renunciar a los juegos y volver al trabajo para siempre.",
  ui_story_5081_50811300_96_dialog_content = "Oh... G-Buena suerte con eso...",
  ui_story_5081_50811300_97_dialog_content = "¿Y tú, Batia?",
  ui_story_5081_50811300_98_dialog_content = "Si te parece bien, me gustaría elegir algunos de estos juegos para jugar contigo, PlayerName.",
  ui_story_5081_50811300_99_dialog_content = "¡Oh, está bien! Estos son de tu gallinero, ¿verdad?",
  ui_story_5081_50811300_100_dialog_content = "Veamos... ¿Álbum de Noche Blanca 2, eh? ¿Por qué no reproducimos este?",
  ui_story_5081_50811300_101_dialog_content = "Um... Está bien.",
  ui_story_5081_50811300_102_dialog_content = "Algo me dice que serás realmente bueno en este juego. Veamos qué decisiones tomas...",
  ui_story_5081_50811300_103_dialog_content = "¡Seguro! ¡Vamos a arrancarlo!",
  ui_story_5081_50811300_104_dialog_content = "¿Realmente es el momento de relajarnos así? Pronto desafiaremos a Gronru de nuevo, ¿recuerdas?",
  ui_story_5081_50811300_105_dialog_content = "¡Solo estamos jugando videojuegos, Yingel! Además, ¿quién dice que este juego va a ser fácil? ¡Ven y compruébalo por ti mismo!",
  ui_story_5081_50811300_106_dialog_content = "<color=#e8d9bb>Y así, mientras Gronru pone los toques finales a su nuevo juego, el resto de nosotros también nos sentamos a su alrededor y jugamos juegos...</color>",
  ui_story_5081_50811300_107_dialog_content = "<color=#e8d9bb>Juntos, tenemos una noche de disfrute simple y puro en la compañía del otro.</color>",
  ui_story_5081_50811300_108_dialog_content = "¡La espera finalmente terminó, todos! May ¡Les presento el juego de fantasía que hará que todo Astra se vuelva loco!",
  ui_story_5081_50811300_109_dialog_content = "Como sus primeros tres jugadores, ¡espero que todos estén listos!",
  ui_story_5081_50811300_110_dialog_content = "Mi rifle de francotirador está cansado de esperar.",
  ui_story_5081_50811300_111_dialog_content = "Je, entonces parece que puedo configurarlo en la dificultad más difícil posible!",
  ui_story_5081_50811300_112_dialog_content = "¿Qué hay de ustedes dos?",
  ui_story_5081_50811300_113_dialog_content = "¡Estoy listo!",
  ui_story_5081_50811300_114_dialog_content = "¡Haré mi mejor esfuerzo también!",
  ui_story_5081_50811300_115_dialog_content = "¡Bien, entonces que comience la cuenta regresiva! ¡Tres! ¡Dos! ¡Uno!",
  ui_story_5081_50811300_116_dialog_content = "¡Empezar juego!"
}
return config
